window.SBF_DATEN = {"stand":"ELWIS-Fragenkatalog SBF-Binnen, Stand 01.08.2023","themen":[{"id":"recht","name":"Recht & Führerschein"},{"id":"fahrregeln","name":"Fahr- & Ausweichregeln"},{"id":"lichter","name":"Lichter & Sichtzeichen"},{"id":"zeichen","name":"Schifffahrtszeichen & Tonnen"},{"id":"schleuse","name":"Schleusen & Brücken"},{"id":"schall","name":"Schall- & Notsignale"},{"id":"gewaesser","name":"Fahrwasser & Hochwasser"},{"id":"seemannschaft","name":"Seemannschaft & Anlegen"},{"id":"motor","name":"Motor & Antrieb"},{"id":"sicherheit","name":"Sicherheit an Bord"},{"id":"umwelt","name":"Umweltschutz"},{"id":"wetter","name":"Wetter & Sicht"},{"id":"wassersport","name":"Wasserski & Wassermotorrad"},{"id":"boot","name":"Bootskunde & Stabilität"},{"id":"segel","name":"Segel, Tauwerk & Wind"},{"id":"trimm","name":"Segeltrimm"},{"id":"segelmanoever","name":"Segelmanöver & Notfälle"}],"fragen":[{"nr":1,"teil":"basis","thema":"recht","frage":"Was ist zu tun, wenn vor Antritt der Fahrt nicht feststeht, wer Schiffsführer ist?","inline":[],"bilder":[],"antworten":["Der verantwortliche Schiffsführer muss bestimmt werden.","Der verantwortliche Schiffsführer muss gewählt werden.","Ein Inhaber eines Sportbootführerscheins muss die Fahrzeugführung übernehmen.","Ein Inhaber eines Sportbootführerscheins muss die Verantwortung übernehmen."],"erklaerung":"An Bord muss immer klar sein, wer verantwortlich ist. Steht das nicht fest, wird der Schiffsführer vor der Fahrt bestimmt. Gewählt wird er nicht, und der Besitz eines Führerscheins allein macht noch niemanden zum Schiffsführer.","stichworte":["Schiffsführer bestimmen","vor Fahrtantritt","Verantwortung"]},{"nr":2,"teil":"basis","thema":"recht","frage":"In welchen Fällen darf weder ein Sportboot geführt noch dessen Kurs oder Geschwindigkeit selbstständig bestimmt werden?","inline":[],"bilder":[],"antworten":["Wenn man infolge körperlicher oder geistiger Mängel oder infolge des Genusses alkoholischer Getränke oder anderer berauschender Mittel in der sicheren Führung behindert ist oder wenn eine Blutalkoholkonzentration von 0,5 ‰ oder mehr im Körper vorhanden ist.","Wenn man infolge körperlicher oder geistiger Mängel oder infolge des Genusses alkoholischer Getränke oder anderer berauschender Mittel in der sicheren Führung behindert ist oder wenn eine Blutalkoholkonzentration von 0,8 ‰ oder mehr im Körper vorhanden ist.","Wenn man infolge körperlicher oder geistiger Mängel oder infolge des Genusses alkoholischer Getränke oder anderer berauschender Mittel in der sicheren Führung behindert ist oder wenn eine Blutalkoholkonzentration von 1,0 ‰ oder mehr im Körper vorhanden ist.","Wenn man infolge körperlicher oder geistiger Mängel oder infolge des Genusses alkoholischer Getränke oder anderer berauschender Mittel in der sicheren Führung behindert ist oder wenn eine Blutalkoholkonzentration von 0,3 ‰ oder mehr im Körper vorhanden ist."],"erklaerung":"Auf Binnenschifffahrtsstraßen gilt eine Grenze von 0,5 Promille Blutalkohol. Unabhängig davon darf niemand ein Boot führen, der durch Alkohol, Drogen oder körperliche bzw. geistige Mängel in der sicheren Führung behindert ist. Zum Merken: 0,5 ‰ wie im Straßenverkehr.","stichworte":["0,5 ‰","Alkohol und Drogen","Fahruntüchtigkeit"]},{"nr":3,"teil":"basis","thema":"recht","frage":"Wann ist ein Fahrzeug in Fahrt?","inline":[],"bilder":[],"antworten":["Wenn es weder vor Anker liegt noch an Land festgemacht ist noch auf Grund sitzt.","Wenn es weder vor Anker liegt noch an Land festgemacht ist noch Fahrt über Grund macht.","Wenn es weder auf Grund sitzt noch vor Anker liegt noch manövrierbehindert oder manövrierunfähig ist.","Wenn es weder an Land festgemacht ist noch vor Anker liegt noch Fahrt durchs Wasser macht."],"erklaerung":"„In Fahrt“ ist jedes Fahrzeug, das weder ankert, noch festgemacht ist, noch auf Grund sitzt. Es muss sich dafür nicht bewegen: Auch ein treibendes Boot mit ausgeschaltetem Motor ist in Fahrt.","stichworte":["In Fahrt","nicht geankert","nicht festgemacht","nicht auf Grund"]},{"nr":4,"teil":"basis","thema":"schall","frage":"Wie lang ist die Dauer eines kurzen Tons ({0})?","inline":["bilder/EinkurzerTon.gif"],"bilder":[],"antworten":["Etwa 1 Sekunde.","Etwa 2 Sekunden.","Weniger als 1 Sekunde.","Weniger als 4 Sekunden."],"erklaerung":"Ein kurzer Ton dauert etwa 1 Sekunde, im Symbol ist er ein Punkt. Zum Vergleich: Ein langer Ton dauert etwa 4 bis 6 Sekunden.","stichworte":["Kurzer Ton","ca. 1 Sekunde","Punkt"]},{"nr":5,"teil":"basis","thema":"schall","frage":"Wie lang ist die Dauer eines langen Tons ({0})?","inline":["bilder/EinlangerTon.gif"],"bilder":[],"antworten":["Etwa 4 - 6 Sekunden.","Etwa 2 - 6 Sekunden.","Etwa 1 - 2 Sekunden.","Etwa 6 - 8 Sekunden."],"erklaerung":"Ein langer Ton dauert etwa 4 bis 6 Sekunden, im Symbol ist er ein Strich. Ein kurzer Ton dauert dagegen nur etwa 1 Sekunde.","stichworte":["Langer Ton","4–6 Sekunden","Strich"]},{"nr":6,"teil":"basis","thema":"fahrregeln","frage":"Wann gilt ein Fahrzeug unter Segel als Maschinenfahrzeug?","inline":[],"bilder":[],"antworten":["Wenn es gleichzeitig mit Maschinenkraft fährt.","Wenn es mit einer Antriebsmaschine ausgerüstet ist.","Wenn es durch das Segeln keine Fahrt durchs Wasser macht.","Wenn es durch das Segeln keine Fahrt über Grund macht."],"erklaerung":"Es kommt darauf an, ob der Motor tatsächlich mitschiebt. Ein Segelboot, das gleichzeitig mit Maschinenkraft fährt, gilt als Maschinenfahrzeug und verliert damit die Vorrechte des Seglers. Dass ein Motor nur an Bord ist, spielt keine Rolle.","stichworte":["Motorsegeln","Maschinenfahrzeug","Vorrechte entfallen"]},{"nr":7,"teil":"basis","thema":"lichter","frage":"Welches Signal führt ein Fahrzeug unter Segel, das als Maschinenfahrzeug gilt, zusätzlich am Tage?","inline":[],"bilder":[],"antworten":["Einen schwarzen Kegel, Spitze unten.","Einen schwarzen Kegel, Spitze oben.","Einen schwarzen Rhombus.","Zwei schwarze Bälle senkrecht übereinander."],"erklaerung":"Ein motorsegelndes Fahrzeug zeigt am Tag einen schwarzen Kegel mit der Spitze nach unten, gut sichtbar im Vorschiff. Daran erkennen andere, dass es als Maschinenfahrzeug gilt und keine Segler-Vorrechte hat. Merkhilfe: Die Spitze nach unten ist ein „Trichter“, durch den der Motor gefüllt wird.","stichworte":["Schwarzer Kegel","Spitze unten","Motorsegler am Tag"]},{"nr":8,"teil":"basis","thema":"seemannschaft","frage":"Welche Seite wird als Luvseite bezeichnet?","inline":[],"bilder":[],"antworten":["Die dem Wind zugekehrte Seite.","Die dem Wind abgewandte Seite.","Die Seite in Fahrtrichtung rechts.","Die Seite in Fahrtrichtung links."],"erklaerung":"Luv ist die Seite, von der der Wind kommt, also die dem Wind zugekehrte Seite. Merkhilfe: Luv wie „Luft kommt an“.","stichworte":["Luv","dem Wind zugekehrt"]},{"nr":9,"teil":"basis","thema":"seemannschaft","frage":"Welche Seite wird als Leeseite bezeichnet?","inline":[],"bilder":[],"antworten":["Die dem Wind abgewandte Seite.","Die dem Wind zugekehrte Seite.","Die Seite in Fahrtrichtung rechts.","Die Seite in Fahrtrichtung links."],"erklaerung":"Lee ist die dem Wind abgewandte, windgeschützte Seite. Merkhilfe: Im Lee ist es „leer“ vom Wind.","stichworte":["Lee","dem Wind abgewandt","windgeschützt"]},{"nr":10,"teil":"basis","thema":"lichter","frage":"Wann müssen die Lichter von Fahrzeugen geführt oder gezeigt werden?","inline":[],"bilder":[],"antworten":["Von Sonnenuntergang bis Sonnenaufgang und bei verminderter Sicht.","Von Sonnenaufgang bis Sonnenuntergang und bei verminderter Sicht.","Von abends 18:00 Uhr bis morgens 06:00 Uhr und bei verminderter Sicht.","Bei Dunkelheit, schlechtem Wetter und verminderter Sicht."],"erklaerung":"Lichter werden von Sonnenuntergang bis Sonnenaufgang geführt, außerdem tagsüber bei verminderter Sicht wie Nebel oder starkem Regen. Feste Uhrzeiten gibt es dafür nicht.","stichworte":["Sonnenuntergang bis Sonnenaufgang","verminderte Sicht"]},{"nr":11,"teil":"basis","thema":"lichter","frage":"Wozu dient die Lichterführung?","inline":[],"bilder":[],"antworten":["Sie zeigt Fahrtrichtung und Lage eines Fahrzeugs an.","Sie zeigt Kurs und Geschwindigkeit eines Fahrzeugs an.","Sie zeigt Fahrtrichtung und Position eines Fahrzeugs an.","Sie zeigt Fahrtrichtung und Kurs eines Fahrzeugs an."],"erklaerung":"An den Lichtern sieht man, in welche Richtung ein Fahrzeug fährt und wie es zu einem liegt: Sieht man Rot, blickt man auf seine Backbordseite, sieht man Grün, auf seine Steuerbordseite. Geschwindigkeit oder genaue Position verraten die Lichter nicht.","stichworte":["Fahrtrichtung","Lage","Rot = Backbord","Grün = Steuerbord"]},{"nr":12,"teil":"basis","thema":"lichter","frage":"Was für eine Laterne kann ein Segelfahrzeug von weniger als 20 m Länge anstelle der Seitenlichter und des Hecklichtes führen?","inline":[],"bilder":[],"antworten":["Eine Dreifarbenlaterne an oder nahe der Mastspitze.","Eine Zweifarbenlaterne an gut sichtbarer Stelle.","Eine Dreifarbenlaterne an gut sichtbarer Stelle.","Eine Zweifarbenlaterne an oder nahe der Mastspitze."],"erklaerung":"Segelfahrzeuge unter 20 m dürfen Seitenlichter und Hecklicht in einer Dreifarbenlaterne (rot/grün/weiß) zusammenfassen. Sie sitzt an oder nahe der Mastspitze, weil sie dort nicht von den Segeln verdeckt wird. Läuft der Motor mit, ist die Dreifarbenlaterne nicht erlaubt.","stichworte":["Dreifarbenlaterne","Mastspitze","Segler unter 20 m"]},{"nr":13,"teil":"basis","thema":"lichter","frage":"Welche Lichter muss ein Fahrzeug unter Segel, das gleichzeitig mit Maschinenkraft fährt, führen?","inline":[],"bilder":[],"antworten":["Die für ein Maschinenfahrzeug vorgeschriebenen Lichter.","Die für ein Segelfahrzeug vorgeschriebenen Lichter.","Zwei rote Rundumlichter senkrecht übereinander.","Seitenlichter rot und grün und ein rotes Rundumlicht."],"erklaerung":"Wer unter Segel und gleichzeitig mit Motor fährt, ist ein Maschinenfahrzeug. Deshalb führt er auch dessen Lichter, zusätzlich zu den Seitenlichtern also das weiße Topplicht.","stichworte":["Motorsegeln","Lichter wie Maschinenfahrzeug","Topplicht"]},{"nr":14,"teil":"basis","thema":"fahrregeln","frage":"Wie weichen zwei Motorboote aus, die sich auf entgegengesetzten Kursen nähern?","inline":[],"bilder":[],"antworten":["Jedes Fahrzeug muss seinen Kurs nach Steuerbord ändern.","Jedes Fahrzeug muss seinen Kurs nach Backbord ändern.","Es muss das luvwärtige Fahrzeug dem leewärtigen Fahrzeug ausweichen.","Es muss das leewärtige Fahrzeug dem luvwärtigen Fahrzeug ausweichen."],"erklaerung":"Kommen sich zwei Maschinenfahrzeuge entgegen, weichen beide nach Steuerbord (rechts) aus und passieren sich Backbord an Backbord. Luv und Lee spielen nur bei Seglern eine Rolle.","stichworte":["Entgegengesetzte Kurse","beide nach Steuerbord","Backbord an Backbord"]},{"nr":15,"teil":"basis","thema":"fahrregeln","frage":"Zwei Motorboote nähern sich auf kreuzenden Kursen. Es besteht die Gefahr eines Zusammenstoßes. Wer ist ausweichpflichtig?","inline":[],"bilder":[],"antworten":["Dasjenige Fahrzeug muss ausweichen, welches das Andere an seiner Steuerbordseite hat.","Dasjenige Fahrzeug muss ausweichen, welches das Andere an seiner Backbordseite hat.","Es muss das luvwärtige Fahrzeug dem leewärtigen Fahrzeug ausweichen.","Es muss das leewärtige Fahrzeug dem luvwärtigen Fahrzeug ausweichen."],"erklaerung":"Bei kreuzenden Kursen muss ausweichen, wer das andere Fahrzeug an seiner Steuerbordseite (rechts) hat. Das ist wie „rechts vor links“ im Straßenverkehr.","stichworte":["Kreuzende Kurse","Steuerbord hat Vorrang","rechts vor links"]},{"nr":16,"teil":"basis","thema":"schall","frage":"Welche Bedeutung hat folgendes Schallsignal?","inline":[],"bilder":["bilder/Schallzeichen-Frage-16.gif"],"antworten":["Bleib-weg-Signal, Gefahrenbereich sofort verlassen.","Allgemeines Gefahr- und Warnsignal.","Ankerlieger über 100 m Länge.","Manövrierbehinderter Schleppverband über 200 m Länge."],"erklaerung":"Die Folge aus abwechselnd kurzen und langen Tönen ist das Bleib-weg-Signal. Es wird zum Beispiel bei einem Unfall mit gefährlichen Gütern gegeben und bedeutet: Gefahrenbereich sofort verlassen. Das allgemeine Gefahr- und Warnsignal ist dagegen eine Folge sehr kurzer Töne.","stichworte":["Bleib-weg-Signal","kurz–lang wiederholt","Gefahrenbereich verlassen"]},{"nr":17,"teil":"basis","thema":"zeichen","frage":"Welche Bedeutung hat folgendes Tafelzeichen?","inline":[],"bilder":["bilder/Verbotszeichen-A02.gif"],"antworten":["Überholverbot.","Begegnungsverbot.","Überholverbot für Fahrzeuge unter 20 m Länge.","Begegnungsverbot für Fahrzeuge über 20 m Länge."],"erklaerung":"Rot umrandete Tafeln mit rotem Schrägbalken sind Verbote. Zwei Pfeile in die gleiche Richtung stehen für Überholen, durchgestrichen bedeutet das: Überholverbot für alle Fahrzeuge.","stichworte":["Verbotszeichen","zwei Pfeile gleiche Richtung","Überholverbot"]},{"nr":18,"teil":"basis","thema":"zeichen","frage":"Welche Bedeutung hat folgendes Tafelzeichen?","inline":[],"bilder":["bilder/Verbotszeichen-A04.gif"],"antworten":["Begegnungsverbot an einer Engstelle.","Begegnungsverbot für Fahrzeuge über 12 m Länge.","Überholverbot; mit Gegenverkehr muss gerechnet werden.","Überholverbot für alle Fahrzeuge."],"erklaerung":"Hier zeigen die Pfeile in entgegengesetzte Richtungen, es geht also um Begegnungen. Die Tafel verbietet das Begegnen an einer Engstelle, weil dort kein Platz für zwei Fahrzeuge ist.","stichworte":["Pfeile gegenläufig","Begegnungsverbot","Engstelle"]},{"nr":19,"teil":"basis","thema":"zeichen","frage":"Welche Bedeutung hat folgendes Tafelzeichen?","inline":[],"bilder":["bilder/Gebotszeichen-A04a.gif"],"antworten":["Sog und Wellenschlag vermeiden.","Gefährdeter Strandbereich, Überspülungsgefahr; Mindestpassierabstand 100 m.","Wasserstraße, die jederzeit sicher befahren werden kann; keine Gefahr durch Seegang.","Wasserstraße, die nicht jederzeit sicher befahren werden kann; Gefahr durch Seegang."],"erklaerung":"Durchgestrichene Wellen bedeuten: Sog und Wellenschlag vermeiden, also langsam fahren. Damit werden Ufer, Anleger und andere Fahrzeuge geschützt.","stichworte":["Durchgestrichene Wellen","Sog und Wellenschlag vermeiden","langsam"]},{"nr":20,"teil":"basis","thema":"zeichen","frage":"Welche Bedeutung hat folgendes Tafelzeichen?","inline":[],"bilder":["bilder/Einschraenkungszeichen-C5.gif"],"antworten":["Mindestabstand in Metern, der in der nachfolgenden Strecke vom Aufstellungsort der Tafel an eingehalten werden muss.","Maximalgeschwindigkeit in km/h, die auf der in Fahrtrichtung rechten Fahrwasserseite nicht überschritten werden darf.","Maximalabstand in Metern, der in der nachfolgenden Strecke vom Aufstellungsort der Tafel an eingehalten werden muss.","Verengung des Fahrwassers auf 40 m."],"erklaerung":"Die Zahl auf dieser Einschränkungstafel ist ein Abstand in Metern. Er muss ab der Tafel auf der folgenden Strecke eingehalten werden. Eine Geschwindigkeit ist es nicht, die steht auf einer anderen Tafel.","stichworte":["Zahl in Metern","Mindestabstand","ab Aufstellungsort"]},{"nr":21,"teil":"basis","thema":"zeichen","frage":"Welche Bedeutung hat folgendes Tafelzeichen?","inline":[],"bilder":["bilder/Gebotszeichen-B05.gif"],"antworten":["Haltegebot vor beweglichen Brücken, Sperrwerken und Schleusen.","Dauernde Sperrung einer Teilstrecke der Wasserstraße.","Gebot zur Abgabe eines langen Signaltons.","Weiterfahrt für Sportfahrzeuge verboten."],"erklaerung":"Ein schwarzer waagerechter Balken in rot umrandeter Tafel ist ein Haltegebot. Es steht vor beweglichen Brücken, Sperrwerken und Schleusen und bedeutet: Hier anhalten, wenn die Durchfahrt nicht freigegeben ist.","stichworte":["Gebotszeichen","Balken","Halten vor Brücke, Schleuse, Sperrwerk"]},{"nr":22,"teil":"basis","thema":"zeichen","frage":"Welche Bedeutung hat folgendes Tafelzeichen?","inline":[],"bilder":["bilder/Verbotszeichen-A06.gif"],"antworten":["Ankern verboten für alle Fahrzeuge.","Ankern verboten für Kleinfahrzeuge unter 12 m Länge.","Ankern verboten für Kleinfahrzeuge ab 12 m Länge.","Ankern und Festmachen verboten."],"erklaerung":"Ein durchgestrichener Anker bedeutet Ankerverbot, und zwar für alle Fahrzeuge. Die Tafel macht keine Ausnahme nach Länge oder Art des Fahrzeugs.","stichworte":["Durchgestrichener Anker","Ankerverbot","alle Fahrzeuge"]},{"nr":23,"teil":"basis","thema":"zeichen","frage":"Welche Bedeutung haben folgende Tafelzeichen?","inline":[],"bilder":["bilder/Verbotszeichen-A07.gif","bilder/Verbotszeichen-A05.gif"],"antworten":["Festmache- und Liegeverbot.","Festmache- und Liegeverbot für Sportboote.","Festmache- und Liegeverbot für Sportboote über 12 m Länge.","Festmache- und Liegeverbot für gewerbliche Schiffe."],"erklaerung":"Der durchgestrichene Poller verbietet das Festmachen am Ufer, das durchgestrichene „P“ verbietet das Liegen (Stillliegen, Parken). Beide Verbote gelten für alle Fahrzeuge.","stichworte":["Poller = Festmachen","P = Liegen","Verbot für alle"]},{"nr":24,"teil":"basis","thema":"zeichen","frage":"Welche Bedeutung hat folgendes Tafelzeichen?","inline":[],"bilder":["bilder/Schild-10.gif"],"antworten":["Abgabe eines langen Tons.","Abgabe eines kurzen Tons.","Abgabe von zwei langen Tönen.","Abgabe eines kurzen und eines langen Tons."],"erklaerung":"Der schwarze Punkt in rot umrandeter Tafel gebietet, ein Schallzeichen zu geben. Welches Zeichen gemeint ist, zeigt die Zusatztafel: Der Strich steht für einen langen Ton.","stichworte":["Schallzeichen geben","Zusatztafel","Strich = langer Ton"]},{"nr":25,"teil":"basis","thema":"zeichen","frage":"Welche Bedeutung haben folgende Tafelzeichen?","inline":[],"bilder":["bilder/Hinweiszeichen-E17.gif","bilder/Hinweiszeichen-E22.gif"],"antworten":["Wasserflächen, auf denen mit Wasserski oder Wassermotorrädern gefahren werden darf.","Genehmigungspflichtige Übungsstrecke für das Fahren mit Wasserski oder Wassermotorrädern.","Fahren mit Wasserski oder Wassermotorrädern erlaubt. Wasserskiläufer und Wassermotorräder haben Vorfahrt.","Genehmigungsfreie Übungsstrecke für das Fahren mit Wasserski oder Wassermotorrädern."],"erklaerung":"Blaue Tafeln sind Hinweise bzw. Erlaubnisse. Mit Wasserskiläufer bzw. Wassermotorrad zeigen sie Wasserflächen, auf denen diese Sportarten erlaubt sind. Vorfahrt geben sie nicht, und eine Genehmigung braucht es dafür auch nicht.","stichworte":["Blaue Tafel","Erlaubnis","Wasserski","Wassermotorrad"]},{"nr":26,"teil":"basis","thema":"zeichen","frage":"Welche Bedeutung hat folgendes Tafelzeichen?","inline":[],"bilder":["bilder/Hinweiszeichen-E11.gif"],"antworten":["Ende einer Gebots- oder Verbotsstrecke.","Streckenabschnitt für eine nicht frei fahrende Fähre.","Queren des Fahrwassers ist gestattet.","Wechseln der Fahrwasserseite ist gestattet."],"erklaerung":"Der weiße Schrägstrich auf blauer Tafel bedeutet: Hier endet eine Strecke, für die vorher ein Gebot oder Verbot galt. Er wirkt also wie ein „Aufgehoben“.","stichworte":["Weißer Schrägstrich","Ende der Strecke","Gebot/Verbot aufgehoben"]},{"nr":27,"teil":"basis","thema":"zeichen","frage":"Welche Bedeutung hat folgendes Tafelzeichen?","inline":[],"bilder":["bilder/Verbotszeichen-A01-Tafeln.gif"],"antworten":["Verbot der Durchfahrt und Sperrung der Schifffahrt.","Verbot der Durchfahrt und Sperrung für Kleinfahrzeuge.","Verbot der Durchfahrt, jedoch für Kleinfahrzeuge ohne laufende Antriebsmaschine befahrbar.","Verbot der Durchfahrt, jedoch für Kleinfahrzeuge ohne Antriebsmaschine befahrbar."],"erklaerung":"Rot-weiß-rot waagerecht (wie „Einfahrt verboten“ im Straßenverkehr) bedeutet Verbot der Durchfahrt bzw. Sperrung. Das gilt für alle Fahrzeuge, auch für Kleinfahrzeuge und Boote ohne Motor.","stichworte":["Rot-weiß-rot","Durchfahrt verboten","Sperrung für alle"]},{"nr":28,"teil":"basis","thema":"zeichen","frage":"Welche Bedeutung haben folgende Schifffahrtszeichen?","inline":[],"bilder":["bilder/Gebotszeichen-A19aa.gif"],"antworten":["Brücke, Sperrwerk oder Schleuse geschlossen.","Anlage dauerhaft gesperrt.","Stoppsignal für alle Fahrzeuge.","Außergewöhnliche Schifffahrtsbehinderung."],"erklaerung":"Zwei rote Lichter nebeneinander an Brücke, Sperrwerk oder Schleuse bedeuten: vorübergehend geschlossen, also warten. Merkhilfe: nebeneinander = vorübergehend zu, übereinander = dauerhaft gesperrt.","stichworte":["Zwei Rot nebeneinander","vorübergehend geschlossen","warten"]},{"nr":29,"teil":"basis","thema":"zeichen","frage":"Welche Bedeutung haben folgende Schifffahrtszeichen?","inline":[],"bilder":["bilder/Gebotszeichen-A19d.gif"],"antworten":["Anlage dauerhaft gesperrt.","Brücke, Sperrwerk oder Schleuse geschlossen.","Stoppsignal für alle Fahrzeuge.","Außergewöhnliche Schifffahrtsbehinderung."],"erklaerung":"Zwei rote Lichter übereinander bedeuten, dass die Anlage dauerhaft gesperrt bzw. außer Betrieb ist. Warten bringt hier nichts. Merkhilfe: übereinander = dauerhaft.","stichworte":["Zwei Rot übereinander","dauerhaft gesperrt","außer Betrieb"]},{"nr":30,"teil":"basis","thema":"schleuse","frage":"Was bedeuten diese Lichter vor einer Schleuse?","inline":[],"bilder":["bilder/Gebotszeichen-A23bb.gif"],"antworten":["Einfahrt frei, Gegenverkehr gesperrt.","Einfahrt frei, Schleusentor öffnet.","Schleuse in Betrieb, auf Einfahrtsignal gemäß Reihenfolge warten.","Schleuse in Betrieb, auf Ausfahrtsignal gemäß Reihenfolge warten."],"erklaerung":"Zwei grüne Lichter vor einer Schleuse bedeuten: Einfahrt frei, der Gegenverkehr ist gesperrt.","stichworte":["Zwei Grün","Einfahrt frei","Gegenverkehr gesperrt"]},{"nr":31,"teil":"basis","thema":"umwelt","frage":"Welches Merkblatt enthält Hinweise für das Verhalten zum Schutz seltener Tiere und Pflanzen sowie zur Reinhaltung der Gewässer?","inline":[],"bilder":[],"antworten":["Die 10 goldenen Regeln für Wassersportler.","Die 15 goldenen Regeln für Wassersportler.","Die 10 Grundregeln für Wassersportler.","Die 15 Verhaltensregeln für Wassersportler."],"erklaerung":"Die „10 goldenen Regeln für Wassersportler“ ist ein Merkblatt für umweltgerechtes Verhalten: Abstand zu Schilf, Brutplätze schonen, keine Abfälle ins Wasser usw.","stichworte":["10 goldene Regeln","Naturschutz","Gewässerreinhaltung"]},{"nr":32,"teil":"basis","thema":"umwelt","frage":"Wie kann mitgeholfen werden, die Lebensmöglichkeiten der Pflanzen- und Tierwelt in Gewässern und Feuchtgebieten zu bewahren und zu fördern?","inline":[],"bilder":[],"antworten":["Durch umweltbewusstes Verhalten und Beachtung der \"Zehn goldenen Regeln für das Verhalten von Wassersportlern in der Natur\".","Durch umweltbewusstes Verhalten und Beachtung der \"Zehn Grundregeln für den Wassersport\".","Durch umsichtiges Verhalten und Beachtung der Verkehrsvorschriften.","Durch vorausschauendes Fahren und Ausweichen entsprechend der Verkehrsvorschriften."],"erklaerung":"Die Natur am Gewässer schützt man vor allem durch eigenes umweltbewusstes Verhalten nach den „Zehn goldenen Regeln für Wassersportler“. Die Verkehrsvorschriften allein regeln den Schiffsverkehr, nicht den Naturschutz.","stichworte":["Umweltbewusst","10 goldene Regeln","Tier- und Pflanzenwelt"]},{"nr":33,"teil":"basis","thema":"umwelt","frage":"Warum sollte man sich von Schilf- und Röhrichtzonen sowie von dicht bewachsenen Uferzonen möglichst weit fernhalten?","inline":[],"bilder":[],"antworten":["Weil diese Zonen vielfach Rast- und Brutplätze besonders schutzwürdiger Vögel oder Fischlaichplätze sind.","Weil in diesen Zonen die Gefahr von Grundberührungen besteht.","Weil durch die Pflanzen der Propeller blockiert werden könnte.","Weil in diesen Zonen badende Personen schwer zu erkennen sind."],"erklaerung":"Schilf, Röhricht und dicht bewachsene Ufer sind Rückzugs-, Brut- und Rastplätze für Vögel und Laichplätze für Fische. Wer dort hineinfährt, stört und zerstört diese Lebensräume. Darum geht es bei der Frage, nicht um den Schutz des Bootes.","stichworte":["Schilf und Röhricht","Brutplätze","Laichplätze","Abstand halten"]},{"nr":34,"teil":"basis","thema":"fahrregeln","frage":"Warum soll ein kleines Fahrzeug nicht dicht an ein großes in Fahrt befindliches Fahrzeug heranfahren?","inline":[],"bilder":[],"antworten":["Es kann durch dessen Bug- oder Heckwelle kentern oder durch den Sog mit dem Fahrzeug kollidieren.","Dichtes Heranfahren ist ein Verstoß gegen die Grundregeln für das Verhalten im Verkehr.","Da es dem großen in Fahrt befindlichen Fahrzeug sonst nicht ausweichen kann.","Es kann durch dessen Bug- oder Heckwelle Seeschlag erleiden."],"erklaerung":"Große Fahrzeuge erzeugen starke Bug- und Heckwellen und einen Sog. Ein kleines Boot kann dadurch kentern oder gegen das große Fahrzeug gezogen werden. Deshalb hält man reichlich Abstand.","stichworte":["Sog","Bug- und Heckwelle","Kentergefahr","Abstand"]},{"nr":35,"teil":"basis","thema":"seemannschaft","frage":"Warum soll man möglichst gegen Strom und Wind anlegen?","inline":[],"bilder":[],"antworten":["Weil sich das Fahrzeug dabei sicherer manövrieren lässt.","Weil dadurch Sog und Wellenschlag vermieden wird.","Weil dadurch Einflüsse von Wellen und Wassertiefe ausgeglichen werden.","Weil dies die Steuerwirkung der Schraube erhöht."],"erklaerung":"Wer gegen Strom und Wind anlegt, kann langsam fahren und behält trotzdem Ruderwirkung, weil das Wasser am Ruder vorbeiströmt. Das Boot lässt sich so viel feiner steuern und auch abbremsen.","stichworte":["Gegen Strom und Wind","bessere Manövrierfähigkeit","langsam anlegen"]},{"nr":36,"teil":"basis","thema":"fahrregeln","frage":"Wie verhält man sich beim Begegnen mit anderen Fahrzeugen in einem engen Fahrwasser?","inline":[],"bilder":[],"antworten":["Geschwindigkeit herabsetzen und ausreichenden Passierabstand halten.","Geschwindigkeit erhöhen, um das Begegnungsmanöver zügig durchzuführen.","Das gegen den Strom fahrende Fahrzeug ist ausweichpflichtig.","Das mit dem Strom fahrende Fahrzeug hat aufzustoppen."],"erklaerung":"In engem Fahrwasser gilt: Geschwindigkeit herabsetzen und ausreichenden Passierabstand halten. Schnelles Vorbeifahren erhöht Sog und Wellenschlag und damit die Kollisionsgefahr.","stichworte":["Enges Fahrwasser","Fahrt verringern","Passierabstand"]},{"nr":37,"teil":"basis","thema":"fahrregeln","frage":"Welche Gefahren können entstehen, wenn ein kleines von einem größeren Fahrzeug überholt wird?","inline":[],"bilder":[],"antworten":["Das kleinere Fahrzeug kann durch Stau, Sog oder Schwell aus dem Kurs laufen und kollidieren oder querschlagen, in flachen Gewässern auf Grund laufen.","Das größere Fahrzeug kann durch Stau, Sog oder Schwell aus dem Kurs laufen und kollidieren oder querschlagen, in flachen Gewässern auf Grund laufen.","Das kleinere Fahrzeug kann durch Stau, Sog oder Schwell aus dem Kurs laufen und kollidieren oder kentern, in flachen Gewässern extrem versetzt werden.","Das größere Fahrzeug kann durch Wellenbildung aus dem Kurs laufen und kollidieren oder querschlagen, in flachen Gewässern auf Grund laufen."],"erklaerung":"Überholt ein großes Fahrzeug ein kleines, bauen sich Stau (Druck am Bug), Sog und Schwell auf. Das kleine Boot kann aus dem Kurs geraten, kollidieren oder querschlagen und im Flachwasser auf Grund laufen. Gefährdet ist also das kleinere Fahrzeug.","stichworte":["Überholt werden","Stau, Sog, Schwell","kleines Fahrzeug gefährdet"]},{"nr":38,"teil":"basis","thema":"umwelt","frage":"Wo finden Sie Informationen über umweltfreundliche Farben, Lacke und Antifouling-Beschichtungen für Ihr Boot?","inline":[],"bilder":[],"antworten":["Beim Umweltbundesamt.","Beim Bundesministerium für Digitales und Verkehr.","In der Sportbootführerscheinverordnung.","In der Sportbootvermietungsverordnung."],"erklaerung":"Informationen zu umweltfreundlichen Farben, Lacken und Antifouling gibt das Umweltbundesamt heraus. Die genannten Verordnungen regeln Führerscheine und Bootsvermietung, nicht Bootsanstriche.","stichworte":["Umweltbundesamt","Antifouling","umweltfreundliche Farben"]},{"nr":39,"teil":"basis","thema":"seemannschaft","frage":"Woran kann man erkennen, ob der Anker hält?","inline":[],"bilder":[],"antworten":["Wenn beim Handauflegen auf die Ankerkette oder -leine kein Rucken zu verspüren ist und sich die Ankerpeilung nicht ändert.","Wenn Ankerkette oder -leine nicht vibrieren und sich der anliegende Magnetkompasskurs nicht verändert.","Wenn beim Handauflegen auf die Ankerkette oder -leine kein Rucken zu verspüren ist und das Fahrzeug nicht schwojt.","Wenn beim Handauflegen auf die Ankerkette oder -leine kein Rucken zu verspüren ist und sich die Ankerpeilung ändert."],"erklaerung":"Ein Anker hält, wenn die Hand auf Kette oder Leine kein Rucken spürt (Rucken bedeutet, dass der Anker über den Grund schliert) und die Peilung zu einer festen Landmarke gleich bleibt. Schwojen, also das Schwingen um den Anker, ist dagegen normal.","stichworte":["Hand auf Ankerleine","kein Rucken","Ankerpeilung bleibt gleich"]},{"nr":40,"teil":"basis","thema":"seemannschaft","frage":"Welches ist der günstigste Anlaufwinkel beim Anlegen?","inline":[],"bilder":[],"antworten":["Ein möglichst spitzer Winkel.","Ein Winkel von 90° bis 100°.","Ein möglichst stumpfer Winkel.","Ein Winkel von 60° bis 70°."],"erklaerung":"Man läuft in möglichst spitzem Winkel an den Steg an. So kann man langsam heranfahren und das Boot rechtzeitig parallel legen, ohne mit dem Bug gegen den Steg zu stoßen.","stichworte":["Anlegen","spitzer Winkel","langsam"]},{"nr":41,"teil":"basis","thema":"motor","frage":"Wie verhält sich im Allgemeinen das Schiff im Rückwärtsgang bei einem rechtsdrehenden Propeller?","inline":[],"bilder":[],"antworten":["Das Heck dreht nach Backbord.","Das Heck dreht nach Steuerbord.","Der Kurs des Schiffes ändert sich nicht.","Der Bug dreht nach Backbord."],"erklaerung":"Beim rechtsdrehenden Propeller zieht der Radeffekt das Heck bei Rückwärtsfahrt nach Backbord. Merkhilfe: rechtsdrehend + rückwärts = Heck nach links (Backbord).","stichworte":["Rechtsdrehender Propeller","rückwärts","Heck nach Backbord","Radeffekt"]},{"nr":42,"teil":"basis","thema":"motor","frage":"Was bewirkt der Quickstopp?","inline":[],"bilder":[],"antworten":["Unterbrechung von Zündkontakt bzw. Kraftstoffzufuhr.","Automatisches Anlassen des Motors.","Kurze Unterbrechung des Motorlaufs.","Automatische Schubumkehr."],"erklaerung":"Der Quickstopp ist ein Notausschalter am Außenborder, meist mit Reißleine am Handgelenk. Fällt man über Bord, unterbricht er Zündung bzw. Kraftstoffzufuhr und stellt den Motor sofort ab.","stichworte":["Quickstopp","Notaus","Zündung unterbrechen","Reißleine"]},{"nr":43,"teil":"basis","thema":"motor","frage":"Was ist zu unternehmen, wenn Treibstoff oder Öl in die Bilge gelangt?","inline":[],"bilder":[],"antworten":["Mit Lappen aufnehmen und umweltgerecht entsorgen.","Räume lüften und abwarten.","Gleichmäßig verteilen.","Mit entsprechendem Mittel neutralisieren."],"erklaerung":"Treibstoff oder Öl in der Bilge wird mit Lappen bzw. Bindetüchern aufgenommen und als Sondermüll entsorgt. Verteilen oder „neutralisieren“ und dann außenbords pumpen ist verboten, weil es das Gewässer verschmutzt.","stichworte":["Öl in der Bilge","aufnehmen","umweltgerecht entsorgen"]},{"nr":44,"teil":"basis","thema":"motor","frage":"Was ist unter einem rechtsdrehenden Propeller zu verstehen?","inline":[],"bilder":[],"antworten":["Von achtern gesehen in Vorausfahrt Drehung des Propellers im Uhrzeigersinn.","Von vorne gesehen in Vorausfahrt Drehung des Propellers im Uhrzeigersinn.","Von achtern gesehen in Vorausfahrt Drehung des Propellers gegen den Uhrzeigersinn.","Von vorne gesehen in Rückwärtsfahrt Drehung des Propellers gegen den Uhrzeigersinn."],"erklaerung":"Ein Propeller heißt rechtsdrehend, wenn er sich von achtern (hinten) gesehen bei Vorausfahrt im Uhrzeigersinn dreht.","stichworte":["Rechtsdrehend","von achtern gesehen","Vorausfahrt","im Uhrzeigersinn"]},{"nr":45,"teil":"basis","thema":"motor","frage":"Was ist unter einem linksdrehenden Propeller zu verstehen?","inline":[],"bilder":[],"antworten":["Von achtern gesehen in Vorausfahrt Drehung des Propellers gegen den Uhrzeigersinn.","Von vorne gesehen in Vorausfahrt Drehung des Propellers gegen den Uhrzeigersinn.","Von achtern gesehen in Vorausfahrt Drehung des Propellers im Uhrzeigersinn.","Von vorne gesehen in Rückwärtsfahrt Drehung des Propellers im Uhrzeigersinn."],"erklaerung":"Ein Propeller heißt linksdrehend, wenn er sich von achtern gesehen bei Vorausfahrt gegen den Uhrzeigersinn dreht.","stichworte":["Linksdrehend","von achtern gesehen","gegen den Uhrzeigersinn"]},{"nr":46,"teil":"basis","thema":"motor","frage":"Was ist unter der indirekten Ruderwirkung (Radeffekt) des Propellers zu verstehen?","inline":[],"bilder":[],"antworten":["Das seitliche Versetzen des Hecks.","Das Versetzen nach vorne.","Das Versetzen nach hinten.","Das seitliche Versetzen des Bugs."],"erklaerung":"Der Radeffekt versetzt das Heck seitlich, weil die unteren Propellerflügel in dichterem Wasser mehr Druck aufbauen. Der Propeller „läuft“ also wie ein Rad seitlich über den Grund. Besonders stark wirkt das beim Anfahren und bei Rückwärtsfahrt.","stichworte":["Radeffekt","Heck versetzt seitlich","indirekte Ruderwirkung"]},{"nr":47,"teil":"basis","thema":"motor","frage":"Weshalb ist die Kenntnis der Propellerdrehrichtung von Bedeutung?","inline":[],"bilder":[],"antworten":["Sie hilft beim Manövrieren.","Sie hilft beim Kurshalten.","Sie hilft beim Überholen.","Sie hilft beim Begegnen."],"erklaerung":"Wer die Drehrichtung des Propellers kennt, weiß, wohin das Heck beim Einkuppeln und Rückwärtsfahren ausbricht. Das nutzt man beim Manövrieren, besonders beim An- und Ablegen.","stichworte":["Drehrichtung kennen","Manövrieren","Anlegen"]},{"nr":48,"teil":"basis","thema":"motor","frage":"Welche Anlegeseite ist mit rechtsdrehendem Propeller empfehlenswert und warum?","inline":[],"bilder":[],"antworten":["Die Backbordseite - der Radeffekt zieht das Fahrzeug an die Pier.","Die Steuerbordseite - der Radeffekt zieht das Fahrzeug an die Pier.","Die Steuerbord- oder Backbordseite je nach Ruderlage.","Es gibt keine empfehlenswerte Anlegeseite."],"erklaerung":"Beim Anlegen stoppt man mit Rückwärtsgang auf. Ein rechtsdrehender Propeller zieht dabei das Heck nach Backbord. Legt man mit Backbord an, zieht der Radeffekt das Boot also an die Pier.","stichworte":["Rechtsdrehend","Backbord anlegen","Radeffekt zieht an die Pier"]},{"nr":49,"teil":"basis","thema":"motor","frage":"Was muss beim Tanken beachtet werden?","inline":[],"bilder":[],"antworten":["Motor abstellen, keine elektrischen Schalter betätigen, Vorbereitung gegen das Überlaufen von Kraftstoff treffen, kein offenes Feuer.","Motor in Leerlaufstellung, keine elektrischen Schalter betätigen, Vorbereitung gegen das Überlaufen von Kraftstoff treffen, kein offenes Feuer.","Fenster schließen, keine elektrischen Schalter betätigen, Vorbereitung gegen das Überlaufen von Kraftstoff treffen, kein offenes Feuer.","Motor abstellen, Feuerlöscher bereithalten, Vorbereitung gegen das Überlaufen von Kraftstoff treffen, kein offenes Feuer."],"erklaerung":"Beim Tanken ist die Brandgefahr hoch. Deshalb wird der Motor ganz abgestellt (Leerlauf reicht nicht), keine elektrischen Schalter werden betätigt (Funkenbildung), es gibt kein offenes Feuer, und man bereitet sich gegen überlaufenden Kraftstoff vor, z. B. mit einem Lappen am Einfüllstutzen.","stichworte":["Motor aus","keine Schalter","kein Feuer","Überlaufen verhindern"]},{"nr":50,"teil":"basis","thema":"motor","frage":"Wodurch wird bei einem Fahrzeug mit Außenbordmotor und ohne Ruderanlage die Ruderwirkung erzielt?","inline":[],"bilder":[],"antworten":["Durch Schraubenstrom und Richtung des Propellers.","Durch Schraubenstrom und Anstellwinkel des Propellers.","Durch den Schraubenwiderstand und Anstellwinkel des Propellers.","Durch den Schraubenwiderstand und Richtung des Propellers."],"erklaerung":"Ohne Ruder lenkt man über den Außenborder selbst: Der Schraubenstrom wird in die Richtung gedrückt, in die der Propeller zeigt. Man schwenkt also den ganzen Motor.","stichworte":["Außenborder","Schraubenstrom","Propeller schwenken"]},{"nr":51,"teil":"basis","thema":"motor","frage":"Weshalb setzt bei einem Fahrzeug mit Einbaumaschine und starrer Welle bei Aufnahme der Rückwärtsfahrt die Ruderwirkung erst relativ spät ein?","inline":[],"bilder":[],"antworten":["Weil sie erst mit Anströmung des Ruderblattes einsetzt.","Weil sich durch den Radeffekt ein Unterdruck am Propeller entwickelt.","Durch den Abstand von Propeller und Ruderblatt.","Weil sich durch den Radeffekt ein Unterdruck am Ruder entwickelt."],"erklaerung":"Ein Ruder wirkt nur, wenn Wasser daran vorbeiströmt. Bei Rückwärtsfahrt bläst der Schraubenstrom vom Ruder weg, deshalb wirkt es erst, wenn das Boot selbst genug Fahrt rückwärts macht.","stichworte":["Ruderwirkung","Anströmung","Rückwärtsfahrt","spät"]},{"nr":52,"teil":"basis","thema":"motor","frage":"Während der Fahrt sollte die Maschinenanlage ständig überwacht werden. Worauf muss besonders geachtet werden?","inline":[],"bilder":[],"antworten":["Motortemperatur, Öldruck, Ladekontrolle.","Kühlwasseraustritt, Drehzahlmesser, Keilriemenspannung.","Schraubendrehzahl, Getriebeöltemperatur, Öldruck.","Druck der Einspritzpumpe, Impellerpumpe, Ölpumpe."],"erklaerung":"Wichtig für die Überwachung sind Motortemperatur (Überhitzung), Öldruck (Schmierung) und Ladekontrolle (Lichtmaschine). Das sind die Warnlampen, die man während der Fahrt im Blick behält.","stichworte":["Temperatur","Öldruck","Ladekontrolle"]},{"nr":53,"teil":"basis","thema":"motor","frage":"Die Temperatur der Antriebsmaschine überschreitet die zulässigen Grenzwerte. Was könnte die mögliche Ursache sein?","inline":[],"bilder":[],"antworten":["Defektes Thermostat, defekte Impellerpumpe, geschlossenes Seeventil, zu niedriger Kühlwasserstand.","Zu viel Motoröl, defekte Impellerpumpe, geschlossenes Seeventil, zu niedriger Kühlwasserstand.","Defektes Thermostat, defekte Impellerpumpe, geschlossenes Seeventil, zu hohe Batteriespannung.","Defektes Thermostat, defekte Kupplung, geschlossenes Seeventil, zu niedriger Kühlwasserstand."],"erklaerung":"Überhitzen deutet auf ein Problem im Kühlkreislauf: Thermostat defekt, Impeller defekt, Seeventil (Kühlwassereinlass) geschlossen oder zu wenig Kühlwasser. Batteriespannung, Kupplung und Ölmenge haben mit der Kühlung nichts zu tun.","stichworte":["Überhitzung","Thermostat","Impeller","Seeventil","Kühlwasser"]},{"nr":54,"teil":"basis","thema":"motor","frage":"Die Ladekontrolllampe erlischt nach dem Starten nicht. Was könnte die mögliche Ursache sein?","inline":[],"bilder":[],"antworten":["Lichtmaschine bzw. Regler der Lichtmaschine defekt.","Zu hohe Motordrehzahl.","Keilriemen gerissen und hoher Stromverbrauch.","Anlasser ist nach dem Starten ausgefallen."],"erklaerung":"Geht die Ladekontrolllampe nach dem Starten nicht aus, wird die Batterie nicht geladen. Ursache ist meist eine defekte Lichtmaschine oder ein defekter Regler.","stichworte":["Ladekontrolle leuchtet","Lichtmaschine","Regler"]},{"nr":55,"teil":"basis","thema":"motor","frage":"Die Ölkontrollleuchte leuchtet nach dem Starten weiter. Was könnte die mögliche Ursache sein?","inline":[],"bilder":[],"antworten":["Druckschalter bzw. Öldruckpumpe defekt.","Zu viel Motoröl im Motor.","FI-Schalter defekt.","Zu hohe Motordrehzahl."],"erklaerung":"Leuchtet die Öldruckleuchte nach dem Start weiter, wird kein ausreichender Öldruck gemeldet. Entweder ist der Druckschalter defekt oder die Ölpumpe. Motor sofort abstellen!","stichworte":["Öldruckleuchte","Druckschalter","Ölpumpe"]},{"nr":56,"teil":"basis","thema":"motor","frage":"Der Motor ist gestartet worden. Was kann die Ursache sein, wenn nach dem Einkuppeln der Antriebswelle der Motor stehenbleibt?","inline":[],"bilder":[],"antworten":["Blockierter Propeller.","Blockierte Kraftstoffzufuhr.","Verschmutzter Ölfilter.","Verschmutzter Luftfilter."],"erklaerung":"Läuft der Motor im Leerlauf und stirbt erst beim Einkuppeln ab, hat er die Last nicht geschafft. Typisch ist ein blockierter Propeller, z. B. durch eine Leine oder Pflanzen.","stichworte":["Stirbt beim Einkuppeln","Propeller blockiert","Leine im Propeller"]},{"nr":57,"teil":"basis","thema":"motor","frage":"Ein Außenborder mit gefülltem Tank bleibt während der Fahrt stehen. Was könnten die Ursachen sein?","inline":[],"bilder":[],"antworten":["Belüftungsschraube geschlossen; verstopfte Kraftstoffleitung.","Ansaugdüsen zu groß bzw. zu klein.","Tankdeckel ist offen.","Schraube an der Welle lose."],"erklaerung":"Ist die Belüftungsschraube am Tank geschlossen, entsteht beim Verbrauch ein Unterdruck und es fließt kein Kraftstoff mehr nach. Dasselbe passiert bei einer verstopften Kraftstoffleitung. Ein offener Tankdeckel würde dagegen sogar belüften.","stichworte":["Tankentlüftung","Belüftungsschraube","Kraftstoffleitung verstopft"]},{"nr":58,"teil":"basis","thema":"recht","frage":"Welche Veröffentlichungen enthalten wichtige Regeln und Tipps für Wassersportler, Empfehlungen zur Ausrüstung von Sportbooten sowie Hinweise zu umweltgerechtem Verhalten auf dem Wasser?","inline":[],"bilder":[],"antworten":["Nautische Publikationen wie „Sicherheit auf dem Wasser“ und „Sicher auf See\".","Verordnung über die Sicherung der Seefahrt und nautische Publikationen wie „Sicher auf See\".","Nautische Publikation wie „Sicherheit auf dem Wasser“ und Internationales Signalbuch.","Internationales Signalbuch und Verordnung über die Sicherung der Seefahrt."],"erklaerung":"Die Broschüren „Sicherheit auf dem Wasser“ (Binnen) und „Sicher auf See“ des Verkehrsministeriums enthalten Regeln, Tipps, Ausrüstungsempfehlungen und Umwelthinweise für Wassersportler. Verordnungen und das Signalbuch sind keine solchen Ratgeber.","stichworte":["„Sicherheit auf dem Wasser“","„Sicher auf See“","Broschüren"]},{"nr":59,"teil":"basis","thema":"recht","frage":"Unter welchen Voraussetzungen darf ein Sportboot mit Elektromotor ohne Fahrerlaubnis geführt werden?","inline":[],"bilder":[],"antworten":["Die Antriebsleistung beträgt höchstens 7,5 Kilowatt Betriebsart S1 (Dauerbetrieb).","Es darf immer ohne Fahrerlaubnis geführt werden, unabhängig von der Antriebsleistung.","Bis zu einer Antriebsleistung von 11,03 Kilowatt Betriebsart S1 (Dauerbetrieb).","Es darf nie ohne Fahrerlaubnis geführt werden, unabhängig von der Antriebsleistung."],"erklaerung":"Boote mit Elektromotor bis 7,5 kW Dauerleistung (Betriebsart S1) dürfen ohne Führerschein gefahren werden. Die 11,03 kW (15 PS) gelten für Verbrennungsmotoren.","stichworte":["Elektromotor","7,5 kW","S1 Dauerbetrieb","führerscheinfrei"]},{"nr":60,"teil":"basis","thema":"seemannschaft","frage":"Welche Vorkehrungen sind für das längere Verlassen des Fahrzeugs zu treffen?","inline":[],"bilder":[],"antworten":["Alle Seeventile schließen und den Hauptschalter des Bordnetzes ausschalten.","Kraftstoff- und Wassertank auffüllen und das Bordnetz aufladen.","Tagestank schließen und Kraftstofffilter entwässern.","Fahrzeug seefest hinterlassen und den Hafenmeister verständigen."],"erklaerung":"Verlässt man das Boot für längere Zeit, schließt man alle Seeventile (dann kann kein Wasser über undichte Schläuche eindringen) und schaltet den Hauptschalter aus (das verhindert Kurzschluss und Batterieentladung).","stichworte":["Seeventile schließen","Hauptschalter aus","Boot verlassen"]},{"nr":61,"teil":"basis","thema":"fahrregeln","frage":"Wie ist ein enges Gewässer zu befahren, wenn man sich am Ufer festgemachten Fahrzeugen nähert?","inline":[],"bilder":[],"antworten":["Verringerung der Geschwindigkeit, um schädlichen Sog und Wellenschlag zu vermeiden.","Beibehaltung der Geschwindigkeit, um durch Gleitfahrt schädlichen Sog und Wellenschlag auszuschließen.","Verringerung der Geschwindigkeit und nötigenfalls vom Rechtsfahrgebot abweichen.","Auf Höhe der festgemachten Fahrzeuge aufstoppen und überprüfen, dass kein Dritter behindert oder geschädigt wird."],"erklaerung":"An festgemachten Fahrzeugen fährt man langsam vorbei, denn Sog und Wellenschlag können sie gegen den Steg werfen oder Leinen reißen lassen. Gleitfahrt ist keine Lösung.","stichworte":["Festgemachte Fahrzeuge","langsam","Sog und Wellenschlag"]},{"nr":62,"teil":"basis","thema":"sicherheit","frage":"Wo sollen die Gasbehälter einer Flüssiggasanlage gelagert werden?","inline":[],"bilder":[],"antworten":["Möglichst an Deck, geschützt vor Sonneneinstrahlung, sonst in einem besonders abgeschlossenen Raum für Gasbehälter, der in Bodenhöhe eine Öffnung nach außenbords hat.","Möglichst unten im Schiff, geschützt vor Sonneneinstrahlung, sonst in einem besonders abgeschlossenen Raum für Gasbehälter, der in Bodenhöhe eine Öffnung nach außenbords hat.","Möglichst auf dem Vorschiff, geschützt vor Sonneneinstrahlung, sonst in einem besonders abgeschlossenen Raum für Gasbehälter, der in Bodenhöhe eine Öffnung nach außenbords hat.","Möglichst an Deck, geschützt vor Sonneneinstrahlung, sonst in einem besonders abgeschlossenen Raum für Gasbehälter, der oben belüftet ist."],"erklaerung":"Propan und Butan sind schwerer als Luft und sammeln sich ganz unten. Deshalb lagert man Gasflaschen am besten an Deck, vor Sonne geschützt. Sonst kommen sie in einen eigenen Gaskasten mit Öffnung nach außenbords in Bodenhöhe, damit ausströmendes Gas abfließen kann.","stichworte":["Gasflasche an Deck","Gaskasten","Öffnung unten nach außenbords"]},{"nr":63,"teil":"basis","thema":"sicherheit","frage":"Warum sind die Flüssiggase Propan und Butan an Bord besonders gefährlich?","inline":[],"bilder":[],"antworten":["Beide Gase sind schwerer als Luft und bilden mit Luft ein explosives Gemisch.","Beide Gase sind leichter als Luft und bilden mit Luft ein explosives Gemisch.","Beide Gase sind schwerer als Wasser und bilden mit Wasser ein explosives Gemisch.","Beide Gase sind schwerer als Luft und bilden mit Wasser ein explosives Gemisch."],"erklaerung":"Propan und Butan sind schwerer als Luft. Austretendes Gas sammelt sich deshalb in der Bilge und bildet mit Luft ein explosives Gemisch. Ein Funke genügt dann.","stichworte":["Schwerer als Luft","sammelt sich in der Bilge","explosiv"]},{"nr":64,"teil":"basis","thema":"sicherheit","frage":"Was ist zu tun, wenn Flüssiggas in das Innere des Bootes gelangt?","inline":[],"bilder":[],"antworten":["Gaszuführung absperren und für Lüftung sorgen. Außerdem keine elektrischen Schalter betätigen und keinen Funk und keine Mobiltelefone benutzen.","Gasleitung entleeren und für Lüftung sorgen. Außerdem keine elektrischen Schalter betätigen und keine Telefone benutzen.","Gaszuführung absperren und für Lüftung sorgen. Außerdem keine elektrischen Schalter betätigen und per Telefon Hilfe holen.","Gasleitung entleeren und die Gasfreiheit mit dem Feuerzeug prüfen sowie über Funk oder Mobiltelefon Hilfe anfordern."],"erklaerung":"Ist Gas ausgetreten: Gaszufuhr absperren und gut lüften. Keine elektrischen Schalter betätigen und weder Funkgerät noch Handy benutzen, denn jeder Funke kann das Gemisch zünden. Gasfreiheit niemals mit Feuer prüfen!","stichworte":["Gas absperren","lüften","keine Funken","kein Handy/Funk"]},{"nr":65,"teil":"basis","thema":"sicherheit","frage":"Was ist vor Inbetriebnahme einer Flüssiggasanlage zu prüfen?","inline":[],"bilder":[],"antworten":["Die Anlage muss abgenommen sein, Leitungen und Anschlüsse müssen dicht sein. Haupthahn und andere Absperrventile sind zu öffnen.","Die Anlage muss abgenommen sein, die Inbetriebnahme darf nur durch eine besonders geprüfte Person erfolgen.","Die Anlage muss abgenommen sein und jährlich überprüft werden. Die Inbetriebnahme darf nur durch eine besonders geprüfte Person erfolgen.","Die Abnahme der Anlage darf nicht länger als drei Jahre zurückliegen. Haupthahn und andere Absperrventile sind zu öffnen."],"erklaerung":"Eine Gasanlage darf nur in Betrieb gehen, wenn sie abgenommen (geprüft) ist und Leitungen und Anschlüsse dicht sind. Dann öffnet man Haupthahn und Absperrventile. Eine besondere Person für die Inbetriebnahme braucht es nicht.","stichworte":["Abgenommen","dicht","Haupthahn öffnen"]},{"nr":66,"teil":"basis","thema":"sicherheit","frage":"Was ist zu beachten, wenn eine Flüssiggasanlage außer Betrieb gesetzt wird?","inline":[],"bilder":[],"antworten":["Haupthahn und Absperrventile sind zu schließen.","Die Anlage ist gasfrei zu machen.","Gasflasche fachgerecht entsorgen.","Der Flüssiggasbehälter ist vollständig zu entleeren."],"erklaerung":"Außer Betrieb setzen heißt: Haupthahn und alle Absperrventile schließen. Die Flasche muss dafür weder geleert noch entsorgt werden.","stichworte":["Haupthahn zu","Absperrventile zu"]},{"nr":67,"teil":"basis","thema":"sicherheit","frage":"Wie oft muss man aufblasbare Rettungsmittel warten lassen?","inline":[],"bilder":[],"antworten":["Entsprechend der Herstellerangabe, mindestens alle 2 Jahre.","Jährlich und nach jedem Einsatz oder Übungsgebrauch.","Entsprechend der Herstellerangabe, mindestens alle 3 Jahre.","Jährlich, jeweils vor Beginn der Wassersportsaison."],"erklaerung":"Aufblasbare Rettungsmittel wie automatische Rettungswesten oder Rettungsinseln werden nach Herstellerangabe gewartet, spätestens aber alle 2 Jahre.","stichworte":["Aufblasbare Rettungsmittel","Herstellerangabe","mind. alle 2 Jahre"]},{"nr":68,"teil":"basis","thema":"sicherheit","frage":"Welcher Feuerlöscher ist für Sportboote zweckmäßig und wie oft muss man einen Feuerlöscher überprüfen lassen?","inline":[],"bilder":[],"antworten":["ABC-Pulver- und Schaumlöscher, mindestens alle 2 Jahre.","Feuerlöscher mit Löschschaum, mindestens einmal pro Jahr.","CO2-Feuerlöscher, mindestens alle 2 Jahre.","ABC-Pulverlöscher, mindestens einmal pro Jahr."],"erklaerung":"Für Sportboote eignen sich ABC-Pulverlöscher (für Feststoffe, Flüssigkeiten und Gase) und Schaumlöscher. Sie müssen mindestens alle 2 Jahre geprüft werden. CO₂ ist in engen Räumen gefährlich und auf offenem Deck wenig wirksam.","stichworte":["ABC-Pulver","Schaum","Prüfung alle 2 Jahre"]},{"nr":69,"teil":"basis","thema":"sicherheit","frage":"Welche Maßnahmen muss man ergreifen, um einen Brand mit dem Feuerlöscher wirksam zu bekämpfen?","inline":[],"bilder":[],"antworten":["Luftzufuhr verhindern, Feuerlöscher erst am Brandherd einsetzen und das Feuer möglichst von unten bekämpfen.","Rauchabzug sicherstellen und Feuerlöscher rechtzeitig einsetzen, dabei den Löschstrahl möglichst in die lodernden Flammen halten.","Luftzufuhr verhindern und den Feuerlöscher mit sparsamen Löschstrahlstößen einsetzen, dabei das Feuer möglichst von oben bekämpfen.","Handhabungshinweise durchlesen und den Feuerlöscher sofort einsetzen, dabei das Feuer möglichst von unten bekämpfen."],"erklaerung":"Feuer braucht Sauerstoff, deshalb Luftzufuhr verhindern (Luken zu). Den Löscher erst direkt am Brandherd auslösen, damit kein Löschmittel verloren geht, und von unten in die Glut löschen, nicht in die Flammen.","stichworte":["Luftzufuhr verhindern","erst am Brandherd","von unten löschen"]},{"nr":70,"teil":"basis","thema":"recht","frage":"Wie hat man sich nach einem Zusammenstoß zu verhalten?","inline":[],"bilder":[],"antworten":["Hilfe leisten und so lange am Unfallort bleiben, bis ein weiterer Beistand nicht mehr erforderlich ist; alle erforderlichen Daten austauschen.","Hilfe leisten und so lange am Unfallort bleiben, bis ein weiterer Beistand nicht mehr erforderlich ist; die Wasserschutzpolizei benachrichtigen.","Hilfe leisten und so lange am Unfallort bleiben, bis ein weiterer Beistand nicht mehr erforderlich ist; Notsignal geben.","Hilfe leisten und so lange am Unfallort bleiben, bis ein weiterer Beistand nicht mehr erforderlich ist; Verschlusszustand herstellen."],"erklaerung":"Nach einem Zusammenstoß muss man Hilfe leisten und bleiben, bis keine Hilfe mehr gebraucht wird. Außerdem werden die nötigen Daten ausgetauscht (Namen, Boot, Versicherung), ähnlich wie nach einem Autounfall.","stichworte":["Hilfe leisten","am Unfallort bleiben","Daten austauschen"]},{"nr":71,"teil":"basis","thema":"wetter","frage":"Welche Faktoren sind hauptsächlich für das Wettergeschehen, also für Wind und Niederschläge, ausschlaggebend?","inline":[],"bilder":[],"antworten":["Luftdruckänderung, Luftfeuchtigkeit und Temperatur.","Luftdruckänderung, Sonneneinstrahlung und Höhenlage.","Luftdruckänderung, Luftfeuchtigkeit und Jahreszeit.","Luftdruckänderung, Tageszeit und Temperatur."],"erklaerung":"Wind entsteht durch Luftdruckunterschiede, Niederschlag durch Luftfeuchtigkeit und Temperatur (abkühlende Luft lässt Wasserdampf kondensieren). Diese drei Faktoren bestimmen das Wetter.","stichworte":["Luftdruck","Luftfeuchtigkeit","Temperatur"]},{"nr":72,"teil":"basis","thema":"schall","frage":"In welcher Situation dürfen Notsignale gegeben werden?","inline":[],"bilder":[],"antworten":["Wenn Gefahr für Leib oder Leben von Personen besteht und daher Hilfe benötigt wird.","Wenn Gefahr für Leib oder Leben von Personen besteht oder das Schiff nicht mehr sicher manövriert werden kann.","Wenn Gefahr für Leib oder Leben von Personen oder erhebliche Sachwerte besteht und daher Hilfe benötigt wird.","Wenn Gefahr für Leib oder Leben von Personen, erhebliche Sachwerte oder die maritime Umwelt besteht."],"erklaerung":"Notsignale sind nur erlaubt, wenn Menschen in Gefahr sind und Hilfe brauchen. Sachschaden allein oder ein manövrierunfähiges Boot ohne Gefahr für Personen reichen nicht.","stichworte":["Notsignal","Gefahr für Leib und Leben","Hilfe nötig"]},{"nr":73,"teil":"binnen","thema":"recht","frage":"Für welche Sportboote ist der Sportbootführerschein mit dem Geltungsbereich Binnenschifffahrtsstraßen vorgeschrieben?","inline":[],"bilder":[],"antworten":["Für Sportboote von mehr als 11,03 kW (15 PS) Nutzleistung bei Verwendung eines Verbrennungsmotors bzw. 7,5 kW bei Verwendung eines Elektromotors Betriebsart S1 (Dauerbetrieb) und weniger als 20 m Länge.","Für Sportboote von weniger als 11,03 kW (15 PS) Nutzleistung bei Verwendung eines Verbrennungsmotors bzw. 7,5 kW bei Verwendung eines Elektromotors Betriebsart S1 (Dauerbetrieb) und mehr als 20 m Länge.","Für Sportboote von mehr als 11,03 kW (15 PS) Nutzleistung bei Verwendung eines Verbrennungsmotors bzw. 7,5 kW bei Verwendung eines Elektromotors Betriebsart S1 (Dauerbetrieb) und mehr als 20 m Länge.","Für Sportboote von weniger als 11,03 kW (15 PS) Nutzleistung bei Verwendung eines Verbrennungsmotors bzw. 7,5 kW bei Verwendung eines Elektromotors Betriebsart S1 (Dauerbetrieb) und weniger als 20 m Länge."],"erklaerung":"Pflicht ist der SBF Binnen ab mehr als 11,03 kW (15 PS) beim Verbrenner bzw. mehr als 7,5 kW beim Elektromotor, und zwar für Boote unter 20 m Länge. Für Boote ab 20 m braucht man ein Sportschifferzeugnis bzw. Patent.","stichworte":["Über 11,03 kW / 15 PS","Elektro über 7,5 kW","unter 20 m"]},{"nr":74,"teil":"binnen","thema":"recht","frage":"Auf welchen Gewässern gilt der Sportbootführerschein mit dem Geltungsbereich Binnenschifffahrtsstraßen?","inline":[],"bilder":[],"antworten":["Auf den Bundeswasserstraßen im Binnenbereich.","Auf allen Landesgewässern.","Auf den Bundeswasserstraßen und allen Landesgewässern.","Auf allen Seewasserstraßen."],"erklaerung":"Der SBF Binnen gilt auf den Bundeswasserstraßen im Binnenbereich. Für Landesgewässer gelten eigene Regeln der Bundesländer, für Seeschifffahrtsstraßen braucht man den SBF See.","stichworte":["Bundeswasserstraßen","Binnenbereich","nicht Landesgewässer"]},{"nr":75,"teil":"binnen","thema":"recht","frage":"Aus welchen Gründen muss der Sportbootführerschein mit dem Geltungsbereich Binnenschifffahrtsstraßen entzogen werden?","inline":[],"bilder":[],"antworten":["Bei fehlender Tauglichkeit oder fehlender Zuverlässigkeit.","Bei zweifelhafter Tauglichkeit wegen Alkoholmissbrauch.","Bei zweifelhafter Zuverlässigkeit aus Altersgründen.","Bei fehlender Zuverlässigkeit nach einer begangenen Ordnungswidrigkeit."],"erklaerung":"Der Führerschein muss entzogen werden, wenn Tauglichkeit oder Zuverlässigkeit fehlen. Bloße Zweifel reichen dafür nicht, sie führen zunächst zu einer Prüfung.","stichworte":["Entzug","fehlende Tauglichkeit","fehlende Zuverlässigkeit"]},{"nr":76,"teil":"binnen","thema":"recht","frage":"Was beinhaltet die allgemeine Sorgfaltspflicht?","inline":[],"bilder":[],"antworten":["Vermeidung der Gefährdung von Menschenleben, von Beschädigungen an Fahrzeugen, Anlagen oder Ufern, Behinderung der Schifffahrt und Beeinträchtigung der Umwelt.","Gefährdung von Menschenleben, Beschädigungen an Fahrzeugen, Anlagen oder Ufern und Beeinträchtigung der Umwelt.","Es ist alles zu tun, was zur Vermeidung der Gefährdung von Menschenleben, Behinderung der Schifffahrt und Beeinträchtigung der Umwelt nötig ist.","Es ist alles zu tun, was zur Vermeidung von Beschädigungen an Fahrzeugen, Anlagen oder Ufern, Behinderung der Schifffahrt und Beeinträchtigung der Umwelt nötig ist."],"erklaerung":"Zur allgemeinen Sorgfaltspflicht gehört, alles zu vermeiden, was Menschen gefährdet, Fahrzeuge, Anlagen oder Ufer beschädigt, die Schifffahrt behindert oder die Umwelt beeinträchtigt. Die richtige Antwort nennt alle vier Punkte.","stichworte":["Sorgfaltspflicht","Menschen","Sachen","Schifffahrt","Umwelt"]},{"nr":77,"teil":"binnen","thema":"recht","frage":"Unter welchen Umständen darf von den geltenden Bestimmungen über das Verhalten im Verkehr auf den Binnenschifffahrtsstraßen abgewichen werden?","inline":[],"bilder":[],"antworten":["Bei unmittelbar drohender Gefahr für sich oder andere.","Bei unmittelbar bevorstehender Begegnung.","Bei unmittelbar bevorstehendem Überholvorgang.","Bei mittelbar drohender Gefahr für sich oder andere."],"erklaerung":"Von den Verkehrsregeln darf man nur abweichen, wenn unmittelbar Gefahr droht, also um einen Unfall abzuwenden. Ein Überholen oder Begegnen allein ist kein solcher Grund.","stichworte":["Abweichen von Regeln","unmittelbar drohende Gefahr"]},{"nr":78,"teil":"binnen","thema":"recht","frage":"Welche Anforderungen neben der körperlichen und geistigen Tauglichkeit und fachlichen Eignung muss der Führer eines Sportbootes auf Binnenschifffahrtsstraßen erfüllen, wenn die größte Nutzleistung der Antriebsmaschine 11,03 kW bei Verbrennungsmotoren bzw. 7,5 kW bei Elektromotoren Betriebsart S1 (Dauerbetrieb) oder weniger beträgt?","inline":[],"bilder":[],"antworten":["Mindestalter 16 Jahre.","Nachweis der Zuverlässigkeit.","Mindestalter 14 Jahre.","Besitz eines Sportbootführerscheins mit dem Geltungsbereich Binnenschifffahrtsstraßen für Sportboote mit Antriebsmaschine oder eines gleichgestellten Befähigungszeugnisses."],"erklaerung":"Bis 11,03 kW (Verbrenner) bzw. 7,5 kW (Elektro) braucht man keinen Führerschein, muss aber mindestens 16 Jahre alt sein (und tauglich und geeignet).","stichworte":["Führerscheinfrei","Mindestalter 16"]},{"nr":79,"teil":"binnen","thema":"recht","frage":"Welche Anforderungen neben der körperlichen und geistigen Tauglichkeit und fachlichen Eignung muss der Führer eines Sportbootes auf dem Rhein erfüllen, wenn die Nutzleistung der Antriebsmaschine mehr als 11,03 kW bei Verbrennungsmotoren bzw. 7,5 kW bei Elektromotoren Betriebsart S1 (Dauerbetrieb) beträgt?","inline":[],"bilder":[],"antworten":["Besitz eines Sportbootführerscheins mit dem Geltungsbereich Binnenschifffahrtsstraßen für Sportboote mit Antriebsmaschine oder eines gleichgestellten Befähigungszeugnisses.","Nachweis der Zuverlässigkeit.","Mindestens 14 Jahre.","Mindestalter 16 Jahre."],"erklaerung":"Auf dem Rhein braucht man bei mehr als 11,03 kW bzw. 7,5 kW elektrisch den SBF Binnen für Antriebsmaschine oder ein gleichgestelltes Befähigungszeugnis.","stichworte":["Rhein","über 11,03 kW","SBF Binnen nötig"]},{"nr":80,"teil":"binnen","thema":"recht","frage":"Welche Anforderungen werden an die Person gestellt, mit der der Schiffsführer das Ruder eines Sportbootes mit Antriebsmaschine auf Binnenschifffahrtstraßen besetzen will?","inline":[],"bilder":[],"antworten":["Sie muss mindestens 16 Jahre alt und körperlich, geistig und fachlich geeignet sein.","Sie muss mindestens 18 Jahre alt und körperlich, geistig und fachlich geeignet sein.","Sie muss mindestens 16 Jahre alt und Inhaber des Sportbootführerscheins mit dem Geltungsbereich Binnenschifffahrtsstraßen für Sportboote mit Antriebsmaschine sein.","Sie muss mindestens 14 Jahre alt und körperlich, geistig und fachlich geeignet sein."],"erklaerung":"Wer bei einem Motorboot das Ruder übernimmt, muss mindestens 16 Jahre alt sein und körperlich, geistig und fachlich geeignet. Einen eigenen Führerschein braucht er nicht, solange der Schiffsführer mit Schein an Bord ist und die Verantwortung trägt.","stichworte":["Rudergänger","mind. 16 Jahre","geeignet","kein eigener Schein nötig"]},{"nr":81,"teil":"binnen","thema":"recht","frage":"Wo erhält man Auskünfte über Verkehrsbeschränkungen und aktuelle Informationen über Binnenschifffahrtsstraßen?","inline":[],"bilder":[],"antworten":["Bei der Wasserstraßen- und Schifffahrtsverwaltung, im Internet unter www.elwis.de und bei der Wasserschutzpolizei.","Bei einem Wasserwirtschaftsamt und bei der Wasserschutzpolizei.","In der Binnenschifffahrtsstraßen-Ordnung Teil II.","In der Binnenschiffsuntersuchungsordnung."],"erklaerung":"Aktuelle Informationen zu Sperrungen, Wasserständen und Beschränkungen gibt es bei der Wasserstraßen- und Schifffahrtsverwaltung (WSV), im Internet auf ELWIS (www.elwis.de) und bei der Wasserschutzpolizei. Verordnungen enthalten keine tagesaktuellen Informationen.","stichworte":["WSV","ELWIS","Wasserschutzpolizei","aktuelle Infos"]},{"nr":82,"teil":"binnen","thema":"recht","frage":"Wozu muss der Rudergänger eines Sportbootes zur sicheren Steuerung in der Lage sein?","inline":[],"bilder":[],"antworten":["Alle Informationen und Weisungen zu empfangen und zu geben, alle Schallzeichen wahrzunehmen und nach allen Seiten genügend freie Sicht zu haben.","Alle Informationen und Weisungen zu empfangen und zu geben.","Alle Schallzeichen wahrnehmen zu können und nach allen Seiten genügend freie Sicht zu haben.","Alle Informationen und Weisungen zu empfangen und zu geben und nach allen Seiten genügend freie Sicht zu haben."],"erklaerung":"Der Rudergänger muss Informationen und Anweisungen empfangen und weitergeben können, alle Schallzeichen hören und nach allen Seiten genug sehen. Richtig ist nur die Antwort, die alle drei Punkte nennt.","stichworte":["Rudergänger","Weisungen","Schallzeichen hören","freie Sicht"]},{"nr":83,"teil":"binnen","thema":"recht","frage":"Bis zu welcher Schiffslänge berechtigt der Sportbootführerschein mit dem Geltungsbereich Binnenschifffahrtsstraßen zum Führen eines Sportbootes auf Binnenschifffahrtsstraßen?","inline":[],"bilder":[],"antworten":["Bis zu einer Länge von weniger als 20 m (ohne Ruder und Bugspriet).","Bis zu einer Länge von weniger als 25 m (mit Ruder und Bugspriet).","Bis zu einer Länge von weniger als 25 m (ohne Ruder und Bugspriet).","Bis zu einer Länge von weniger als 15 m (mit Ruder und Bugspriet)."],"erklaerung":"Der SBF Binnen gilt für Sportboote unter 20 m Länge. Gemessen wird ohne Ruder und Bugspriet. Ab 20 m braucht man ein Sportschifferzeugnis bzw. Patent.","stichworte":["Unter 20 m","ohne Ruder und Bugspriet"]},{"nr":84,"teil":"binnen","thema":"recht","frage":"Wo findet man die allgemeinen Verkehrsregeln für die Binnenschifffahrtsstraßen und den Rhein?","inline":[],"bilder":[],"antworten":["Binnenschifffahrtsstraßen-Ordnung, Rheinschifffahrtspolizeiverordnung.","Binnenschiffsuntersuchungsordnung, Rheinschifffahrtspolizeiverordnung.","Moselschifffahrtspolizeiverordnung, Donauschifffahrtspolizeiverordnung.","Wassermotorräderverordnung, Wasserskiverordnung."],"erklaerung":"Allgemein gilt auf den Binnenschifffahrtsstraßen die Binnenschifffahrtsstraßen-Ordnung (BinSchStrO), auf dem Rhein die Rheinschifffahrtspolizeiverordnung. Die Untersuchungsordnung regelt die Technik der Schiffe, nicht den Verkehr.","stichworte":["BinSchStrO","Rheinschifffahrtspolizeiverordnung"]},{"nr":85,"teil":"binnen","thema":"recht","frage":"Wo findet man die allgemeinen Verkehrsregeln für die Mosel und die Donau?","inline":[],"bilder":[],"antworten":["Moselschifffahrtspolizeiverordnung, Donauschifffahrtspolizeiverordnung.","Donauschifffahrtspolizeiverordnung, Binnenschifffahrtsstraßen-Ordnung.","Moselschifffahrtspolizeiverordnung, Binnenschiffsuntersuchungsordnung.","Wassermotorräderverordnung, Wasserskiverordnung."],"erklaerung":"Mosel und Donau haben eigene Verkehrsregeln: die Moselschifffahrtspolizeiverordnung und die Donauschifffahrtspolizeiverordnung.","stichworte":["Mosel","Donau","eigene Polizeiverordnungen"]},{"nr":86,"teil":"binnen","thema":"recht","frage":"Wo findet man Regeln für den Verkehr von Wassermotorrädern und für das Wasserskilaufen?","inline":[],"bilder":[],"antworten":["Wassermotorräderverordnung, Wasserskiverordnung.","Moselschifffahrtspolizeiverordnung, Donauschifffahrtspolizeiverordnung.","Binnenschifffahrtsstraßen-Ordnung, Rheinschifffahrtspolizeiverordnung.","Moselschifffahrtspolizeiverordnung, Binnenschiffsuntersuchungsordnung."],"erklaerung":"Für Wassermotorräder und Wasserski gibt es eigene Verordnungen: die Wassermotorräderverordnung und die Wasserskiverordnung.","stichworte":["Wassermotorräderverordnung","Wasserskiverordnung"]},{"nr":87,"teil":"binnen","thema":"gewaesser","frage":"Welche Maßnahmen sind zu treffen, wenn das Fahrzeug innerhalb des Fahrwassers bzw der Fahrrinne Grundberührung hat?","inline":[],"bilder":[],"antworten":["Die Wasserstraßen- und Schifffahrtsverwaltung oder die Wasserschutzpolizei ist mit genauer Angabe der Hindernisstelle zu benachrichtigen.","Die Wasserschutzpolizei oder die Wasserstraßen- und Schifffahrtsverwaltung ist mit genauer Angabe der Schiffsdaten zu informieren.","Das Fahrzeug verbleibt vor Ort bis die Wasserschutzpolizei eintrifft.","Ein Baggerunternehmen ist zu verständigen, damit das Hindernis beseitigt wird."],"erklaerung":"Eine Grundberührung im Fahrwasser weist auf ein Hindernis hin, das andere gefährden kann. Man meldet sie deshalb der WSV oder der Wasserschutzpolizei, mit genauer Angabe, wo das Hindernis liegt. Die Schiffsdaten sind dabei nicht das Wichtigste.","stichworte":["Grundberührung","melden","WSV oder WSP","Hindernisstelle angeben"]},{"nr":88,"teil":"binnen","thema":"gewaesser","frage":"Was versteht man unter \"Fahrwasser\"?","inline":[],"bilder":[],"antworten":["Den Teil der Wasserstraße, der den örtlichen Umständen nach vom durchgehenden Schiffsverkehr benutzt wird.","Es ist der Teil der Wasserstraße, der durch die Ufer begrenzt ist.","Den Teil der Wasserstraße, in dem für den durchgehenden Schiffsverkehr bestimmte Breiten und Tiefen vorgehalten bzw. angestrebt werden.","Es ist der Teil der Wasserstraße, deren Tiefe bei 2,50 m und mehr beginnt."],"erklaerung":"Das Fahrwasser ist der Teil der Wasserstraße, den der durchgehende Schiffsverkehr nach den örtlichen Umständen tatsächlich benutzt. Die Definition mit „vorgehaltenen Breiten und Tiefen“ gehört zur Fahrrinne.","stichworte":["Fahrwasser","vom Verkehr benutzt","örtliche Umstände"]},{"nr":89,"teil":"binnen","thema":"gewaesser","frage":"Was versteht man unter \"Fahrrinne\"?","inline":[],"bilder":[],"antworten":["Es ist der Teil der Wasserstraße, in dem für den durchgehenden Schiffsverkehr bestimmte Breiten und Tiefen vorgehalten bzw. angestrebt werden.","Den Teil der Wasserstraße, der den örtlichen Umständen nach vom durchgehenden Schiffsverkehr benutzt wird.","Es ist der Teil der Wasserstraße, deren Breite mindestens 150 m und deren Tiefe mindestens 3,00 m beträgt.","Es ist der Teil der Wasserstraße, deren Breite mindestens 88 m und deren Tiefe mindestens 2,50 m beträgt."],"erklaerung":"In der Fahrrinne werden für den durchgehenden Verkehr bestimmte Breiten und Tiefen vorgehalten oder angestrebt. Die Fahrrinne liegt innerhalb des Fahrwassers und wird mit Tonnen gekennzeichnet. Feste Zahlenwerte gibt es dafür nicht.","stichworte":["Fahrrinne","Breiten und Tiefen vorgehalten","betonnt"]},{"nr":90,"teil":"binnen","thema":"gewaesser","frage":"Wie wird die Schifffahrt vom Erreichen bestimmter Wasserstände und Hochwassermarken informiert?","inline":[],"bilder":[],"antworten":["Durch Nautischen Informationsfunk, Information im Rundfunk, im Fernsehen und im Internet.","Durch Aushang bei Hafenämtern und Schleusen.","Durch Aushang bei Wasserschutzpolizei-Stationen.","Durch Bekanntgaben der Hochwasserschutzzentrale."],"erklaerung":"Bei Hochwasser wird über Nautischen Informationsfunk, Radio, Fernsehen und Internet (z. B. ELWIS) informiert, damit die Meldung möglichst viele schnell erreicht. Ein Aushang allein reicht dafür nicht.","stichworte":["Hochwasser","Nautischer Informationsfunk","Rundfunk","Internet"]},{"nr":91,"teil":"binnen","thema":"gewaesser","frage":"Wo kann der Sportbootfahrer vor Ort das Erreichen bestimmter Wasserstände und Hochwassermarken feststellen?","inline":[],"bilder":[],"antworten":["An den Pegeln und ausgewiesenen Hochwassermarken.","An den Aushängen bei Hafenämtern und Schleusen.","An den Aushängen bei Wasserschutzpolizei-Stationen.","An den Pegeln und den Einsenkungsmarken der Fahrzeuge."],"erklaerung":"Vor Ort liest man den Wasserstand an den Pegeln und an den ausgewiesenen Hochwassermarken am Ufer ab. Einsenkungsmarken zeigen dagegen, wie tief ein Schiff beladen ist.","stichworte":["Pegel","Hochwassermarken","vor Ort"]},{"nr":92,"teil":"binnen","thema":"gewaesser","frage":"Welche Auswirkungen kann das Erreichen der Hochwassermarke I für die Sportschifffahrt haben?","inline":[],"bilder":[],"antworten":["Geschwindigkeitsbeschränkung und Fahrverbot für Fahrzeuge ohne Sprechfunk.","Einstellung der Schifffahrt.","Verbot der Schifffahrt bei Nacht und unsichtigem Wetter.","Überholverbot und Fahrverbot für Fahrzeuge ohne Sprechfunk."],"erklaerung":"Ab Hochwassermarke I wird die Schifffahrt eingeschränkt: Es gilt eine Geschwindigkeitsbeschränkung, und Fahrzeuge ohne Sprechfunk dürfen nicht mehr fahren. Damit sind die meisten Sportboote betroffen. Ganz eingestellt wird die Schifffahrt erst bei Marke II.","stichworte":["Hochwassermarke I","Geschwindigkeitsbeschränkung","Fahrverbot ohne Funk"]},{"nr":93,"teil":"binnen","thema":"gewaesser","frage":"Welche Auswirkungen hat das Erreichen der Hochwassermarke II für die Sportschifffahrt?","inline":[],"bilder":[],"antworten":["Einstellung der Schifffahrt.","Geschwindigkeitsbeschränkung und Fahrverbot für Fahrzeuge ohne Sprechfunk.","Überholverbot und Fahrverbot für Fahrzeuge ohne Sprechfunk.","Verbot der Schifffahrt bei Nacht und unsichtigem Wetter."],"erklaerung":"Bei Hochwassermarke II wird die Schifffahrt ganz eingestellt. Merkhilfe: Marke I = eingeschränkt, Marke II = Stopp.","stichworte":["Hochwassermarke II","Schifffahrt eingestellt"]},{"nr":94,"teil":"binnen","thema":"gewaesser","frage":"In welche Richtung werden bei Flüssen die Uferseiten als rechtes bzw. linkes Ufer bezeichnet?","inline":[],"bilder":[],"antworten":["Von der Quelle bis zur Mündung.","Von der Mündung bis zur Quelle.","Bei der Bergfahrt liegt die rechte Uferseite rechts.","Bei der Talfahrt liegt die rechte Uferseite links."],"erklaerung":"Rechtes und linkes Ufer werden in Fließrichtung bestimmt, also von der Quelle zur Mündung gesehen. Wer zu Tal fährt, hat das rechte Ufer rechts.","stichworte":["Rechtes/linkes Ufer","von der Quelle zur Mündung","Talfahrt"]},{"nr":95,"teil":"binnen","thema":"gewaesser","frage":"Was bedeutet \"zu Berg\" oder \"Bergfahrt\" auf Flüssen?","inline":[],"bilder":[],"antworten":["Die Fahrt in Richtung Quelle.","Die Fahrt über Grund.","Die Fahrt mit der Strömung.","Die Fahrt in Richtung Mündung."],"erklaerung":"Bergfahrt bedeutet auf Flüssen Fahrt flussaufwärts, Richtung Quelle, also gegen die Strömung. Talfahrt geht Richtung Mündung.","stichworte":["Bergfahrt","Richtung Quelle","stromauf"]},{"nr":96,"teil":"binnen","thema":"gewaesser","frage":"Was bedeutet \"zu Berg\" oder \"Bergfahrt\" auf Kanälen?","inline":[],"bilder":[],"antworten":["Die Fahrt, die in Teil II der Binnenschifffahrtsstraßen-Ordnung als Fahrt \"zu Berg\" oder \"Bergfahrt\" festgelegt ist.","Die Fahrt, die in Teil I der Binnenschifffahrtsstraßen-Ordnung als Fahrt \"zu Berg\" oder \"Bergfahrt\" festgelegt ist.","Die Fahrt in Richtung Quelle.","Die Fahrt gegen die Strömung."],"erklaerung":"Kanäle haben oft keine eindeutige Strömung. Welche Richtung dort „Bergfahrt“ heißt, ist deshalb in Teil II der BinSchStrO (den regionalen Sonderbestimmungen) festgelegt.","stichworte":["Kanal","Bergfahrt festgelegt","BinSchStrO Teil II"]},{"nr":97,"teil":"binnen","thema":"zeichen","frage":"Welche Zeichen begrenzen die Fahrrinne zum rechten Ufer?","inline":[],"bilder":[],"antworten":["Rote Stumpftonnen oder Schwimmstangen.","Grüne Spitztonnen oder Schwimmstangen.","Rote Spierentonnen oder Schwimmstangen.","Grüne Spierentonnen oder Schwimmstangen."],"erklaerung":"Die rechte Fahrrinnenseite ist mit roten Stumpftonnen oder roten Schwimmstangen markiert, die linke mit grünen Spitztonnen. Rechts und links gelten in Talfahrt. Merkhilfe: zu Tal rot rechts.","stichworte":["Rechte Seite","rot","Stumpftonne","Talfahrt"]},{"nr":98,"teil":"binnen","thema":"zeichen","frage":"Welche Zeichen begrenzen die Fahrrinne zum linken Ufer?","inline":[],"bilder":[],"antworten":["Grüne Spitztonnen oder Schwimmstangen.","Rote Stumpftonnen oder Schwimmstangen.","Rote Spierentonnen oder Schwimmstangen.","Grüne Spierentonnen oder Schwimmstangen."],"erklaerung":"Die linke Fahrrinnenseite ist mit grünen Spitztonnen oder grünen Schwimmstangen markiert. Rechts und links gelten in Talfahrt, also von der Quelle zur Mündung gesehen.","stichworte":["Linke Seite","grün","Spitztonne"]},{"nr":99,"teil":"binnen","thema":"zeichen","frage":"Welche Fahrrinnenseite hat ein Bergfahrer an seiner Steuerbordseite und wie ist diese gekennzeichnet?","inline":[],"bilder":[],"antworten":["Die linke Fahrrinnenseite, gekennzeichnet durch grüne Spitztonnen oder Schwimmstangen.","Die rechte Fahrrinnenseite, gekennzeichnet durch rote Stumpftonnen oder Schwimmstangen.","Die linke Fahrrinnenseite, gekennzeichnet durch rote Stumpftonnen oder Schwimmstangen.","Die rechte Fahrrinnenseite, gekennzeichnet durch grüne Spitztonnen oder Schwimmstangen."],"erklaerung":"Wer zu Berg fährt, fährt entgegen der Richtung, in der die Ufer benannt sind. Deshalb hat der Bergfahrer die linke Fahrrinnenseite (grüne Spitztonnen) an Steuerbord und die rote rechte Seite an Backbord.","stichworte":["Bergfahrt","Steuerbord = linke Seite","grüne Spitztonnen"]},{"nr":100,"teil":"binnen","thema":"zeichen","frage":"Was bedeutet eine rot-grün gestreifte Tonne oder Schwimmstange und was ist zu beachten?","inline":[],"bilder":[],"antworten":["Fahrrinnenspaltung. Vorbeifahrt an beiden Seiten möglich.","Fahrrinnenspaltung. In Fahrtrichtung links halten.","Fahrrinnenspaltung. Vorbeifahrt nur an Steuerbord möglich.","Fahrrinnenspaltung. In Fahrtrichtung rechts halten."],"erklaerung":"Eine rot-grün gestreifte Tonne oder Stange markiert eine Fahrrinnenspaltung. Man darf auf beiden Seiten vorbeifahren.","stichworte":["Rot-grün gestreift","Fahrrinnenspaltung","beide Seiten"]},{"nr":101,"teil":"binnen","thema":"zeichen","frage":"Mit welchen Zeichen werden Hindernisse wie zum Beispiel Buhnen und Kribben an der rechten Seite der Wasserstraße bezeichnet?","inline":[],"bilder":[],"antworten":["Stangen mit Toppzeichen: roter Kegel, Spitze nach unten, oder rot-weiß gestreifte Schwimmstange mit rotem Zylinder.","Stangen mit Toppzeichen: grüner Kegel, Spitze nach oben, oder grün-weiß gestreifte Schwimmstange mit grünem Kegel.","Stangen mit Toppzeichen: roter Kegel, Spitze nach oben, oder rot-weiß gestreifte Schwimmstange mit rotem Zylinder.","Stangen mit Toppzeichen: grüner Kegel, Spitze nach unten, oder grün-weiß gestreifte Schwimmstange mit grünem Kegel."],"erklaerung":"Hindernisse wie Buhnen an der rechten Seite werden rot gekennzeichnet: roter Kegel mit Spitze nach unten oder rot-weiß gestreifte Schwimmstange mit rotem Zylinder. Grün mit Spitze nach oben gehört zur linken Seite.","stichworte":["Hindernis rechts","roter Kegel Spitze unten","rot-weiß mit Zylinder"]},{"nr":102,"teil":"binnen","thema":"zeichen","frage":"Was kennzeichnet eine grün-weiß gestreifte Schwimmstange mit grünem Kegel, Spitze nach oben, oder eine grüne Tonne mit grün-weiß gestreiftem Aufsatz mit grünem Kegel, Spitze nach oben?","inline":[],"bilder":[],"antworten":["Hindernis an der linken Seite der Wasserstraße.","Fahrrinnenrand an der linken Seite der Wasserstraße.","Hindernis an der rechten Seite der Wasserstraße.","Fahrrinnenrand an der rechten Seite der Wasserstraße."],"erklaerung":"Grün-weiß gestreift mit grünem Kegel, Spitze nach oben, kennzeichnet ein Hindernis an der linken Seite. Die weißen Streifen bedeuten „Hindernis“ im Unterschied zum reinen Fahrrinnenrand.","stichworte":["Hindernis links","grün-weiß","grüner Kegel Spitze oben"]},{"nr":103,"teil":"binnen","thema":"gewaesser","frage":"Was ist in Kanälen verboten?","inline":[],"bilder":[],"antworten":["Ankern.","Wenden.","Überholen.","Begegnen."],"erklaerung":"In Kanälen ist Ankern verboten, weil der Platz knapp ist und Anker den Verkehr oder die Kanalsohle gefährden würden. Überholen, Begegnen und Wenden sind grundsätzlich erlaubt.","stichworte":["Kanal","Ankerverbot"]},{"nr":104,"teil":"binnen","thema":"lichter","frage":"Was bedeuten auf einem stillliegenden Fahrzeug zwei weiße Lichter übereinander?","inline":[],"bilder":[],"antworten":["Ein Ankerlieger, dessen Anker die Schifffahrt gefährden kann.","Ein stillliegender Schubverband.","Ein Ankerlieger, der zwei Anker ausgelegt hat.","Ein Fahrzeug über 135 m."],"erklaerung":"Laut Katalog zeigen zwei weiße Lichter übereinander auf einem stillliegenden Fahrzeug einen Ankerlieger an, dessen Anker die Schifffahrt gefährden kann. Man fährt also mit Abstand vorbei.","stichworte":["Zwei weiße Lichter übereinander","Anker gefährdet Schifffahrt"]},{"nr":105,"teil":"binnen","thema":"lichter","frage":"Welches Licht setzt ein stillliegendes Fahrzeug?","inline":[],"bilder":[],"antworten":["Ein von allen Seiten sichtbares weißes Rundumlicht auf der Fahrwasserseite.","Ein weißes Topplicht und ein weißes Hecklicht.","Die Seitenlichter und ein sichtbares weißes Rundumlicht.","Ein von allen Seiten sichtbares weißes Blinklicht auf der Fahrwasserseite."],"erklaerung":"Ein stillliegendes Fahrzeug zeigt ein weißes Rundumlicht auf der Seite zum Fahrwasser hin. So sehen vorbeifahrende Schiffe, wo es liegt.","stichworte":["Stillliegend","weißes Rundumlicht","Fahrwasserseite"]},{"nr":106,"teil":"binnen","thema":"lichter","frage":"Wie sind Anker am Tage bezeichnet, die die Schifffahrt behindern können?","inline":[],"bilder":[],"antworten":["Mit einem gelben Döpper.","Mit einem weißen Döpper.","Mit einem grünen Döpper.","Mit einem roten Döpper."],"erklaerung":"Am Tag werden Anker, die die Schifffahrt behindern können, mit einem gelben Döpper (kleine Boje) gekennzeichnet.","stichworte":["Anker","gelber Döpper","Tag"]},{"nr":107,"teil":"binnen","thema":"zeichen","frage":"Was bedeutet dieses Tafelzeichen?","inline":[],"bilder":["bilder/Hinweiszeichen-E057.gif"],"antworten":["Liegestelle für Fahrzeuge mit explosiven Stoffen, für Kleinfahrzeuge verboten.","Liegestelle für Fahrzeuge mit brennbaren Stoffen, für Kleinfahrzeuge verboten.","Liegestelle für Fahrzeuge mit gesundheitsgefährdeten Stoffen, für Kleinfahrzeuge verboten.","Liegestelle für alle Fahrzeuge, für Kleinfahrzeuge verboten."],"erklaerung":"Diese blaue Liegestellentafel mit drei blauen Kegeln gilt für Fahrzeuge mit explosiven Stoffen (drei blaue Kegel bzw. Lichter). Wegen der großen Gefahr ist sie für Kleinfahrzeuge verboten. Merkhilfe: 1 Kegel = brennbar, 2 = gesundheitsschädlich, 3 = explosiv.","stichworte":["Liegestelle","drei Kegel","explosive Stoffe","nicht für Kleinfahrzeuge"]},{"nr":108,"teil":"binnen","thema":"zeichen","frage":"Was bedeuten diese Tafelzeichen?","inline":[],"bilder":["bilder/Hinweiszeichen-E0512.gif","bilder/Hinweiszeichen-E058.gif"],"antworten":["Liegestelle für Fahrzeuge ohne gefährliche Güter, auch für Kleinfahrzeuge.","Liegestelle für Fahrzeuge ohne gefährliche Güter, nicht für Kleinfahrzeuge.","Liegestelle für Fahrzeuge mit gefährlichen Gütern, auch für Kleinfahrzeuge.","Liegestelle für Fahrzeuge mit gefährlichen Gütern, nicht für Kleinfahrzeuge."],"erklaerung":"Diese Tafeln zeigen eine Liegestelle für Fahrzeuge ohne gefährliche Güter (ohne blaue Kegel). Hier dürfen auch Kleinfahrzeuge liegen.","stichworte":["Liegestelle","ohne gefährliche Güter","auch Kleinfahrzeuge"]},{"nr":109,"teil":"binnen","thema":"gewaesser","frage":"Wo besteht ohne besondere Bezeichnung der Stellen bzw. Strecken ein allgemeines Liegeverbot?","inline":[],"bilder":[],"antworten":["Auf Schifffahrtskanälen und Schleusenkanälen.","Auf Schifffahrtskanälen und vor Schleusenkanälen.","Vor Brücken und Hochspannungsleitungen.","Vor Brücken und nach Hochspannungsleitungen."],"erklaerung":"In Schifffahrts- und Schleusenkanälen darf man auch ohne Schild nicht liegen bleiben, weil es dort eng ist und liegende Fahrzeuge den Verkehr behindern würden.","stichworte":["Liegeverbot","Schifffahrtskanal","Schleusenkanal","ohne Schild"]},{"nr":110,"teil":"binnen","thema":"zeichen","frage":"Welche Bedeutung hat das nachstehende Tafelzeichen?","inline":[],"bilder":["bilder/Tafelzeichen-Frage-110.gif"],"antworten":["Empfohlene Durchfahrtsöffnung, Durchfahrt in beide Richtungen erlaubt.","Empfohlene Durchfahrt, Durchfahrt in Gegenrichtung verboten.","Die Durchfahrt ist nur durch diese Brückenöffnung und nur in eine Richtung gestattet.","Die Durchfahrt ist nur durch diese Brückenöffnung und in beide Richtungen gestattet."],"erklaerung":"Ein gelber Rhombus an einer Brücke markiert die empfohlene Durchfahrtsöffnung. Man darf dort in beide Richtungen durchfahren. Merkhilfe: ein Rhombus = mit Gegenverkehr.","stichworte":["Ein gelber Rhombus","empfohlene Durchfahrt","beide Richtungen"]},{"nr":111,"teil":"binnen","thema":"zeichen","frage":"Welche Bedeutung haben die nachstehenden Tafelzeichen?","inline":[],"bilder":["bilder/Empfehlungszeichen-D1b-Rhein-Mosel.jpg"],"antworten":["Empfohlene Durchfahrt, Durchfahrt in Gegenrichtung verboten.","Empfohlene Durchfahrtsöffnung, Durchfahrt in beide Richtungen erlaubt.","Die Durchfahrt ist nur durch diese Brückenöffnung und in beide Richtungen gestattet.","Die Durchfahrt ist nur durch diese Brückenöffnung und nur in eine Richtung gestattet."],"erklaerung":"Zwei gelbe Rhomben (neben- oder übereinander) bedeuten: empfohlene Durchfahrt, aber aus der Gegenrichtung verboten. Merkhilfe: zwei Rhomben = Einbahnstraße.","stichworte":["Zwei gelbe Rhomben","Gegenrichtung verboten","Einbahn"]},{"nr":112,"teil":"binnen","thema":"schleuse","frage":"Was bedeuten diese Tafelzeichen an Brücken?","inline":[],"bilder":["bilder/Verbotszeichen-A10.gif"],"antworten":["Durchfahrt nur zwischen den beiden Tafeln erlaubt.","Durchfahrt nur außerhalb der beiden Tafeln erlaubt.","Empfohlene Durchfahrt nur zwischen den beiden Tafeln.","Empfohlene Durchfahrt mit Gegenverkehr."],"erklaerung":"Rot-weiße Tafeln an Brücken sind verbindlich: Man darf nur zwischen den beiden Tafeln hindurchfahren. Merkhilfe: rot = Pflicht.","stichworte":["Rot-weiße Tafeln","nur zwischen den Tafeln","Pflicht"]},{"nr":113,"teil":"binnen","thema":"schleuse","frage":"Was bedeuten diese Tafelzeichen an Brücken?","inline":[],"bilder":["bilder/Empfehlungszeichen-D2.gif"],"antworten":["Empfohlene Durchfahrt nur zwischen den beiden Tafeln.","Durchfahrt nur zwischen den beiden Tafeln erlaubt.","Durchfahrt nur außerhalb der beiden Tafeln erlaubt.","Empfohlene Durchfahrt mit Gegenverkehr."],"erklaerung":"Grün-weiße Tafeln an Brücken sind nur eine Empfehlung: Am besten fährt man zwischen den beiden Tafeln hindurch. Merkhilfe: grün = Empfehlung, rot = Pflicht.","stichworte":["Grün-weiße Tafeln","empfohlen","zwischen den Tafeln"]},{"nr":114,"teil":"binnen","thema":"schleuse","frage":"Was bedeutet dieses Tafelzeichen an Brücken?","inline":[],"bilder":["bilder/Tafelzeichen-Frage-114.gif"],"antworten":["Empfohlene Durchfahrt mit Gegenverkehr.","Empfohlene Durchfahrt ohne Gegenverkehr.","Empfohlene Durchfahrt nur in eine Richtung.","Durchfahrt nur neben der Tafel erlaubt."],"erklaerung":"Ein einzelner gelber Rhombus heißt: empfohlene Durchfahrt, Gegenverkehr ist möglich.","stichworte":["Ein Rhombus","empfohlen","mit Gegenverkehr"]},{"nr":115,"teil":"binnen","thema":"schleuse","frage":"Was bedeuten diese Tafelzeichen an Brücken?","inline":[],"bilder":["bilder/Tafelzeichen-Frage-115.gif"],"antworten":["Empfohlene Durchfahrt ohne Gegenverkehr.","Empfohlene Durchfahrt mit Gegenverkehr.","Empfohlene Durchfahrt in beide Richtungen.","Durchfahrt nur außerhalb der beiden Tafeln erlaubt."],"erklaerung":"Zwei gelbe Rhomben nebeneinander heißen: empfohlene Durchfahrt ohne Gegenverkehr, weil die Gegenrichtung gesperrt ist.","stichworte":["Zwei Rhomben","empfohlen","ohne Gegenverkehr"]},{"nr":116,"teil":"binnen","thema":"schleuse","frage":"Was bedeutet dieses Tafelzeichen im Bereich eines Wehres?","inline":[],"bilder":["bilder/Verbotszeichen-A01-Tafeln.gif"],"antworten":["Verbot der Durchfahrt und Sperrung der Schifffahrt.","Gesperrte Wasserfläche, jedoch für Kleinfahrzeuge mit Antriebsmaschine befahrbar.","Gesperrte Wasserfläche, jedoch für Kleinfahrzeuge ohne Antriebsmaschine befahrbar.","Schutzbedürftige Anlage."],"erklaerung":"Rot-weiß-rot bedeutet immer: Durchfahrt verboten, Schifffahrt gesperrt. Am Wehr ist das lebenswichtig, weil die Strömung ein Boot über das Wehr ziehen kann.","stichworte":["Rot-weiß-rot","Durchfahrt verboten","Wehr"]},{"nr":117,"teil":"binnen","thema":"schleuse","frage":"Welche Bedeutung haben vor einer Schleuse ein rotes oder ein rotes und ein grünes Licht?","inline":[],"bilder":[],"antworten":["Einfahrt verboten, Öffnen der Schleuse wird vorbereitet.","Einfahrt verboten, Schließen der Schleuse wird vorbereitet.","Ausfahrt verboten, Öffnen der Schleuse wird vorbereitet.","Ausfahrt verboten, Schließen der Schleuse wird vorbereitet."],"erklaerung":"Rot heißt: Einfahrt verboten. Erscheint zusätzlich Grün (rot und grün), wird die Schleuse gerade zur Einfahrt vorbereitet bzw. geöffnet. Grün kommt also gleich, bis dahin wird gewartet.","stichworte":["Rot / Rot+Grün","Einfahrt verboten","Öffnen wird vorbereitet"]},{"nr":118,"teil":"binnen","thema":"schleuse","frage":"In welcher Reihenfolge fahren Fahrzeuge, die nicht Kleinfahrzeuge sind, und Kleinfahrzeuge, die gemeinsam geschleust werden sollen, in die Schleuse ein?","inline":[],"bilder":[],"antworten":["Kleinfahrzeuge fahren erst nach den Fahrzeugen, die nicht Kleinfahrzeuge sind und nach Aufforderung durch die Schleusenaufsicht in die Schleuse ein.","Kleinfahrzeuge fahren vor den Fahrzeugen, die nicht Kleinfahrzeuge sind und vor Aufforderung durch die Schleusenaufsicht in die Schleuse ein.","Kleinfahrzeuge fahren vor den Fahrzeugen, die nicht Kleinfahrzeuge sind und ohne Aufforderung durch die Schleusenaufsicht in die Schleuse ein.","Kleinfahrzeuge fahren nach den Fahrzeugen, die nicht Kleinfahrzeuge sind und ohne Aufforderung durch die Schleusenaufsicht in die Schleuse ein."],"erklaerung":"Bei gemeinsamer Schleusung fahren Kleinfahrzeuge erst nach den großen Fahrzeugen ein, und zwar erst, wenn die Schleusenaufsicht sie dazu auffordert.","stichworte":["Schleuse","Kleinfahrzeuge zuletzt","nach Aufforderung"]},{"nr":119,"teil":"binnen","thema":"schleuse","frage":"Mehrere Kleinfahrzeuge sollen gemeinsam vom Oberwasser in das Unterwasser geschleust werden. Worauf ist bei deren Einfahrt in die Schleuse und während des Schleusens besonders zu achten?","inline":[],"bilder":[],"antworten":["Das letzte Kleinfahrzeug muss so weit einfahren, dass es beim Leeren der Schleuse nicht auf den Drempel aufsetzen kann. Die Festmacherleinen sind so zu bedienen, dass Stöße gegen Schleusenwände, Schleusentore, andere Fahrzeuge vermieden werden und ein sicheres Fieren der Leinen möglich ist.","Das erste Kleinfahrzeug muss so weit einfahren, dass es beim Leeren der Schleuse nicht auf den Drempel aufsetzen kann. Die Festmacherleinen sind so zu bedienen, dass Stöße gegen Schleusenwände, Schleusentore, andere Fahrzeuge vermieden werden und ein sicheres Fieren der Leinen möglich ist.","Das erste Kleinfahrzeug muss so weit einfahren, dass es beim Füllen der Schleuse nicht auf den Drempel aufsetzen kann. Die Festmacherleinen sind so zu bedienen, dass Stöße gegen Schleusenwände, Schleusentore, andere Fahrzeuge vermieden werden und ein sicheres Fieren der Leinen möglich ist.","Das letzte Kleinfahrzeug muss so weit einfahren, dass es beim Füllen der Schleuse nicht auf den Drempel aufsetzen kann. Die Festmacherleinen sind so zu bedienen, dass Stöße gegen Schleusenwände, Schleusentore, andere Fahrzeuge vermieden werden und ein sicheres Fieren der Leinen möglich ist."],"erklaerung":"Abwärts (vom Oberwasser ins Unterwasser) sinkt das Wasser in der Schleuse. Am oberen Tor liegt eine Schwelle (Drempel), auf der ein Boot aufsetzen kann, wenn es zu weit hinten liegt. Deshalb muss auch das letzte Boot weit genug einfahren. Die Leinen werden außerdem so geführt, dass man sie beim Absinken sicher fieren kann.","stichworte":["Abwärtsschleusen","Drempel","letztes Boot weit einfahren","Leinen fieren"]},{"nr":120,"teil":"binnen","thema":"lichter","frage":"Was bedeuten diese Lichter?","inline":[],"bilder":["bilder/Lichter-Frage-120.gif"],"antworten":["Fahrzeug mit Maschinenantrieb länger als 110 m.","Schubverband kürzer als 110 m.","Schubverband länger als 110 m.","Fahrzeug ohne Maschinenantrieb länger als 110 m."],"erklaerung":"Zwei weiße Topplichter übereinander (dazu die Seitenlichter) zeigt ein Maschinenfahrzeug, das länger als 110 m ist. Kürzere Maschinenfahrzeuge führen nur ein Topplicht.","stichworte":["Zwei Topplichter","Maschinenfahrzeug","über 110 m"]},{"nr":121,"teil":"binnen","thema":"lichter","frage":"Was bedeutet dieses Sichtzeichen?","inline":[],"bilder":["bilder/Bild-004-Tag.gif"],"antworten":["Schleppfahrzeug an der Spitze eines Schleppverbandes.","Fahrzeug, das vor Anker liegt.","Fahrzeuge mit Vorrang an einer Schleuse.","Fahrzeug eines Schleppverbandes."],"erklaerung":"Ein gelber Zylinder mit schwarzen Streifen am Mast kennzeichnet am Tag das Schleppfahrzeug an der Spitze eines Schleppverbandes.","stichworte":["Gelber Zylinder","Schleppfahrzeug an der Spitze"]},{"nr":122,"teil":"binnen","thema":"lichter","frage":"Was bedeutet dieses Sichtzeichen?","inline":[],"bilder":["bilder/Bild-006-Tag.gif"],"antworten":["Fahrzeug eines Schleppverbandes.","Fahrzeug, das vor Anker liegt.","Fahrzeuge mit Vorrang an einer Schleuse.","Schleppfahrzeug an der Spitze eines Schleppverbandes."],"erklaerung":"Ein gelber Ball kennzeichnet am Tag ein geschlepptes Fahrzeug eines Schleppverbandes. Zwischen den Fahrzeugen verläuft eine Schleppleine, also nie dazwischen hindurchfahren!","stichworte":["Gelber Ball","geschlepptes Fahrzeug","Schleppverband"]},{"nr":123,"teil":"binnen","thema":"lichter","frage":"Was bedeuten diese Lichter?","inline":[],"bilder":["bilder/Lichter-Frage-123.gif"],"antworten":["Schubverband in Fahrt von vorne.","Schubverband in Fahrt von achtern.","Schubverband vor Anker liegend.","Schubverband unter 110 m Länge."],"erklaerung":"Drei weiße Topplichter im Dreieck kennzeichnen einen Schubverband. Sieht man dazu Rot und Grün, kommt er von vorne auf einen zu.","stichworte":["Drei Topplichter im Dreieck","Schubverband","von vorne"]},{"nr":124,"teil":"binnen","thema":"lichter","frage":"Was bedeuten diese Lichter?","inline":[],"bilder":["bilder/Lichter-Frage-124.gif"],"antworten":["Nicht frei fahrende Fähre.","Frei fahrende Fähre.","Schubverband von achtern.","Schubverband von Steuerbordseite."],"erklaerung":"Grün über Weiß als Rundumlichter ohne Seitenlichter zeigt eine nicht frei fahrende Fähre, die z. B. an einem Seil geführt wird. Vorsicht beim Seil!","stichworte":["Grün über Weiß","ohne Seitenlichter","nicht frei fahrende Fähre"]},{"nr":125,"teil":"binnen","thema":"lichter","frage":"Was bedeuten diese Lichter?","inline":[],"bilder":["bilder/Lichter-Frage-125.gif"],"antworten":["Frei fahrende Fähre.","Nicht frei fahrende Fähre.","Schubverband von achtern.","Schubverband von Steuerbordseite."],"erklaerung":"Grün über Weiß zusammen mit Seitenlichtern zeigt eine frei fahrende Fähre. Sie fährt also selbstständig mit eigenem Antrieb.","stichworte":["Grün über Weiß","mit Seitenlichtern","frei fahrende Fähre"]},{"nr":126,"teil":"binnen","thema":"lichter","frage":"Was bedeutet auf einem Fahrzeug ein blaues Licht?","inline":[],"bilder":[],"antworten":["Fahrzeug hat brennbare Stoffe geladen. Abstand beim Stillliegen 10 m.","Fahrzeug hat gesundheitsschädliche Stoffe geladen. Abstand beim Stillliegen 50 m.","Fahrzeug hat explosive Stoffe geladen. Abstand beim Stillliegen 100 m.","Fahrzeug der Überwachungsbehörden im Einsatz."],"erklaerung":"Ein blaues Licht bedeutet, dass das Fahrzeug brennbare Stoffe geladen hat. Beim Stillliegen hält man mindestens 10 m Abstand. Merkhilfe: 1–2–3 blaue Lichter = 10–50–100 m.","stichworte":["1 blaues Licht","brennbar","10 m"]},{"nr":127,"teil":"binnen","thema":"lichter","frage":"Was bedeutet dieses Sichtzeichen?","inline":[],"bilder":["bilder/Bild-027a-Tag.gif"],"antworten":["Fahrzeug hat brennbare Stoffe geladen, Abstand beim Stillliegen 10 m.","Fahrzeug hat gesundheitsschädliche Stoffe geladen, Abstand beim Stillliegen 50 m.","Fahrzeug hat explosive Stoffe geladen. Abstand beim Stillliegen 100 m.","Fahrzeug der Überwachungsbehörden im Einsatz."],"erklaerung":"Ein blauer Kegel (Spitze unten) ist das Tageszeichen für brennbare Stoffe, wie ein blaues Licht in der Nacht. Abstand beim Stillliegen 10 m.","stichworte":["1 blauer Kegel","brennbar","10 m"]},{"nr":128,"teil":"binnen","thema":"lichter","frage":"Was bedeuten auf einem Fahrzeug zwei blaue Lichter übereinander?","inline":[],"bilder":[],"antworten":["Fahrzeug hat gesundheitsschädliche Stoffe geladen, Abstand beim Stillliegen 50 m.","Fahrzeug hat explosive Stoffe geladen, Abstand beim Stillliegen 100 m.","Fahrzeug hat brennbare Stoffe geladen, Abstand beim Stillliegen 10 m.","Fahrzeug der Überwachungsbehörden im Einsatz."],"erklaerung":"Zwei blaue Lichter übereinander bedeuten gesundheitsschädliche Stoffe. Beim Stillliegen hält man 50 m Abstand.","stichworte":["2 blaue Lichter","gesundheitsschädlich","50 m"]},{"nr":129,"teil":"binnen","thema":"lichter","frage":"Was bedeutet dieses Sichtzeichen?","inline":[],"bilder":["bilder/Bild-028a-Tag.gif"],"antworten":["Fahrzeug hat gesundheitsschädliche Stoffe geladen, Abstand beim Stillliegen 50 m.","Fahrzeug hat explosive Stoffe geladen, Abstand beim Stillliegen 100 m.","Fahrzeug hat brennbare Stoffe geladen, Abstand beim Stillliegen 10 m.","Fahrzeug der Überwachungsbehörden im Einsatz."],"erklaerung":"Zwei blaue Kegel übereinander sind das Tageszeichen für gesundheitsschädliche Stoffe. Abstand beim Stillliegen 50 m.","stichworte":["2 blaue Kegel","gesundheitsschädlich","50 m"]},{"nr":130,"teil":"binnen","thema":"lichter","frage":"Was bedeuten auf einem Fahrzeug drei blaue Lichter übereinander?","inline":[],"bilder":[],"antworten":["Fahrzeug hat explosive Stoffe geladen, Abstand beim Stillliegen 100 m.","Fahrzeug hat gesundheitsschädliche Stoffe geladen, Abstand beim Stillliegen 50 m.","Fahrzeug hat brennbare Stoffe geladen, Abstand beim Stillliegen 10 m.","Fahrzeug der Überwachungsbehörden im Einsatz."],"erklaerung":"Drei blaue Lichter übereinander bedeuten explosive Stoffe, die höchste Gefahrenstufe. Beim Stillliegen hält man 100 m Abstand.","stichworte":["3 blaue Lichter","explosiv","100 m"]},{"nr":131,"teil":"binnen","thema":"lichter","frage":"Was bedeutet dieses Sichtzeichen?","inline":[],"bilder":["bilder/Bild-029a-Tag.gif"],"antworten":["Fahrzeug hat explosive Stoffe geladen, Abstand beim Stillliegen 100 m.","Fahrzeug hat gesundheitsschädliche Stoffe geladen, Abstand beim Stillliegen 50 m.","Fahrzeug hat brennbare Stoffe geladen, Abstand beim Stillliegen 10 m.","Fahrzeug der Überwachungsbehörden im Einsatz."],"erklaerung":"Drei blaue Kegel übereinander sind das Tageszeichen für explosive Stoffe. Abstand beim Stillliegen 100 m.","stichworte":["3 blaue Kegel","explosiv","100 m"]},{"nr":132,"teil":"binnen","thema":"lichter","frage":"Welches Fahrzeug führt die nachstehende Tagbezeichnung?","inline":[],"bilder":["bilder/Bild-037-Tag.gif"],"antworten":["Ein Fahrzeug, dem die zuständige Behörde einen Vorrang zur Durchfahrt durch Stellen an denen eine bestimmte Reihenfolge gilt eingeräumt hat.","Fahrzeug unter 20 m Länge, für mehr als 12 Fahrgäste zugelassen.","Geschlepptes Fahrzeug eines Schleppverbandes.","Festgefahrenes Fahrzeug, das einseitig nicht passierbar ist."],"erklaerung":"Ein roter Wimpel zeigt, dass die Behörde dem Fahrzeug Vorrang an Stellen eingeräumt hat, an denen sonst eine Reihenfolge gilt, z. B. an Schleusen. Es darf sich also vordrängeln.","stichworte":["Roter Wimpel","Vorrang","Schleuse"]},{"nr":133,"teil":"binnen","thema":"lichter","frage":"Ein Kleinfahrzeug unter Segel fährt nachts auf einer Binnenschifffahrtsstraße und führt ein weißes Rundumlicht im Topp. Wie wird zweckmäßigerweise die weiße Handlampe, die bei Annäherung anderer Fahrzeuge gezeigt werden muss, benutzt?","inline":[],"bilder":[],"antworten":["Die eigenen Segel anleuchten.","Das Wasser anleuchten.","Das heranfahrende Fahrzeug anleuchten.","Die Handlampe nach oben halten."],"erklaerung":"Mit der weißen Handlampe leuchtet man die eigenen Segel an. Die große helle Fläche ist von Weitem gut zu sehen, und das andere Fahrzeug wird nicht geblendet.","stichworte":["Handlampe","Segel anleuchten","nicht blenden"]},{"nr":134,"teil":"binnen","thema":"lichter","frage":"Ein Kleinfahrzeug unter Segel fährt nachts auf einer Binnenschifffahrtsstraße und führt ein weißes Rundumlicht im Topp. Welche zusätzlichen Lichter müssen gesetzt werden, wenn der Motor angeworfen wird?","inline":[],"bilder":[],"antworten":["Seitenlichter unmittelbar nebeneinander oder in einer einzigen Laterne.","Es muss ein weißes Funkellicht geführt werden.","Es muss kein weiteres Licht geführt werden.","Es muss ein zweites weißes Topplicht geführt werden."],"erklaerung":"Läuft der Motor, gilt der Segler als Kleinfahrzeug mit Maschinenantrieb. Zum weißen Rundumlicht kommen dann die Seitenlichter dazu, nebeneinander oder in einer Zweifarbenlaterne.","stichworte":["Motor an","Seitenlichter dazu","Zweifarbenlaterne"]},{"nr":135,"teil":"binnen","thema":"lichter","frage":"Welche Lichter muss ein Kleinfahrzeug unter Motor führen, wenn es ein anderes Kleinfahrzeug ohne Maschinenantrieb schleppt?","inline":[],"bilder":[],"antworten":["Lichter eines Kleinfahrzeugs mit Maschinenantrieb.","Zwei weiße Lichter übereinander.","Weißes Rundumlicht.","Lichter eines Kleinfahrzeugs mit Maschinenantrieb und ein zweites weißes Topplicht."],"erklaerung":"Ein Kleinfahrzeug, das ein anderes Kleinfahrzeug schleppt, führt einfach die normalen Lichter eines Kleinfahrzeugs mit Maschinenantrieb. Ein zusätzliches Schlepplicht ist nicht nötig.","stichworte":["Kleinfahrzeug schleppt","normale Motorlichter"]},{"nr":136,"teil":"binnen","thema":"lichter","frage":"Welche Lichter muss ein geschlepptes Kleinfahrzeug führen?","inline":[],"bilder":[],"antworten":["Weißes Rundumlicht.","Lichter eines Kleinfahrzeugs mit Maschinenantrieb.","Zwei weiße Lichter übereinander.","Weißes Funkellicht."],"erklaerung":"Ein geschlepptes Kleinfahrzeug führt nur ein weißes Rundumlicht.","stichworte":["Geschlepptes Kleinfahrzeug","weißes Rundumlicht"]},{"nr":137,"teil":"binnen","thema":"recht","frage":"Wann gilt ein Sportboot auf den Binnenschifffahrtsstraßen nicht mehr als Kleinfahrzeug?","inline":[],"bilder":[],"antworten":["Wenn es 20 m oder länger ist.","Wenn es 15 m oder länger ist.","Wenn es 10 m oder länger ist.","Wenn es 18 m oder länger ist."],"erklaerung":"Auf Binnenschifffahrtsstraßen gilt ein Fahrzeug unter 20 m Länge als Kleinfahrzeug. Ab 20 m ist es kein Kleinfahrzeug mehr. Die Grenze von 20 m gilt auch für den SBF Binnen.","stichworte":["Kleinfahrzeug","unter 20 m"]},{"nr":138,"teil":"binnen","thema":"lichter","frage":"Welchen Sichtwinkel und welche Farben haben die vorgeschriebenen Lichter an Bord?","inline":[],"bilder":[],"antworten":["Topplicht: weiß 225°, Hecklicht 135° weiß, Seitenlichter: Backbord rot und Steuerbord grün, jeweils 112,5°.","Topplicht: weiß 135°, Hecklicht 225° weiß, Seitenlichter: Backbord rot und Steuerbord grün, jeweils 112,5°","Topplicht: weiß 225°, Hecklicht 112,5° weiß, Seitenlichter: Backbord rot und Steuerbord grün, jeweils 135°","Topplicht: weiß 112,5°, Hecklicht 225° weiß, Seitenlichter: Backbord rot und Steuerbord grün, jeweils 112,5°"],"erklaerung":"Das Topplicht leuchtet über 225° nach vorne, das Hecklicht über 135° nach hinten, zusammen also 360°. Die Seitenlichter decken je 112,5° ab (zusammen 225°, wie das Topplicht). Backbord ist rot, Steuerbord grün.","stichworte":["Topplicht 225°","Hecklicht 135°","Seitenlichter je 112,5°"]},{"nr":139,"teil":"binnen","thema":"lichter","frage":"Welches Licht muss ein Kleinfahrzeug ohne Maschinenantrieb mindestens führen?","inline":[],"bilder":[],"antworten":["Ein von allen Seiten sichtbares weißes Licht.","Dreifarbenlaterne im Topp.","Seitenlichter.","Topp- und Hecklicht."],"erklaerung":"Ein Kleinfahrzeug ohne Maschinenantrieb (Ruder- oder Segelboot) muss mindestens ein weißes Licht führen, das von allen Seiten sichtbar ist.","stichworte":["Ohne Motor","mindestens weißes Rundumlicht"]},{"nr":140,"teil":"binnen","thema":"fahrregeln","frage":"Wie muss sich ein Segelfahrzeug auf einer Binnenschifffahrtsstraße, welches sich auf Kollisionskurs mit einem Kleinfahrzeug mit Maschinenantrieb befindet, verhalten?","inline":[],"bilder":[],"antworten":["Es hält Kurs und Geschwindigkeit bei.","Es wechselt den Kurs nach Steuerbord und reduziert die Geschwindigkeit.","Es hält Kurs und reduziert die Geschwindigkeit.","Es wechselt den Kurs nach Steuerbord und hält die Geschwindigkeit."],"erklaerung":"Auf Binnenschifffahrtsstraßen müssen Kleinfahrzeuge mit Maschinenantrieb Kleinfahrzeugen unter Segel ausweichen. Der Segler ist kurshaltepflichtig und behält Kurs und Geschwindigkeit bei, damit der andere sicher ausweichen kann.","stichworte":["Motor weicht Segel","Kurs und Geschwindigkeit halten"]},{"nr":141,"teil":"binnen","thema":"fahrregeln","frage":"Wie muss sich ein Fahrzeug mit Topplicht und Seitenlichtern gegenüber einem Kleinfahrzeug mit Seitenlichtern, welches sich auf Kollisionskurs befindet, verhalten?","inline":[],"bilder":[],"antworten":["Es hält Kurs und Geschwindigkeit bei.","Es wechselt den Kurs nach Steuerbord und reduziert die Geschwindigkeit.","Es hält Kurs und reduziert die Geschwindigkeit.","Es muss ausweichen."],"erklaerung":"Gemeint ist ein Fahrzeug, das kein Kleinfahrzeug ist. Kleinfahrzeuge müssen solchen Fahrzeugen ausweichen. Das Fahrzeug mit Topplicht und Seitenlichtern hält also Kurs und Geschwindigkeit, das Kleinfahrzeug weicht aus.","stichworte":["Großes Fahrzeug","Kleinfahrzeug weicht aus","Kurs halten"]},{"nr":142,"teil":"binnen","thema":"fahrregeln","frage":"Wie muss sich ein Kleinfahrzeug mit Maschinenantrieb gegenüber einem Segelsurfer, der auf Kollisionskurs liegt, verhalten?","inline":[],"bilder":[],"antworten":["Es muss ausweichen.","Es hält Kurs und Geschwindigkeit bei.","Es hält Kurs und reduziert die Geschwindigkeit.","Es muss nicht ausweichen."],"erklaerung":"Ein Segelsurfer gilt als Kleinfahrzeug unter Segel. Kleinfahrzeuge mit Maschinenantrieb müssen ihm deshalb ausweichen.","stichworte":["Segelsurfer = Segler","Motor weicht aus"]},{"nr":143,"teil":"binnen","thema":"fahrregeln","frage":"Wer ist ausweichpflichtig, wenn ein Segler mit Wind von Backbord einer Segelyacht mit Wind von Steuerbord und einem schwarzen Kegel auf Kollisionskurs begegnet?","inline":[],"bilder":[],"antworten":["Die Segelyacht mit Wind von Steuerbord, weil sie als Kleinfahrzeug mit Maschinenantrieb gilt.","Die Segelyacht mit Wind von Backbord, weil sie als Kleinfahrzeug unter Segel gilt.","Die Segelyacht mit Wind von Steuerbord, weil sie als Kleinfahrzeug unter Segel gilt.","Beide Segelyachten, weil eines als Kleinfahrzeug mit Maschinenantrieb gilt und das andere den Wind von Backbord hat."],"erklaerung":"Die Yacht mit dem schwarzen Kegel fährt mit Motor und gilt als Kleinfahrzeug mit Maschinenantrieb. Sie muss dem Segler ausweichen, egal von welcher Seite der Wind kommt.","stichworte":["Schwarzer Kegel","gilt als Motorboot","muss ausweichen"]},{"nr":144,"teil":"binnen","thema":"fahrregeln","frage":"Wie lautet eine der drei Grundregeln der Binnenschifffahrtsstraßen-Ordnung, nach denen Kleinfahrzeuge unter Segel einander ausweichen?","inline":[],"bilder":[],"antworten":["Wenn sie den Wind nicht von derselben Seite haben, muss das Segelfahrzeug mit Wind von Backbord dem Segelfahrzeug mit Wind von Steuerbord ausweichen.","Wenn sie den Wind nicht von derselben Seite haben, muss das Segelfahrzeug mit Wind von Steuerbord dem Segelfahrzeug mit Wind von Backbord ausweichen.","Wenn sie den Wind von derselben Seite haben, muss das leeseitige dem luvseitigen ausweichen.","Wenn sie den Wind von derselben Seite haben, müssen beide Fahrzeuge ausweichen."],"erklaerung":"Bei Seglern mit Wind von verschiedenen Seiten weicht der aus, der den Wind von Backbord hat. Merkhilfe: Backbordbug weicht aus. Bei Wind von derselben Seite weicht der Luvseitige aus.","stichworte":["Wind von Backbord weicht aus","Steuerbordbug hat Vorrang"]},{"nr":145,"teil":"binnen","thema":"lichter","frage":"Was bedeuten diese Lichter?","inline":[],"bilder":["bilder/Bild-051-Nacht.gif"],"antworten":["Schwimmendes Gerät bei der Arbeit. Vorbeifahrt an jeder Seite gestattet. Sog und Wellenschlag vermeiden.","Schwimmendes Gerät bei der Arbeit. Vorbeifahrt nicht gestattet.","Festgefahrenes oder gesunkenes Fahrzeug. Vorbeifahrt an der Steuerbordseite gestattet. Sog und Wellenschlag vermeiden.","Festgefahrenes oder gesunkenes Fahrzeug. Vorbeifahrt nicht gestattet."],"erklaerung":"Rot über Weiß bedeutet: hier darf man vorbeifahren, aber Sog und Wellenschlag vermeiden. Sind diese Lichter auf beiden Seiten, ist es laut Katalog ein schwimmendes Gerät bei der Arbeit, das an beiden Seiten passiert werden darf, langsam! Merkhilfe: Grün = frei, Rot-Weiß = frei, aber langsam, Rot allein = gesperrt.","stichworte":["Rot über Weiß beidseitig","beide Seiten passierbar","Sog vermeiden"]},{"nr":146,"teil":"binnen","thema":"lichter","frage":"Was bedeuten diese Sichtzeichen?","inline":[],"bilder":["bilder/Bild-051-Tag.gif"],"antworten":["Schwimmendes Gerät bei der Arbeit. Vorbeifahrt an jeder Seite gestattet. Sog und Wellenschlag vermeiden.","Schwimmendes Gerät bei der Arbeit. Vorbeifahrt nicht gestattet.","Festgefahrenes oder gesunkenes Fahrzeug. Vorbeifahrt an der Steuerbordseite gestattet. Sog und Wellenschlag vermeiden.","Festgefahrenes oder gesunkenes Fahrzeug. Vorbeifahrt nicht gestattet."],"erklaerung":"Am Tag zeigt eine rot-weiße Flagge auf beiden Seiten: schwimmendes Gerät bei der Arbeit, auf beiden Seiten passierbar, aber Sog und Wellenschlag vermeiden. Die Flagge entspricht den Lichtern Rot über Weiß.","stichworte":["Rot-weiße Flaggen beidseitig","beide Seiten","Sog vermeiden"]},{"nr":147,"teil":"binnen","thema":"lichter","frage":"Was bedeuten diese Lichter?","inline":[],"bilder":["bilder/Bild-052-Nacht.gif"],"antworten":["Festgefahrenes oder gesunkenes Fahrzeug. Vorbeifahrt an der rot-weißen Seite gestattet; rote Seite gesperrt. Sog und Wellenschlag vermeiden.","Festgefahrenes oder gesunkenes Fahrzeug. Vorbeifahrt an der rot-weißen Seite gestattet; rote Seite gesperrt. Vorbeifahrt mit unverminderter Geschwindigkeit möglich.","Festgefahrenes oder gesunkenes Fahrzeug. Vorbeifahrt an der roten Seite gestattet; rot-weiße Seite gesperrt. Vorbeifahrt mit unverminderter Geschwindigkeit möglich.","Festgefahrenes oder gesunkenes Fahrzeug. Vorbeifahrt an der roten Seite gestattet; rot-weiße Seite gesperrt. Sog und Wellenschlag vermeiden."],"erklaerung":"Rot allein kennzeichnet die gesperrte Seite, Rot über Weiß die freie Seite, an der man langsam vorbeifährt. So gekennzeichnet ist ein festgefahrenes oder gesunkenes Fahrzeug.","stichworte":["Festgefahren/gesunken","rot-weiße Seite frei","rote Seite gesperrt"]},{"nr":148,"teil":"binnen","thema":"lichter","frage":"Was bedeuten diese Sichtzeichen?","inline":[],"bilder":["bilder/Bild-052-Tag.gif"],"antworten":["Festgefahrenes oder gesunkenes Fahrzeug. Vorbeifahrt an der rot-weißen Seite gestattet; rote Seite gesperrt. Sog und Wellenschlag vermeiden.","Festgefahrenes oder gesunkenes Fahrzeug. Vorbeifahrt an der rot-weißen Seite gestattet; rote Seite gesperrt. Vorbeifahrt mit unverminderter Geschwindigkeit möglich.","Festgefahrenes oder gesunkenes Fahrzeug. Vorbeifahrt an der roten Seite gestattet; rot-weiße Seite gesperrt. Vorbeifahrt mit unverminderter Geschwindigkeit möglich.","Festgefahrenes oder gesunkenes Fahrzeug. Vorbeifahrt an der roten Seite gestattet; rot-weiße Seite gesperrt. Sog und Wellenschlag vermeiden."],"erklaerung":"Am Tag zeigt eine rote Flagge die gesperrte Seite, eine rot-weiße Flagge die Seite, an der man vorbeifahren darf, mit wenig Sog und Wellenschlag. So zeigt sich ein festgefahrenes oder gesunkenes Fahrzeug.","stichworte":["Rote Flagge = gesperrt","rot-weiße Flagge = frei","Sog vermeiden"]},{"nr":149,"teil":"binnen","thema":"lichter","frage":"Was bedeuten diese Lichter?","inline":[],"bilder":["bilder/Bild-050a-Nacht.gif"],"antworten":["Schwimmendes Gerät bei der Arbeit. Vorbeifahrt an der grünen Seite gestattet; rote Seite gesperrt.","Schwimmendes Gerät bei der Arbeit. Vorbeifahrt an der grünen Seite gestattet; rote Seite gesperrt. Sog und Wellenschlag vermeiden.","Schwimmendes Gerät bei der Arbeit. Vorbeifahrt an der grünen Seite gestattet. Vorbeifahrt an der roten Seite mit unverminderter Geschwindigkeit möglich.","Schwimmendes Gerät bei der Arbeit. Vorbeifahrt an der roten Seite gestattet; grüne Seite gesperrt."],"erklaerung":"Zwei grüne Lichter zeigen die freie Seite, ein rotes Licht die gesperrte. Weil Grün statt Rot-Weiß gezeigt wird, ist kein besonderer Schutz vor Sog nötig. Das ist die Nachtbezeichnung eines schwimmenden Geräts bei der Arbeit.","stichworte":["Grün = frei","Rot = gesperrt","schwimmendes Gerät"]},{"nr":150,"teil":"binnen","thema":"lichter","frage":"Was bedeuten diese Sichtzeichen?","inline":[],"bilder":["bilder/Bild-050b-Tag.gif"],"antworten":["Schwimmendes Gerät bei der Arbeit. Vorbeifahrt an der grünen Seite gestattet; rote Seite gesperrt.","Schwimmendes Gerät bei der Arbeit. Vorbeifahrt an der grünen Seite gestattet; rote Seite gesperrt. Sog und Wellenschlag vermeiden.","Schwimmendes Gerät bei der Arbeit. Vorbeifahrt an der grünen Seite gestattet. Vorbeifahrt an der roten Seite mit unverminderter Geschwindigkeit möglich.","Schwimmendes Gerät bei der Arbeit. Vorbeifahrt an der roten Seite gestattet; grüne Seite gesperrt."],"erklaerung":"Am Tag stehen zwei grüne Rhomben für die freie Seite und ein roter Ball für die gesperrte Seite: schwimmendes Gerät bei der Arbeit.","stichworte":["Grüne Rhomben = frei","roter Ball = gesperrt","Tag"]},{"nr":151,"teil":"binnen","thema":"lichter","frage":"Was bedeuten im Fahrwasser nachstehende Zeichen?","inline":[],"bilder":["bilder/Bild-050a-Tag.gif"],"antworten":["Schwimmendes Gerät bei der Arbeit. Vorbeifahrt an der Seite mit dem grün-weiß-grünen Tafelzeichen gestattet; rot-weiß-rote Seite gesperrt.","Festgefahrenes oder gesunkenes Fahrzeug. Vorbeifahrt an der Seite mit dem grün-weiß-grünen Tafelzeichen gestattet; rot-weiß-rote Seite gesperrt. Sog und Wellenschlag vermeiden.","Schwimmendes Gerät bei der Arbeit. Vorbeifahrt an der Seite mit dem grün-weiß-grünen Tafelzeichen gestattet; rot-weiß-rote Seite gesperrt. Sog und Wellenschlag vermeiden.","Festgefahrenes oder gesunkenes Fahrzeug. Vorbeifahrt an der Seite mit dem rot-weiß-roten Tafelzeichen gestattet; grün-weiß-grüne Seite gesperrt."],"erklaerung":"Die grün-weiß-grüne Tafel zeigt die freie Seite, die rot-weiß-rote die gesperrte. Diese Tafeln kann ein schwimmendes Gerät bei der Arbeit statt der Flaggen bzw. Bälle zeigen.","stichworte":["Grün-weiß-grün = frei","rot-weiß-rot = gesperrt","Tafeln"]},{"nr":152,"teil":"binnen","thema":"lichter","frage":"Was bedeuten diese Lichter?","inline":[],"bilder":["bilder/Bild-049a-Nacht.gif"],"antworten":["Schwimmendes Gerät bei der Arbeit. Vorbeifahrt an jeder Seite gestattet.","Schwimmendes Gerät bei der Arbeit. Vorbeifahrt nicht gestattet.","Festgefahrenes oder gesunkenes Fahrzeug. Vorbeifahrt an der Steuerbordseite gestattet.","Festgefahrenes oder gesunkenes Fahrzeug. Vorbeifahrt nicht gestattet."],"erklaerung":"Zwei grüne Lichter auf beiden Seiten bedeuten: schwimmendes Gerät bei der Arbeit, auf beiden Seiten darf man vorbei.","stichworte":["Grün beidseitig","beide Seiten frei","schwimmendes Gerät"]},{"nr":153,"teil":"binnen","thema":"lichter","frage":"Was bedeuten diese Sichtzeichen?","inline":[],"bilder":["bilder/Bild-049b-Tag.gif"],"antworten":["Schwimmendes Gerät bei der Arbeit. Vorbeifahrt an jeder Seite gestattet.","Schwimmendes Gerät bei der Arbeit. Vorbeifahrt nicht gestattet.","Festgefahrenes oder gesunkenes Fahrzeug. Vorbeifahrt an der Steuerbordseite gestattet.","Festgefahrenes oder gesunkenes Fahrzeug. Vorbeifahrt nicht gestattet."],"erklaerung":"Zwei grüne Rhomben auf beiden Seiten sind das Tageszeichen dafür, dass man auf beiden Seiten am schwimmenden Gerät vorbeifahren darf.","stichworte":["Grüne Rhomben beidseitig","beide Seiten frei"]},{"nr":154,"teil":"binnen","thema":"lichter","frage":"Was bedeuten diese Sichtzeichen?","inline":[],"bilder":["bilder/Bild-049a-Tag.gif"],"antworten":["Schwimmendes Gerät bei der Arbeit. Vorbeifahrt an jeder Seite gestattet.","Schwimmendes Gerät bei der Arbeit. Vorbeifahrt nicht gestattet.","Festgefahrenes oder gesunkenes Fahrzeug. Vorbeifahrt an der Steuerbordseite gestattet. Sog und Wellenschlag vermeiden.","Festgefahrenes oder gesunkenes Fahrzeug. Vorbeifahrt nicht gestattet."],"erklaerung":"Grün-weiß-grüne Tafeln auf beiden Seiten bedeuten: Man darf an jeder Seite des schwimmenden Geräts vorbeifahren.","stichworte":["Grün-weiß-grüne Tafeln beidseitig","beide Seiten frei"]},{"nr":155,"teil":"binnen","thema":"lichter","frage":"Was bedeutet diese Tag- und Nachtbezeichnung?","inline":[],"bilder":["bilder/Bild-058-Tag.gif","bilder/Bild-058-Nacht.gif"],"antworten":["Schutzbedürftiges Fahrzeug, Vorbeifahrt in möglichst weitem Abstand, Geschwindigkeit vermindern, Sog und Wellenschlag vermeiden.","Ein festgefahrenes oder gesunkenes Fahrzeug. Vorbeifahrt nicht gestattet.","Ein festgefahrenes oder gesunkenes Fahrzeug. Vorbeifahrt an jeder Seite mit unverminderter Geschwindigkeit gestattet.","Schwimmende Anlage / Schwimmkörper. Vorbeifahrt in möglichst weitem Abstand, Geschwindigkeit vermindern, Sog und Wellenschlag vermeiden."],"erklaerung":"Am Tag zeigt eine rot-weiße Flagge, nachts Rot über Weiß als Rundumlichter, ein schutzbedürftiges Fahrzeug, z. B. mit Tauchern im Wasser. Man fährt mit möglichst großem Abstand und langsam vorbei und vermeidet Sog und Wellenschlag.","stichworte":["Schutzbedürftiges Fahrzeug","großer Abstand","langsam"]},{"nr":156,"teil":"binnen","thema":"zeichen","frage":"Was bedeutet dieses Tafelzeichen?","inline":[],"bilder":["bilder/Verbotszeichen-A01a.gif"],"antworten":["Gesperrte Wasserfläche, jedoch für Kleinfahrzeuge ohne Antriebsmaschine befahrbar.","Gesperrte Wasserfläche, jedoch für Kleinfahrzeuge ohne laufende Antriebsmaschine befahrbar.","Gesperrte Wasserfläche, für Kleinfahrzeuge nicht befahrbar.","Gesperrte Wasserfläche, Verbot der Durchfahrt und Sperrung der Schifffahrt."],"erklaerung":"Die runde rote Tafel mit weißem Balken sperrt die Wasserfläche. Kleinfahrzeuge ohne Antriebsmaschine (Ruder-, Paddel-, Segelboote ohne Motor) dürfen sie trotzdem befahren. Ein Boot, das einen Motor an Bord hat, ist ausgeschlossen, auch wenn der Motor aus ist.","stichworte":["Runde Tafel","gesperrt","frei für Boote ohne Motor"]},{"nr":157,"teil":"binnen","thema":"zeichen","frage":"Was bedeutet dieses Tafelzeichen?","inline":[],"bilder":["bilder/Verbotszeichen-A12.gif"],"antworten":["Fahrverbot für Fahrzeuge mit Maschinenantrieb.","Fahrverbot für Kleinfahrzeuge mit Maschinenantrieb.","Fahrverbot für Fahrzeuge ohne Antriebsmaschine.","Fahrverbot für Kleinfahrzeuge ohne laufende Antriebsmaschine."],"erklaerung":"Ein durchgestrichener Propeller bedeutet Fahrverbot für alle Fahrzeuge mit Maschinenantrieb, groß und klein.","stichworte":["Durchgestrichener Propeller","Fahrverbot für Motorfahrzeuge"]},{"nr":158,"teil":"binnen","thema":"zeichen","frage":"Wie ist eine geschützte Badezone gekennzeichnet?","inline":[],"bilder":[],"antworten":["Durch gelbe Tonnen.","Durch grüne Tonnen.","Durch rote Tonnen.","Durch rot-grün gestreifte Tonnen."],"erklaerung":"Geschützte Badezonen werden mit gelben Tonnen abgegrenzt. Dort ist das Befahren verboten.","stichworte":["Badezone","gelbe Tonnen"]},{"nr":159,"teil":"binnen","thema":"schall","frage":"Was bedeutet ein langer Ton?","inline":[],"bilder":[],"antworten":["Achtung!","Maschine geht rückwärts.","Fahrzeug ist manövrierunfähig.","Überholen nicht möglich."],"erklaerung":"Ein langer Ton bedeutet „Achtung!“. Merkhilfe für die Signale: 1 lang = Achtung, 1 kurz = Steuerbord, 2 kurz = Backbord, 3 kurz = rückwärts, 4 kurz = manövrierunfähig, 5 kurz = Überholen nicht möglich.","stichworte":["1 lang","Achtung"]},{"nr":160,"teil":"binnen","thema":"schall","frage":"Was bedeuten vier kurze Töne?","inline":[],"bilder":[],"antworten":["Fahrzeug ist manövrierunfähig.","Maschine geht rückwärts.","Achtung!","Überholen nicht möglich."],"erklaerung":"Vier kurze Töne bedeuten: Ich bin manövrierunfähig. Merkhilfe: 3 kurz = rückwärts, 4 kurz = manövrierunfähig, 5 kurz = Überholen nicht möglich.","stichworte":["4 kurz","manövrierunfähig"]},{"nr":161,"teil":"binnen","thema":"schall","frage":"Was bedeuten fünf kurze Töne?","inline":[],"bilder":[],"antworten":["Überholen nicht möglich.","Maschine geht rückwärts.","Fahrzeug ist manövrierunfähig.","Achtung!"],"erklaerung":"Fünf kurze Töne gibt der Vorausfahrende, wenn Überholen nicht möglich ist.","stichworte":["5 kurz","Überholen nicht möglich"]},{"nr":162,"teil":"binnen","thema":"schall","frage":"Was bedeutet dieses Schallsignal?","inline":[],"bilder":["bilder/Schallsignal-Frage-162.gif"],"antworten":["Wenden über Steuerbord.","Kursänderung über Steuerbord.","Kursänderung nach Backbord.","Wenden über Backbord."],"erklaerung":"Ein langer und ein kurzer Ton bedeuten: Ich wende über Steuerbord. Merkhilfe: Die langen Töne nennen das Manöver (1 = Wenden, 2 = Überholen, 3 = Hafen), die kurzen die Seite (1 = Steuerbord, 2 = Backbord).","stichworte":["Lang–kurz","Wenden über Steuerbord"]},{"nr":163,"teil":"binnen","thema":"schall","frage":"Was bedeutet dieses Schallsignal?","inline":[],"bilder":["bilder/Schallsignal-Frage-163.gif"],"antworten":["Wenden über Backbord.","Wenden über Steuerbord.","Kursänderung nach Backbord.","Kursänderung nach Steuerbord."],"erklaerung":"Ein langer und zwei kurze Töne bedeuten: Ich wende über Backbord. Ein langer Ton = Wenden, zwei kurze = Backbord.","stichworte":["Lang–kurz–kurz","Wenden über Backbord"]},{"nr":164,"teil":"binnen","thema":"schall","frage":"Was bedeutet dieses Schallsignal?","inline":[],"bilder":["bilder/Schallsignal-Frage-164.gif"],"antworten":["Überholen an der Steuerbordseite des Vorausfahrenden.","Überholen an der Backbordseite des Vorausfahrenden.","Hafen oder Nebenwasserstraße; Ein- oder Ausfahrt mit Kursänderung nach Steuerbord.","Hafen oder Nebenwasserstraße; Ein- oder Ausfahrt mit Kursänderung nach Backbord."],"erklaerung":"Zwei lange und ein kurzer Ton bedeuten: Ich will an deiner Steuerbordseite überholen. Zwei lange = Überholen, ein kurzer = Steuerbord des Vorausfahrenden.","stichworte":["Lang–lang–kurz","Überholen an Steuerbord"]},{"nr":165,"teil":"binnen","thema":"schall","frage":"Was bedeutet dieses Schallsignal?","inline":[],"bilder":["bilder/Schallsignal-Frage-165.gif"],"antworten":["Überholen an der Backbordseite des Vorausfahrenden.","Überholen an der Steuerbordseite des Vorausfahrenden.","Hafen oder Nebenwasserstraße; Ein- oder Ausfahrt mit Kursänderung nach Steuerbord.","Hafen oder Nebenwasserstraße; Ein- oder Ausfahrt mit Kursänderung nach Backbord."],"erklaerung":"Zwei lange und zwei kurze Töne bedeuten: Ich will an deiner Backbordseite überholen. Zwei lange = Überholen, zwei kurze = Backbord.","stichworte":["Lang–lang–kurz–kurz","Überholen an Backbord"]},{"nr":166,"teil":"binnen","thema":"schall","frage":"Was bedeutet dieses Schallsignal?","inline":[],"bilder":["bilder/Schallsignal-Frage-166.gif"],"antworten":["Hafen oder Nebenwasserstraße; Ein- oder Ausfahrt mit Kursänderung nach Steuerbord.","Überholen an der Backbordseite des Vorausfahrenden.","Überholen an der Steuerbordseite des Vorausfahrenden.","Hafen oder Nebenwasserstraße; Ein- oder Ausfahrt mit Kursänderung nach Backbord."],"erklaerung":"Drei lange und ein kurzer Ton bedeuten: Ich fahre mit Kursänderung nach Steuerbord in einen Hafen oder eine Nebenwasserstraße ein oder aus ihr heraus. Drei lange = Hafen, ein kurzer = Steuerbord.","stichworte":["3 lang + 1 kurz","Hafen","nach Steuerbord"]},{"nr":167,"teil":"binnen","thema":"schall","frage":"Was bedeutet dieses Schallsignal?","inline":[],"bilder":["bilder/Schallsignal-Frage-167.gif"],"antworten":["Hafen oder Nebenwasserstraße; Ein- oder Ausfahrt mit Kursänderung nach Backbord.","Überholen an der Backbordseite des Vorausfahrenden.","Hafen oder Nebenwasserstraße; Ein- oder Ausfahrt mit Kursänderung nach Steuerbord.","Überholen an der Steuerbordseite des Vorausfahrenden."],"erklaerung":"Drei lange und zwei kurze Töne bedeuten: Ein- oder Ausfahrt aus dem Hafen bzw. der Nebenwasserstraße mit Kursänderung nach Backbord.","stichworte":["3 lang + 2 kurz","Hafen","nach Backbord"]},{"nr":168,"teil":"binnen","thema":"schall","frage":"Was ist eine Folge sehr kurzer Töne?","inline":[],"bilder":[],"antworten":["Eine Folge von mindestens 6 Tönen, von je etwa einer viertel Sekunde Dauer und mit je einer viertel Sekunde Pause.","Eine Folge von mindestens 4 Tönen von je etwa einer viertel Sekunde Dauer und mit je einer viertel Sekunde Pause.","Eine Folge von mindestens 2 Tönen von je etwa einer viertel Sekunde Dauer und mit je einer viertel Sekunde Pause.","Eine Folge von mindestens 8 Tönen von je etwa einer viertel Sekunde Dauer und mit je einer viertel Sekunde Pause."],"erklaerung":"Eine Folge sehr kurzer Töne sind mindestens 6 Töne von je etwa ¼ Sekunde mit ¼ Sekunde Pause, also ein schnelles „Trillern“.","stichworte":["Sehr kurze Töne","mindestens 6","je ¼ Sekunde"]},{"nr":169,"teil":"binnen","thema":"schall","frage":"Was bedeutet eine Folge sehr kurzer Töne?","inline":[],"bilder":[],"antworten":["Gefahr eines Zusammenstoßes.","Achtung!","Fahrzeug ist manövrierunfähig.","Überholen nicht möglich."],"erklaerung":"Die Folge sehr kurzer Töne warnt: Es droht ein Zusammenstoß.","stichworte":["Sehr kurze Töne","Gefahr eines Zusammenstoßes"]},{"nr":170,"teil":"binnen","thema":"schall","frage":"Welche Schallsignale bzw. Zeichen sind zu geben, wenn das Boot manövrierunfähig geworden ist?","inline":[],"bilder":[],"antworten":["Vier kurze Töne. Bei Tag eine rote Flagge, bei Nacht ein rotes Licht im unteren Halbkreis schwenken.","Fünf kurze Töne. Bei Tag eine rote Flagge, bei Nacht ein rotes Licht im oberen Halbkreis schwenken.","Ein langer, vier kurze Töne. Bei Tag eine rote Flagge, bei Nacht ein rotes Licht setzen.","Eine Gruppe von kurzen und langen Tönen im Intervall geben. Bei Nacht ein rotes Blinklicht einschalten."],"erklaerung":"Wer manövrierunfähig ist, gibt vier kurze Töne. Optisch schwenkt man am Tag eine rote Flagge und nachts ein rotes Licht (im unteren Halbkreis).","stichworte":["Manövrierunfähig","4 kurz","rote Flagge","rotes Licht schwenken"]},{"nr":171,"teil":"binnen","thema":"fahrregeln","frage":"Ein Fahrzeug zeigt an der Steuerbordseite seines Ruderhauses eine blaue Tafel mit weißem Funkellicht. Welche Bedeutung hat dieses Zeichen?","inline":[],"bilder":[],"antworten":["Fahrzeuge begegnen sich an Steuerbord. Dieses Zeichen gilt nicht für Kleinfahrzeuge, verpflichtet aber zu erhöhter Aufmerksamkeit.","Fahrzeuge begegnen sich an Steuerbord. Dieses Zeichen gilt nur für Kleinfahrzeuge.","Fahrzeuge begegnen sich an Steuerbord. Dieses Zeichen braucht gar nicht beachtet zu werden.","Fahrzeuge begegnen sich an Steuerbord. Dieses Zeichen gilt auch für alle Kleinfahrzeuge."],"erklaerung":"Eine blaue Tafel mit weißem Funkellicht zeigt eine Begegnung Steuerbord an Steuerbord, also abweichend von der Regel. Für Kleinfahrzeuge gilt dieses Zeichen nicht, sie müssen aber besonders aufmerksam sein.","stichworte":["Blaue Tafel + weißes Funkellicht","Steuerbord an Steuerbord","nicht für Kleinfahrzeuge"]},{"nr":172,"teil":"binnen","thema":"schleuse","frage":"Ein Sportfahrzeug fährt hinter einem Fahrzeug, das nicht Kleinfahrzeug ist, in den Schleusenvorhafen ein. Aus der Schleusenkammer kommt ein Fahrzeug, das an Steuerbord eine blaue Tafel mit einem weißen Funkellicht zeigt. Was bedeutet dieses Zeichen?","inline":[],"bilder":[],"antworten":["Das aus- und die einfahrenden Fahrzeuge passieren sich an der Steuerbordseite, das Kleinfahrzeug ist nur zu erhöhter Aufmerksamkeit verpflichtet.","Das aus- und die einfahrenden Fahrzeuge passieren sich an der Backbordseite, das Kleinfahrzeug ist nur zu erhöhter Aufmerksamkeit verpflichtet.","Das aus- und die einfahrenden Fahrzeuge passieren sich an der Steuerbordseite, das Kleinfahrzeug ist wartepflichtig.","Das aus- und die einfahrenden Fahrzeuge passieren sich an der Backbordseite, das Kleinfahrzeug hat Vorrang."],"erklaerung":"Die blaue Tafel mit weißem Funkellicht bedeutet, dass das ausfahrende und die einfahrenden Fahrzeuge sich an Steuerbord passieren. Das Kleinfahrzeug ist davon nicht direkt betroffen, muss aber besonders aufpassen.","stichworte":["Blaue Tafel","Steuerbordbegegnung","Kleinfahrzeug aufmerksam"]},{"nr":173,"teil":"binnen","thema":"recht","frage":"Wo kann man von bestehenden Höchstgeschwindigkeiten auf den Binnenschifffahrtsstraßen Kenntnis erhalten?","inline":[],"bilder":[],"antworten":["In der Binnenschifffahrtsstraßen-Ordnung, bei der Wasserstraßen- und Schifffahrtsverwaltung und der Wasserschutzpolizei.","In der Binnenschiffsuntersuchungsordnung, bei der Wasserstraßen- und Schifffahrtsverwaltung und der Wasserschutzpolizei.","In der Sportbootführerscheinverordnung, bei der Wasserstraßen- und Schifffahrtsverwaltung und der Wasserschutzpolizei.","In der Binnenschifferpatentverordnung, bei der Wasserstraßen- und Schifffahrtsverwaltung und der Wasserschutzpolizei."],"erklaerung":"Höchstgeschwindigkeiten stehen in der Binnenschifffahrtsstraßen-Ordnung. Auskunft geben außerdem die WSV und die Wasserschutzpolizei. Die anderen Verordnungen regeln Führerscheine, Patente und Technik.","stichworte":["Höchstgeschwindigkeit","BinSchStrO","WSV","WSP"]},{"nr":174,"teil":"binnen","thema":"fahrregeln","frage":"Wie ist ein Überholmanöver durchzuführen?","inline":[],"bilder":[],"antworten":["Zügig überholen. Beteiligte Fahrzeuge nicht behindern. Verkehrslage und eventuelle Schallzeichen beachten. Ausreichend Abstand halten.","Zügig überholen. Gegebenenfalls das Fahrzeug stark beschleunigen, um schnell passieren zu können.","Zügig überholen; überholen nur auf der Steuerbordseite erlaubt, ausreichend Abstand halten.","Zügig überholen. Dicht am Ufer entlang fahren, eventuelle Schallzeichen müssen von Kleinfahrzeugen beachtet werden."],"erklaerung":"Man überholt zügig, ohne andere zu behindern, mit ausreichendem Abstand und achtet dabei auf die Verkehrslage und mögliche Schallzeichen. Überholen ist auf beiden Seiten möglich, nicht nur an Steuerbord.","stichworte":["Zügig","nicht behindern","Abstand","Schallzeichen beachten"]},{"nr":175,"teil":"binnen","thema":"fahrregeln","frage":"Wann besteht die Gefahr eines Zusammenstoßes?","inline":[],"bilder":[],"antworten":["Wenn sich zwei Fahrzeuge bei gleichbleibender Peilung einander nähern.","Wenn sich zwei Fahrzeuge einander nähern und sich der Kurs der Fahrzeuge nicht ändert.","Wenn sich zwei Fahrzeuge einander nähern und sich der Kurs eines Fahrzeuges ändert.","Wenn sich zwei Fahrzeuge einander nähern und beide Fahrzeuge ihren Kurs nach steuerbord ändern."],"erklaerung":"Kollisionsgefahr besteht, wenn die Peilung zum anderen Fahrzeug gleich bleibt, während man sich nähert. Das andere Boot „steht“ dann scheinbar an derselben Stelle im Blickfeld. Merkhilfe: stehende Peilung = Kollisionskurs.","stichworte":["Stehende Peilung","Kollisionskurs","Annäherung"]},{"nr":176,"teil":"binnen","thema":"fahrregeln","frage":"Wie müssen Ausweichmanöver durchgeführt werden?","inline":[],"bilder":[],"antworten":["Rechtzeitig, klar erkennbar und entschlossen.","Rechtzeitig, klar erkennbar und nach Steuerbord.","Rechtzeitig, klar erkennbar und nach Backbord.","Rechtzeitig, klar erkennbar und vorsichtig."],"erklaerung":"Ausweichen muss rechtzeitig, deutlich und entschlossen sein, damit der andere sofort erkennt, was man vorhat. Zögerliche kleine Kursänderungen sind gefährlich.","stichworte":["Ausweichen","rechtzeitig","klar erkennbar","entschlossen"]},{"nr":177,"teil":"binnen","thema":"fahrregeln","frage":"Ein Kleinfahrzeug und ein Fahrzeug über 20 m Länge nähern sich auf kreuzenden Kursen. Es besteht die Gefahr eines Zusammenstoßes. Wer ist ausweichpflichtig?","inline":[],"bilder":[],"antworten":["Ausweichpflichtig ist das Kleinfahrzeug.","Ausweichpflichtig ist das Fahrzeug über 20 m Länge.","Ausweichpflichtig ist das Fahrzeug, welches das andere an seiner Steuerbordseite sieht.","Ausweichpflichtig ist das Fahrzeug, welches das andere an seiner Backbordseite sieht."],"erklaerung":"Kleinfahrzeuge müssen allen Fahrzeugen ausweichen, die keine Kleinfahrzeuge sind (also ab 20 m). Die Steuerbordregel gilt hier nicht.","stichworte":["Kleinfahrzeug weicht aus","gegenüber Großfahrzeug"]},{"nr":178,"teil":"binnen","thema":"lichter","frage":"Welche Fahrzeuge in Fahrt führen nachts nur ein weißes Rundumlicht?","inline":[],"bilder":[],"antworten":["Geschleppte oder längsseits gekuppelte Kleinfahrzeuge.","Kleinfahrzeuge mit Maschinenantrieb unter 20 m Länge.","Kleinfahrzeuge mit Maschinenantrieb und geschleppte Fahrzeuge.","Fahrzeuge die geschoben werden."],"erklaerung":"Nur ein weißes Rundumlicht führen geschleppte Kleinfahrzeuge und Kleinfahrzeuge, die längsseits gekuppelt sind.","stichworte":["Weißes Rundumlicht","geschleppte Kleinfahrzeuge","längsseits gekuppelt"]},{"nr":179,"teil":"binnen","thema":"fahrregeln","frage":"Wie muss sich ein kreuzendes Kleinfahrzeug unter Segel am Wind in der Nähe eines Ufers gegenüber einem anderen Kleinfahrzeug verhalten?","inline":[],"bilder":[],"antworten":["Es darf ein anderes Kleinfahrzeug, das sein steuerbordseitiges Ufer anhält, nicht zum Ausweichen zwingen.","Es darf ein anderes Kleinfahrzeug, das sein steuerbordseitiges Ufer verlässt, nicht zum Ausweichen zwingen.","Es darf ein anderes Kleinfahrzeug, das sein backbordseitiges Ufer verlässt, zum Ausweichen zwingen.","Es darf ein anderes Kleinfahrzeug, das sein steuerbordseitiges Ufer anhält, zum Ausweichen zwingen."],"erklaerung":"Ein Segler, der am Wind in Ufernähe kreuzt, darf ein Kleinfahrzeug, das sein steuerbordseitiges Ufer anhält (also rechts am Ufer entlangfährt), nicht zum Ausweichen zwingen. Das Boot am Ufer hat keinen Platz zum Ausweichen.","stichworte":["Kreuzen am Ufer","steuerbordseitiges Ufer anhalten","nicht zum Ausweichen zwingen"]},{"nr":180,"teil":"binnen","thema":"fahrregeln","frage":"Wer ist ausweichpflichtig bzw. wer ist nicht ausweichpflichtig?","inline":[],"bilder":["bilder/Bild-Frage-180.gif"],"antworten":["Das Fahrzeug unter Segel ist ausweichpflichtig.","Das Fahrzeug unter Segel ist nicht ausweichpflichtig.","Das Fahrzeug unter Maschinenantrieb ist ausweichpflichtig.","Beide Fahrzeuge sind ausweichpflichtig."],"erklaerung":"Das Motorboot fährt dicht an seinem steuerbordseitigen Ufer entlang. Der kreuzende Segler darf es dort nicht zum Ausweichen zwingen (vgl. Frage 179). Hier muss also ausnahmsweise der Segler ausweichen.","stichworte":["Motorboot hält Steuerbordufer an","Segler weicht aus","Ausnahme"]},{"nr":181,"teil":"binnen","thema":"fahrregeln","frage":"Was hat der Schiffsführer eines Kleinfahrzeugs beim Begegnen mit Fahrzeugen, die nicht Kleinfahrzeuge sind, zu beachten?","inline":[],"bilder":[],"antworten":["Kleinfahrzeuge sind gegenüber Fahrzeugen, die nicht Kleinfahrzeuge sind, ausweichpflichtig. Sie müssen für deren Kurs und zum Manövrieren notwendigen Raum lassen.","Kleinfahrzeuge sind gegenüber anderen Fahrzeugen, die nicht Kleinfahrzeuge sind, nicht ausweichpflichtig.","Kleinfahrzeuge sind gegenüber Fahrzeugen, die nicht Kleinfahrzeuge sind, bei der Begegnung gleichgestellt.","Kleinfahrzeuge sind gegenüber Fahrzeugen, die nicht Kleinfahrzeuge sind, ausweichpflichtig. Sie brauchen aber keinen besonderen Raum zum Manövrieren frei zu geben."],"erklaerung":"Kleinfahrzeuge müssen Fahrzeugen ausweichen, die keine Kleinfahrzeuge sind, und ihnen den Raum lassen, den sie für Kurs und Manöver brauchen. Große Schiffe sind schwerfällig und haben einen langen Bremsweg.","stichworte":["Kleinfahrzeug weicht aus","Raum zum Manövrieren lassen"]},{"nr":182,"teil":"binnen","thema":"fahrregeln","frage":"Von Backbord kommend kreuzt ein Fahrzeug unter Segel mit einem schwarzen Kegel, Spitze nach unten, den Kurs eines Fahrzeuges mit Maschinenantrieb. Wer ist ausweichpflichtig?","inline":[],"bilder":[],"antworten":["Das Fahrzeug unter Segel mit einem schwarzen Kegel ist ausweichpflichtig.","Das Fahrzeug ohne Segel ist ausweichpflichtig.","Das Fahrzeug unter Segel mit einem schwarzen Kegel ist nicht ausweichpflichtig.","Beide Fahrzeuge sind ausweichpflichtig."],"erklaerung":"Der schwarze Kegel mit Spitze nach unten zeigt: Der Segler fährt zusätzlich mit Motor und gilt als Maschinenfahrzeug. Er kommt von Backbord und muss deshalb nach der Steuerbordregel ausweichen.","stichworte":["Schwarzer Kegel = Motor","von Backbord kommend","weicht aus"]},{"nr":183,"teil":"binnen","thema":"fahrregeln","frage":"Zwei Kleinfahrzeuge unter Segel A und B liegen auf Kollisionskurs; A führt einen schwarzen Kegel. Wer ist ausweichpflichtig?","inline":[],"bilder":["bilder/Bild-Frage-183.gif"],"antworten":["Fahrzeug A ist ausweichpflichtig.","Fahrzeug B ist ausweichpflichtig.","Ausweichpflichtig ist das Fahrzeug, welches das Andere an seiner Backbordseite sieht.","Ausweichpflichtig ist das Fahrzeug, welches den Wind von Backbord hat."],"erklaerung":"A zeigt den schwarzen Kegel, segelt also mit Motor und gilt als Kleinfahrzeug mit Maschinenantrieb. Damit muss A dem echten Segler B ausweichen.","stichworte":["Kegel = Motorsegler","A weicht aus","Segler hat Vorrang"]},{"nr":184,"teil":"binnen","thema":"fahrregeln","frage":"Ein Fahrzeug unter Segel kreuzt eine Binnenschifffahrtsstraße. In der Fahrwassermitte kommt ihm ein Kleinfahrzeug mit Maschinenantrieb zu Berg entgegen. Wer ist ausweichpflichtig?","inline":[],"bilder":[],"antworten":["Fahrzeug mit Maschinenantrieb.","Fahrzeug in der Talfahrt.","Fahrzeug unter Segel.","Beide sind ausweichpflichtig."],"erklaerung":"Kleinfahrzeuge mit Maschinenantrieb müssen Kleinfahrzeugen unter Segel ausweichen. Ob der Segler kreuzt oder der andere zu Berg fährt, ändert daran nichts.","stichworte":["Motor weicht Segel","Bergfahrt egal"]},{"nr":185,"teil":"binnen","thema":"fahrregeln","frage":"Zwei Kleinfahrzeuge A und B unter Segel liegen auf Kollisionskurs (Skizze). Wer ist ausweichpflichtig?","inline":[],"bilder":["bilder/Bild-Frage-185.gif"],"antworten":["A ist ausweichpflichtig. Segelfahrzeuge mit Wind von Backbord müssen Segelfahrzeugen mit Wind von Steuerbord ausweichen.","B ist ausweichpflichtig. Segelfahrzeuge mit Wind von Backbord müssen Segelfahrzeugen mit Wind von Steuerbord ausweichen.","A ist ausweichpflichtig. Segelfahrzeuge mit Wind von Steuerbord müssen Segelfahrzeugen mit Wind von Backbord ausweichen.","B ist ausweichpflichtig. Segelfahrzeuge mit Wind von Steuerbord müssen Segelfahrzeugen mit Wind von Backbord ausweichen."],"erklaerung":"Die Boote haben den Wind von verschiedenen Seiten. A hat ihn von Backbord und muss B ausweichen, das den Wind von Steuerbord hat.","stichworte":["Wind von Backbord weicht aus","A weicht aus"]},{"nr":186,"teil":"binnen","thema":"fahrregeln","frage":"Zwei Kleinfahrzeuge unter Segel liegen auf Kollisionskurs. Wer ist ausweichpflichtig?","inline":[],"bilder":["bilder/Bild-Frage-186.gif"],"antworten":["B ist ausweichpflichtig. Das luvseitige Boot muss dem leeseitigen ausweichen.","A ist ausweichpflichtig. Das luvseitige Boot muss dem leeseitigen ausweichen.","A ist ausweichpflichtig. Das leeseitige Boot muss dem luvseitigen ausweichen.","B ist ausweichpflichtig. Das leeseitige Boot muss dem luvseitigen ausweichen."],"erklaerung":"Beide Boote haben den Wind von derselben Seite. Dann muss das luvseitige Boot (näher am Wind) dem leeseitigen ausweichen. Das luvseitige ist hier B.","stichworte":["Gleiche Seite","Luv weicht Lee","B weicht aus"]},{"nr":187,"teil":"binnen","thema":"fahrregeln","frage":"Ein Kleinfahrzeug A segelt nachts auf Vorwindkurs stromab, Großsegel an Steuerbord. Backbord querab kommt ein grünes Seitenlicht eines Bootes B immer näher, das kein Topplicht führt. Wer ist ausweichpflichtig?","inline":[],"bilder":[],"antworten":["Das Kleinfahrzeug A ist ausweichpflichtig. Ein Boot mit Wind von Backbord muss ausweichen, wenn es nicht klar ausmachen kann, ob das luvseitige Boot den Wind von Steuerbord hat.","Das Kleinfahrzeug A ist ausweichpflichtig. Ein Boot mit Wind von Steuerbord muss ausweichen, wenn es nicht klar ausmachen kann, ob das luvseitige Boot den Wind von Backbord hat.","Boot B ist ausweichpflichtig, weil es sich bei Fahrzeug A um ein Kleinfahrzeug unter Segel handelt, das den Wind von Backbord hat.","Boot B ist ausweichpflichtig, weil es sich um ein Kleinfahrzeug handelt und Kleinfahrzeuge anderen Kleinfahrzeugen unter Segel ausweichen müssen."],"erklaerung":"A hat das Großsegel an Steuerbord, also den Wind von Backbord. Das andere Boot führt kein Topplicht, ist also ein Segler. Ob es den Wind von Steuerbord hat, kann A nachts nicht sicher erkennen. In diesem Fall muss A ausweichen.","stichworte":["Wind von Backbord","Wind des anderen unklar","A weicht aus"]},{"nr":188,"teil":"binnen","thema":"fahrregeln","frage":"Der seitliche Abstand zwischen den Booten A, B und C verringert sich ständig. Welches Boot kann seinen Kurs beibehalten?","inline":[],"bilder":["bilder/Bild-Frage-188.gif"],"antworten":["Boot A, weil leeseitig.","Boot A, weil luvseitig.","Boot B, weil leeseitig.","Boot C, weil leeseitig."],"erklaerung":"Die drei Boote haben den Wind von derselben Seite. Dann hat jeweils das leeseitige Boot Vorrang. A liegt am weitesten in Lee und kann Kurs halten, B und C müssen ausweichen.","stichworte":["Gleiche Seite","Lee hat Vorrang","A hält Kurs"]},{"nr":189,"teil":"binnen","thema":"fahrregeln","frage":"Wer ist wem gegenüber kurshaltepflichtig?","inline":[],"bilder":["bilder/Bild-Frage-189.gif"],"antworten":["A gegenüber B und C, B gegenüber C.","C gegenüber A und B, B gegenüber A.","B gegenüber C und A, A gegenüber C.","A gegenüber B und C, C gegenüber B."],"erklaerung":"Wer Vorrang hat, ist kurshaltepflichtig. A hat gegenüber B und C Vorrang, B gegenüber C. C muss also beiden ausweichen.","stichworte":["Kurshaltepflicht","Vorrang","A vor B vor C"]},{"nr":190,"teil":"binnen","thema":"fahrregeln","frage":"Was ist vorrangig zu beachten, wenn eine Jolle gekentert ist und sie nicht wieder aufgerichtet werden kann?","inline":[],"bilder":[],"antworten":["Vollständigkeit der Crew überprüfen, gegebenenfalls Hilfe leisten. Am Boot festhalten oder gegebenenfalls aufs Boot legen, Hilfe abwarten.","Sofort vorgeschriebene Notsignale geben, mit allen Mitteln versuchen, das Fahrzeug aus dem Fahrwasser zu bringen.","Auf das gekenterte Boot steigen und sich ruhig verhalten, um Wärmeverlust zu minimieren. Sollte das nicht möglich sein, ans benachbarte Ufer schwimmen und Hilfe holen.","Rettungswesten anlegen und mit geeigneten Mitteln Hilfe herbeiholen. Gegebenenfalls Segel bergen."],"erklaerung":"Bei einer Kenterung geht es zuerst um die Menschen: Ist die Crew vollständig? Braucht jemand Hilfe? Dann bleibt man am Boot und hält sich fest bzw. legt sich darauf, weil das Boot schwimmt und gut zu sehen ist. Wegschwimmen ist gefährlich, da Entfernungen täuschen und Unterkühlung droht.","stichworte":["Crew vollzählig?","beim Boot bleiben","nicht wegschwimmen"]},{"nr":191,"teil":"binnen","thema":"fahrregeln","frage":"Ein Segelboot gerät in das Feld einer Segelregatta, ohne selbst Teilnehmer zu sein. Welche Ausweichregeln sind zu beachten?","inline":[],"bilder":[],"antworten":["Die der Binnenschifffahrtsstraßen-Ordnung.","Die der Wettsegelbestimmungen.","Gegenüber Regattateilnehmern, die der Wettfahrtregeln, gegenüber anderen Fahrzeugen die der Binnenschifffahrtsstraßen-Ordnung.","Fahrzeuge, die an einer Regatta teilnehmen, müssen unbeteiligten Fahrzeugen ausweichen."],"erklaerung":"Wer nicht an der Regatta teilnimmt, für den gelten weiterhin nur die Regeln der Binnenschifffahrtsstraßen-Ordnung. Die Wettfahrtregeln gelten nur zwischen den Regattateilnehmern.","stichworte":["Regatta","Unbeteiligter","BinSchStrO gilt"]},{"nr":192,"teil":"binnen","thema":"lichter","frage":"Ein Kleinfahrzeug unter Segel kreuzt nachts das Fahrwasser. An Backbord tauchen die nachstehenden Lichter eines Fahrzeugs auf, das in spitzem Winkel den Kurs des Kleinfahrzeugs unter Segel kreuzen will. Was bedeuten diese Lichter?","inline":[],"bilder":["bilder/Lichter-Frage-192.gif"],"antworten":["Kleinfahrzeug mit Maschinenantrieb.","Frei fahrende Fähre.","Schubverband von vorne.","Geschlepptes Kleinfahrzeug."],"erklaerung":"Grün plus Weiß ohne Rot: Man sieht die Steuerbordseite eines Fahrzeugs mit Seitenlicht und weißem Licht (Topp- bzw. Rundumlicht). Diese Kombination zeigt ein Kleinfahrzeug mit Maschinenantrieb.","stichworte":["Grün + Weiß","Kleinfahrzeug mit Motor"]},{"nr":193,"teil":"binnen","thema":"lichter","frage":"Ein Kleinfahrzeug unter Segel kreuzt nachts das Fahrwasser. An Backbord tauchen die nachstehenden Lichter eines Fahrzeugs auf, das in spitzem Winkel den Kurs des Kleinfahrzeugs unter Segel kreuzen will. Wer ist ausweichpflichtig?","inline":[],"bilder":["bilder/Lichter-Frage-192.gif"],"antworten":["Kleinfahrzeug mit Maschinenantrieb.","Kleinfahrzeug unter Segel.","Kleinfahrzeug, welches das Andere auf der Backbordseite hat.","Beide sind ausweichpflichtig."],"erklaerung":"Das herankommende Boot ist ein Kleinfahrzeug mit Maschinenantrieb. Motorboote müssen Seglern ausweichen. Von welcher Seite es kommt, spielt dabei keine Rolle.","stichworte":["Motor weicht Segel","Seite egal"]},{"nr":194,"teil":"binnen","thema":"fahrregeln","frage":"Ein Kleinfahrzeug unter Segel und mit Maschinenantrieb kreuzt nachts stromauf. Ein Fahrzeug kommt entgegen, das nur ein weißes Licht führt. Was bedeutet dieses Licht?","inline":[],"bilder":[],"antworten":["Kleinfahrzeug ohne Maschinenantrieb.","Kleinfahrzeug mit Maschinenantrieb.","Kleinfahrzeug unter Segel.","Kleinfahrzeug unter Segel mit Maschinenantrieb."],"erklaerung":"Nur ein weißes Licht (Rundumlicht) führt ein Kleinfahrzeug ohne Maschinenantrieb, z. B. ein Ruderboot. Mit Motor kämen Seitenlichter hinzu. Ein Segler ohne Motor kann ebenfalls nur ein weißes Licht führen, deshalb lautet die allgemeine Antwort „ohne Maschinenantrieb“.","stichworte":["Nur weißes Licht","ohne Maschinenantrieb"]},{"nr":195,"teil":"binnen","thema":"fahrregeln","frage":"Ein Kleinfahrzeug unter Segel kreuzt nachts im Fahrwasser. Von achtern kommt ein Fahrzeug, das eine Zweifarbenlaterne und ein Topplicht führt. Was bedeuten diese Lichter?","inline":[],"bilder":[],"antworten":["Kleinfahrzeug mit Maschinenantrieb.","Kleinfahrzeug ohne Maschinenantrieb.","Kleinfahrzeug unter Segel.","Kleinfahrzeug unter Segel mit Maschinenantrieb."],"erklaerung":"Ein Topplicht ist das Kennzeichen des Maschinenantriebs, die Zweifarbenlaterne enthält die Seitenlichter. Zusammen zeigen sie ein Kleinfahrzeug mit Maschinenantrieb.","stichworte":["Topplicht + Zweifarbenlaterne","Kleinfahrzeug mit Motor"]},{"nr":196,"teil":"binnen","thema":"lichter","frage":"Was bedeuten nachts auf einer Binnenschifffahrtsstraße die nachstehenden Lichter?","inline":[],"bilder":["bilder/Lichter-Frage-196.gif"],"antworten":["Sog und Wellenschlag vermeiden.","Keine Durchfahrt für Kleinfahrzeuge.","Sperrung der Schifffahrt.","Durchfahrt für Kleinfahrzeuge."],"erklaerung":"Rot über Weiß bedeutet nachts: Sog und Wellenschlag vermeiden. So kennzeichnen sich z. B. schutzbedürftige Fahrzeuge.","stichworte":["Rot über Weiß","Sog und Wellenschlag vermeiden"]},{"nr":197,"teil":"binnen","thema":"fahrregeln","frage":"Wo ist die Geschwindigkeit zu vermindern, um Sog und Wellenschlag zu vermeiden?","inline":[],"bilder":[],"antworten":["Vor Hafeneinmündungen, an Lade-, Lösch- und Liegeplätzen, in der Nähe nicht frei fahrender Fähren, auf gekennzeichneten Strecken, in der Nähe schwimmender Geräte bei der Arbeit.","Vor Einmündungen, an Lade-, Lösch- und Liegeplätzen, in der Nähe nicht frei fahrender Fähren, auf gekennzeichneten Strecken, in der Nähe schwimmender Geräte bei der Arbeit.","Vor Hafeneinmündungen, an Lade-, Lösch- und Liegeplätzen, in der Nähe frei fahrender Fähren, auf gekennzeichneten Strecken, in der Nähe schwimmender Geräte bei der Arbeit.","Vor Hafeneinmündungen, an Lade-, Lösch- und Liegeplätzen, in der Nähe nicht frei fahrender Fähren, auf gekennzeichneten Strecken, in der Nähe schwimmender Schifffahrtszeichen."],"erklaerung":"Langsam fährt man überall dort, wo Sog und Wellenschlag schaden können: vor Hafeneinfahrten, an Lade-, Lösch- und Liegeplätzen, bei nicht frei fahrenden Fähren (Seil!), an gekennzeichneten Strecken und bei schwimmenden Geräten bei der Arbeit.","stichworte":["Hafeneinfahrt","Liegeplätze","Seilfähren","schwimmende Geräte"]},{"nr":198,"teil":"binnen","thema":"zeichen","frage":"Was bedeutet dieses Tafelzeichen?","inline":[],"bilder":["bilder/Tafelzeichen-Frage-198.gif"],"antworten":["Vorgeschriebene Fahrtrichtung.","Fahrtrichtung nach links verboten.","Vorgeschriebene Fahrtrichtung nur für Kleinfahrzeuge.","Empfohlene Fahrtrichtung."],"erklaerung":"Ein schwarzer Pfeil in rot umrandeter Tafel ist ein Gebot: Diese Fahrtrichtung ist vorgeschrieben, und zwar für alle Fahrzeuge.","stichworte":["Pfeil","Gebot","vorgeschriebene Fahrtrichtung"]},{"nr":199,"teil":"binnen","thema":"zeichen","frage":"Welche Bedeutung hat das nachstehende Tafelzeichen, wenn das rote Licht leuchtet?","inline":[],"bilder":["bilder/Verbotszeichen-A01-Pfeil.gif"],"antworten":["Verbot der Einfahrt in einen Hafen oder eine Nebenwasserstraße.","Verbot des Überholens auf dem Streckenabschnitt.","Achtung Doppelschleuse, linke Kammer gesperrt.","Achtung Ausfahrt aus Hafen oder Nebenfahrwasser."],"erklaerung":"Leuchtet an dieser Tafel das rote Licht, ist die Einfahrt in den Hafen bzw. die Nebenwasserstraße verboten, in die der Winkel zeigt.","stichworte":["Rotes Licht","Einfahrt in Hafen verboten"]},{"nr":200,"teil":"binnen","thema":"zeichen","frage":"Was bedeutet dieses Tafelzeichen?","inline":[],"bilder":["bilder/Tafelzeichen-Frage-200.gif"],"antworten":["10 km/h Höchstgeschwindigkeit gegenüber dem Ufer.","10 km/h Höchstgeschwindigkeit gegenüber der Strömung.","10 km/h Höchstgeschwindigkeit für Kleinfahrzeuge.","10 km/h für größere Fahrzeuge."],"erklaerung":"Eine Zahl in rot umrandeter Tafel ist eine Höchstgeschwindigkeit in km/h. Sie gilt gegenüber dem Ufer, also über Grund, nicht durchs Wasser.","stichworte":["Zahl = km/h","Höchstgeschwindigkeit","gegenüber dem Ufer"]},{"nr":201,"teil":"binnen","thema":"zeichen","frage":"Was bedeutet dieses Tafelzeichen?","inline":[],"bilder":["bilder/Gebotszeichen-B08.gif"],"antworten":["Gebot: Besondere Vorsicht walten lassen.","Gebot: Geradeaus zu fahren.","Gebot: Achtungssignal geben.","Gebot: Vor dem Schild anhalten."],"erklaerung":"Ein senkrechter schwarzer Balken in rot umrandeter Tafel gebietet besondere Vorsicht.","stichworte":["Senkrechter Balken","besondere Vorsicht"]},{"nr":202,"teil":"binnen","thema":"zeichen","frage":"Was bedeutet dieses Tafelzeichen?","inline":[],"bilder":["bilder/Verbotszeichen-A08.gif"],"antworten":["Wendeverbot.","Verbotene Fahrtrichtung rechts oder links.","Verbote in beiden angezeigten Richtungen zu fahren.","Wendeverbot in der Mitte des Fahrwassers."],"erklaerung":"Das durchgestrichene Wendesymbol bedeutet Wendeverbot im ganzen Bereich, nicht nur in der Fahrwassermitte.","stichworte":["Durchgestrichener Wendepfeil","Wendeverbot"]},{"nr":203,"teil":"binnen","thema":"zeichen","frage":"Was bedeutet dieses Tafelzeichen?","inline":[],"bilder":["bilder/Hinweiszeichen-E08.gif"],"antworten":["Empfohlener Wendeplatz. Stillliegen für alle Fahrzeuge verboten.","Empfohlener Wendeplatz. Stillliegen von Kleinfahrzeugen erlaubt.","Vorgeschriebener Wendeplatz. Stillliegen für alle Fahrzeuge verboten.","Vorgeschriebener Wendeplatz. Stillliegen von Kleinfahrzeugen erlaubt."],"erklaerung":"Das blaue Wendesymbol zeigt einen empfohlenen Wendeplatz. Damit dort gewendet werden kann, darf niemand stillliegen, auch kein Kleinfahrzeug. Blau = Empfehlung/Hinweis, nicht Pflicht.","stichworte":["Blaues Wendezeichen","Wendeplatz empfohlen","Stillliegen verboten"]},{"nr":204,"teil":"binnen","thema":"zeichen","frage":"Was bedeutet dieses Tafelzeichen?","inline":[],"bilder":["bilder/Hinweiszeichen-E03.gif"],"antworten":["Wehr.","Hubbrücke.","Schleuse.","Sicherheitstor."],"erklaerung":"Diese blaue Hinweistafel kündigt ein Wehr an. Dort darf man nicht durchfahren, Strömungsgefahr!","stichworte":["Hinweistafel","Wehr"]},{"nr":205,"teil":"binnen","thema":"wetter","frage":"Welche Sichtbeeinträchtigungen führen zu unsichtigem Wetter?","inline":[],"bilder":[],"antworten":["Nebel, Schneefall, starker Regen.","Dunkelheit, Nebel, Schneefall, starker Regen.","Nacht, Schneefall, starker Regen.","Dämmerung, Nebel, Schneefall, starker Regen."],"erklaerung":"Unsichtiges Wetter entsteht durch Nebel, Schneefall oder starken Regen. Dunkelheit, Nacht oder Dämmerung allein machen das Wetter nicht unsichtig, dafür gibt es die Lichter.","stichworte":["Unsichtig","Nebel","Schnee","starker Regen","nicht Dunkelheit"]},{"nr":206,"teil":"binnen","thema":"wetter","frage":"Wie muss ein Fahrzeug ausgerüstet sein, um bei unsichtigem Wetter zu fahren?","inline":[],"bilder":[],"antworten":["Mit einer für die Binnenschifffahrt zugelassenen funktionsfähigen Radaranlage und einer Sprechfunkanlage für den Binnenschifffahrtsfunk.","Mit einer für die Binnenschifffahrt zugelassenen funktionsfähigen Radaranlage und einer Sprechfunkanlage ohne ATIS.","Mit einer für die Binnenschifffahrt zugelassenen funktionsfähigen Radaranlage und einer Sprechfunkanlage für den Seefunkdienst.","Mit einer Radaranlage ohne Wendeanzeiger und einer Sprechfunkanlage für den Binnenschifffahrtsfunk."],"erklaerung":"Bei unsichtigem Wetter darf nur fahren, wer eine für die Binnenschifffahrt zugelassene, funktionierende Radaranlage und Sprechfunk für den Binnenschifffahrtsfunk hat. Seefunk reicht nicht.","stichworte":["Radar","Binnenschifffahrtsfunk","unsichtiges Wetter"]},{"nr":207,"teil":"binnen","thema":"wetter","frage":"Was ist zu beachten, wenn während der Fahrt unsichtiges Wetter eintritt?","inline":[],"bilder":[],"antworten":["Auf bestimmten Wasserstraßen ist ohne Radar und Sprechfunk die Fahrt unverzüglich einzustellen.","Auf allen Wasserstraßen ist ohne Radar und Sprechfunk die Fahrt unverzüglich einzustellen.","Auf bestimmten Wasserstraßen ist ohne Radar und AIS-- die Fahrt unverzüglich einzustellen.","Auf allen Wasserstraßen ist ohne Radar und ECDIS die Fahrt unverzüglich einzustellen."],"erklaerung":"Tritt unterwegs unsichtiges Wetter ein, muss man auf bestimmten Wasserstraßen ohne Radar und Sprechfunk die Fahrt sofort einstellen. Die Regel gilt nicht überall, sondern nur auf den festgelegten Strecken.","stichworte":["Unsichtig","ohne Radar und Funk","Fahrt einstellen","bestimmte Wasserstraßen"]},{"nr":208,"teil":"binnen","thema":"sicherheit","frage":"Welchen Vorteil bietet ein Radarreflektor auf einem Sportboot?","inline":[],"bilder":[],"antworten":["Bessere Erkennbarkeit des Sportbootes auf Radarbildschirmen.","Bessere Erkennbarkeit des Sportbootes bei Nacht.","Bessere Erkennbarkeit des Sportbootes bei Taglicht.","Bessere Erkennbarkeit des Sportbootes bei unsichtigem Wetter."],"erklaerung":"Ein Radarreflektor macht das kleine Boot auf dem Radarbildschirm großer Schiffe besser sichtbar. Für das menschliche Auge ändert er nichts.","stichworte":["Radarreflektor","auf dem Radar sichtbar"]},{"nr":209,"teil":"binnen","thema":"sicherheit","frage":"Welche technische Einrichtung gegen einen Stromschlag muss in der Landstromversorgung unbedingt installiert sein?","inline":[],"bilder":[],"antworten":["Ein Fehlerstromschutzschalter.","Ein geringer Ladungsstrom ist ungefährlich.","Ein Überspannungsschutz.","Ein Schutzkleinspannungsschalter."],"erklaerung":"Ein Fehlerstromschutzschalter (FI-Schalter) schaltet bei Fehlerstrom blitzschnell ab und schützt so vor einem lebensgefährlichen Stromschlag. Am Wasser ist das besonders wichtig.","stichworte":["FI-Schalter","Landstrom","Stromschlag"]},{"nr":210,"teil":"binnen","thema":"schall","frage":"Welches Schallsignal ist zu geben, wenn in einer Notsituation Hilfe gebraucht wird?","inline":[],"bilder":[],"antworten":["Wiederholte lange Töne geben oder Gruppen von Glockenschlägen.","Wiederholte kurze Töne geben, keine Glockenschläge.","Einen langen Ton geben, vereinzelt Glockenschläge.","Drei kurze Töne geben, keine Glockenschläge."],"erklaerung":"Akustische Notsignale sind wiederholte lange Töne oder Gruppen von Glockenschlägen.","stichworte":["Notsignal","wiederholte lange Töne","Glockenschläge"]},{"nr":211,"teil":"binnen","thema":"schall","frage":"Welche Bedeutung hat am Tag das Kreisen einer roten Flagge auf einem Wasserfahrzeug?","inline":[],"bilder":[],"antworten":["Ein in Not befindliches Fahrzeug, das durch Sichtzeichen Hilfe herbeirufen will.","Ein manövrierbehindertes Fahrzeug, das durch Sichtzeichen Hilfe herbeirufen will.","Keine Bedeutung für den durchgehenden Schiffsverkehr.","Schützenswertes Fahrzeug, Vermeidung von Sog und Wellenschlag."],"erklaerung":"Eine rote Flagge, die im Kreis geschwenkt wird, ist ein Notsignal: Das Fahrzeug ist in Not und ruft Hilfe herbei.","stichworte":["Rote Flagge kreisen","Notsignal"]},{"nr":212,"teil":"binnen","thema":"schall","frage":"Welche Notsignale kann ein Segelsurfer auf Binnenschifffahrtsstraßen geben?","inline":[],"bilder":[],"antworten":["Kreisförmiges Schwenken der Arme oder eines Gegenstandes.","Kreisförmiges Schwenken einer grünen Flagge, die mit anderen Zeichen nicht verwechselt werden kann.","Wiederholt lange Gruppen von Glockenschlägen.","Kreisförmiges Schwenken der Arme ist zu vermeiden, das Surfsegel ist möglichst senkrecht zu stellen."],"erklaerung":"Ein Segelsurfer hat weder Horn noch Flagge. Er gibt Not zu erkennen, indem er die Arme oder einen Gegenstand im Kreis schwenkt.","stichworte":["Surfer","Arme kreisen","Notsignal"]},{"nr":213,"teil":"binnen","thema":"umwelt","frage":"Was ist mit Abfällen jeglicher Art zu tun, die an Bord anfallen?","inline":[],"bilder":[],"antworten":["An Bord sammeln und an Land in den entsprechenden Abfallsammelbehältern umweltgerecht entsorgen.","An Bord sammeln und bei einer Liegestelle an Land stellen.","An Bord sammeln und nur in geschlossenen Behältern über Bord werfen.","An Bord sammeln. Die Abgabe ist an jeder Schleuse möglich."],"erklaerung":"Alle Abfälle werden an Bord gesammelt und an Land in passenden Sammelbehältern entsorgt. Über Bord werfen ist verboten, auch in geschlossenen Behältern.","stichworte":["Abfall sammeln","an Land entsorgen"]},{"nr":214,"teil":"binnen","thema":"recht","frage":"Wem darf der Schiffsführer das Ruder eines motorisierten Sportbootes überlassen?","inline":[],"bilder":[],"antworten":["Einer Person, die mindestens 16 Jahre alt, sowie körperlich und geistig geeignet ist.","Einer Person, die mindestens 18 Jahre alt, sowie körperlich und geistig geeignet ist.","Einer Person, die mindestens 14 Jahre alt, sowie körperlich und geistig geeignet ist.","Einer Person jeden Alters, die körperlich und geistig geeignet ist."],"erklaerung":"Das Ruder eines Motorboots darf der Schiffsführer einer Person überlassen, die mindestens 16 Jahre alt und körperlich und geistig geeignet ist.","stichworte":["Ruder überlassen","mind. 16 Jahre","geeignet"]},{"nr":215,"teil":"binnen","thema":"umwelt","frage":"Wie müssen Abfälle entsorgt werden?","inline":[],"bilder":[],"antworten":["Es dürfen keinerlei Abfälle ins Wasser gelangen, Fäkalien und Öle sind an Land zu entsorgen.","Nur Abfälle, die die Umwelt nicht gefährden, dürfen 300 m vom Ufer ins Wasser eingeleitet werden.","Auf Seen dürfen keine Abfälle ins Wasser gelangen, auf Binnenschifffahrtsstraßen gibt es Sonderregelungen.","Alle Schiffe müssen mit Fäkalientanks ausgerüstet sein und geeignete Behältnisse für die getrennte Aufnahme von Abfällen an Bord haben."],"erklaerung":"Keinerlei Abfälle dürfen ins Wasser gelangen. Fäkalien und Öle werden an Land entsorgt. Eine Ausnahme mit Abstand zum Ufer gibt es nicht.","stichworte":["Nichts ins Wasser","Fäkalien und Öl an Land"]},{"nr":216,"teil":"binnen","thema":"umwelt","frage":"Was ist beim Neuanstrich des Unterwasserschiffs und bei der Entfernung des alten Anstrichs zu beachten?","inline":[],"bilder":[],"antworten":["Der Arbeitsbereich ist großzügig abzudecken und der anfallende Abfall ist als Sondermüll zu behandeln und entsprechend zu entsorgen.","Es dürfen nur Unterwasseranstriche verwendet werden, deren Umweltverträglichkeit an der EU-Kennzeichnung erkenntlich ist.","Es sind bei Arbeiten mit Unterwasseranstrichen die Richtlinien der Schiffsuntersuchungskommission zu beachten.","Unterwasserarbeiten dürfen nur von zertifizierten Fachbetrieben, nach den Bestimmungen des Umweltschutzes ausgeführt werden."],"erklaerung":"Beim Abschleifen und Streichen des Unterwasserschiffs fallen giftige Farbreste an. Der Arbeitsbereich wird deshalb großzügig abgedeckt, und die Reste werden als Sondermüll entsorgt.","stichworte":["Unterwasseranstrich","abdecken","Sondermüll"]},{"nr":217,"teil":"binnen","thema":"wetter","frage":"Was ist bei Sturmwarnung vom Schiffsführer eines Sportbootes unter Segel auf einem größeren Gewässer zu veranlassen?","inline":[],"bilder":[],"antworten":["Rettungsweste anlegen. Segel bergen, versuchen einen Hafen oder eine geschützte Bucht anzulaufen.","Rettungsweste anlegen. Alle Segel setzen, versuchen, einen Hafen oder eine geschützte Bucht anzulaufen.","Rettungsweste bereit halten. Segel bergen, versuchen, einen Hafen oder eine geschützte Bucht anzulaufen.","Rettungsweste anlegen. Segel setzen, versuchen die Gewässermitte anzulaufen."],"erklaerung":"Bei Sturmwarnung: sofort Rettungsweste anlegen (nicht nur bereitlegen), Segel bergen bzw. reduzieren und einen Hafen oder eine geschützte Bucht ansteuern.","stichworte":["Sturmwarnung","Weste an","Segel bergen","Hafen anlaufen"]},{"nr":218,"teil":"binnen","thema":"zeichen","frage":"Welche Fahrrinnenseite hat ein Talfahrer an seiner Backbordseite?","inline":[],"bilder":[],"antworten":["Die linke Fahrrinnenseite, gekennzeichnet durch grüne Spitztonnen oder Schwimmstangen.","Die rechte Fahrrinnenseite, gekennzeichnet durch rote Stumpftonnen oder Schwimmstangen.","Die linke Fahrrinnenseite, gekennzeichnet durch rote Stumpftonnen oder Schwimmstangen.","Die rechte Fahrrinnenseite, gekennzeichnet durch grüne Spitztonnen oder Schwimmstangen."],"erklaerung":"Ein Talfahrer fährt in Richtung der Uferbezeichnung: Rechts ist rechts. An Backbord hat er also die linke Fahrrinnenseite mit grünen Spitztonnen.","stichworte":["Talfahrt","Backbord = linke Seite","grün"]},{"nr":219,"teil":"binnen","thema":"wetter","frage":"Mit welcher Wetterentwicklung ist bei schnellem und stetig fallendem Luftdruck zu rechnen?","inline":[],"bilder":[],"antworten":["Schlechtes Wetter, Starkwind oder Sturm.","Besseres Wetter, steigende Temperatur.","Schlechtes Wetter ist nicht zu erwarten.","Besseres Wetter, Sonne."],"erklaerung":"Fällt der Luftdruck schnell und stetig, naht ein Tief: Mit schlechtem Wetter und Starkwind bis Sturm ist zu rechnen. Merkhilfe: Je schneller der Druck fällt, desto stärker wird der Wind.","stichworte":["Luftdruck fällt schnell","Starkwind","Sturm"]},{"nr":220,"teil":"binnen","thema":"wetter","frage":"Welches Wetter ist zu erwarten, wenn der Luftdruck langsam aber stetig steigt?","inline":[],"bilder":[],"antworten":["Besseres Wetter, Sonne.","Besseres Wetter, steigende Temperatur.","Schlechtes Wetter ist nicht zu erwarten.","Schlechtes Wetter, Starkwind oder Sturm."],"erklaerung":"Steigt der Luftdruck langsam, aber stetig, ist mit beständig besserem Wetter und Sonne zu rechnen.","stichworte":["Luftdruck steigt langsam","besseres Wetter"]},{"nr":221,"teil":"binnen","thema":"wassersport","frage":"Wo darf auf Binnenschifffahrtsstraßen Wasserski gelaufen werden?","inline":[],"bilder":[],"antworten":["Nur in durch Tafelzeichen freigegebenen Bereichen.","Außerhalb des Fahrwassers.","Außerhalb der Fahrrinne.","Überall, ohne die Schifffahrt zu gefährden."],"erklaerung":"Wasserski ist auf Binnenschifffahrtsstraßen nur in Bereichen erlaubt, die durch Tafelzeichen freigegeben sind.","stichworte":["Wasserski","nur freigegebene Bereiche","Tafelzeichen"]},{"nr":222,"teil":"binnen","thema":"wassersport","frage":"Zu welcher Tageszeit und bei welchen Sichtweiten darf auf den erlaubten Gewässerabschnitten Wasserski gelaufen werden?","inline":[],"bilder":[],"antworten":["Sonnenaufgang bis -untergang, Sicht 1 000 m und mehr.","Sonnenaufgang bis -untergang, Sicht 1 500 m und mehr.","Sonnenaufgang bis -untergang, Sicht 500 m und mehr.","Sonnenaufgang bis -untergang, Sicht 300 m und mehr."],"erklaerung":"Wasserski ist nur am Tag (Sonnenaufgang bis Sonnenuntergang) und bei mindestens 1000 m Sicht erlaubt.","stichworte":["Wasserski","Tag","Sicht mind. 1000 m"]},{"nr":223,"teil":"binnen","thema":"wassersport","frage":"Wie muss sich der Wasserskiläufer bei der Vorbeifahrt an Fahrzeugen, Schwimmkörpern oder Badenden verhalten?","inline":[],"bilder":[],"antworten":["Er muss im Kielwasser des Zugbootes bleiben.","Er darf bis zu 10 m beiderseits außerhalb des Kielwassers fahren.","Er darf bis zu 5 m beiderseits außerhalb des Kielwassers fahren.","Er muss uferseitig des Kielwassers fahren."],"erklaerung":"Fährt man an Fahrzeugen, Schwimmkörpern oder Badenden vorbei, muss der Wasserskiläufer im Kielwasser des Zugboots bleiben, damit er niemanden gefährdet.","stichworte":["Wasserski","im Kielwasser bleiben"]},{"nr":224,"teil":"binnen","thema":"wassersport","frage":"Unter welchen Voraussetzungen darf außerhalb der ausgewiesenen Strecken/Wasserflächen Wassermotorrad gefahren werden?","inline":[],"bilder":[],"antworten":["Bei Touren- und Wanderfahrten mit klarem Geradeauskurs.","Bei großen Sonderveranstaltungen außerhalb der Fahrrinne.","Wenn kein anderer Verkehrsteilnehmer behindert wird.","Ab Hochwassermarke I nur im Fahrwasser."],"erklaerung":"Außerhalb der ausgewiesenen Strecken darf man mit dem Wassermotorrad nur bei Touren- und Wanderfahrten mit klarem Geradeauskurs fahren. Kreisen, Kurven oder Springen sind dort verboten.","stichworte":["Wassermotorrad","Wanderfahrt","Geradeauskurs"]},{"nr":225,"teil":"binnen","thema":"wassersport","frage":"Wie hat sich der Führer eines Wassermotorrades außerhalb der ausgewiesenen Strecken/Wasserflächen zu verhalten?","inline":[],"bilder":[],"antworten":["Klaren Geradeauskurs fahren.","Im Abstand von 10 m zum Ufer fahren.","Im Abstand von 10 m außerhalb des Tonnenstrichs fahren.","Am Rande der Fahrrinne fahren."],"erklaerung":"Außerhalb der ausgewiesenen Flächen muss der Fahrer eines Wassermotorrads einen klaren Geradeauskurs halten.","stichworte":["Wassermotorrad","klarer Geradeauskurs"]},{"nr":226,"teil":"binnen","thema":"recht","frage":"Auf welchen Gewässern ist die Fahrerlaubnis für Sportboote unter Segeln erforderlich?","inline":[],"bilder":[],"antworten":["Auf bestimmten Wasserstraßen in Berlin und Brandenburg.","Auf allen Landesgewässern.","Auf den Binnenschifffahrtsstraßen und allen Landesgewässern.","Auf allen deutschen Wasserstraßen."],"erklaerung":"Eine Fahrerlaubnis für Segelboote braucht man nur auf bestimmten Wasserstraßen in Berlin und Brandenburg.","stichworte":["Segelschein Pflicht","Berlin","Brandenburg"]},{"nr":227,"teil":"binnen","thema":"recht","frage":"Weshalb muss sich der Schiffsführer vor dem Befahren fremder Gewässer über die dort geltenden Vorschriften informieren?","inline":[],"bilder":[],"antworten":["Um die jeweils geltenden Vorschriften einhalten zu können.","Da diese auf Landesgewässern grundsätzlich inhaltlich abweichen.","Da diese auf Bundesgewässern grundsätzlich inhaltlich abweichen.","Weil die jeweils geltenden Vorschriften wichtige Informationen über die Brückendurchfahrtshöhen enthalten."],"erklaerung":"In fremden Revieren können besondere Vorschriften gelten. Man muss sie kennen, um sie einhalten zu können.","stichworte":["Fremdes Revier","Vorschriften kennen"]},{"nr":228,"teil":"binnen","thema":"recht","frage":"Welcher Befähigungsnachweis berechtigt zum Führen eines Sportbootes bis zu einer Länge von 25 m auf dem Rhein?","inline":[],"bilder":[],"antworten":["Das Sportpatent.","Das Sportschifferzeugnis.","Der Sportbootführerschein mit dem Geltungsbereich Binnenschifffahrtsstraßen.","Der Sportbootführerschein mit dem Geltungsbereich Seeschifffahrtsstraßen."],"erklaerung":"Auf dem Rhein braucht man für Sportboote bis 25 m das Sportpatent. Das Sportschifferzeugnis gilt dort nicht.","stichworte":["Rhein","bis 25 m","Sportpatent"]},{"nr":229,"teil":"binnen","thema":"recht","frage":"Welcher Befähigungsnachweis berechtigt zum Führen eines Sportbootes mit einer Länge von 20 m bis 25 m auf den Binnenschifffahrtsstraßen außerhalb des Rheins?","inline":[],"bilder":[],"antworten":["Das Sportschifferzeugnis oder das Sportpatent.","Der Sportbootführerschein mit dem Geltungsbereich Binnenschifffahrtsstraßen.","Der Sportbootführerschein mit dem Geltungsbereich Seeschifffahrtsstraßen.","Der Sportbootführerschein mit dem Geltungsbereich Binnenschifffahrtsstraßen zum Führen von Sportbooten mit Antriebsmaschine oder das Sportpatent."],"erklaerung":"Außerhalb des Rheins braucht man für Sportboote von 20 bis 25 m das Sportschifferzeugnis oder das Sportpatent. Der SBF Binnen reicht nur bis unter 20 m.","stichworte":["20–25 m","Sportschifferzeugnis","Sportpatent"]},{"nr":230,"teil":"binnen","thema":"recht","frage":"Wo sind umfangreiche Hinweise auf die Binnenschifffahrtsstraßen und deren Grenzen zu finden?","inline":[],"bilder":[],"antworten":["Im Teil II der Binnenschifffahrtsstraßen-Ordnung.","Im Teil I der Binnenschifffahrtsstraßen-Ordnung.","In der Binnenschiffsuntersuchungsordnung.","In der Kleinfahrzeugkennzeichenverordnung."],"erklaerung":"In Teil II der BinSchStrO stehen die regionalen Bestimmungen, darunter die einzelnen Binnenschifffahrtsstraßen und ihre Grenzen. Teil I enthält die allgemeinen Verkehrsregeln.","stichworte":["BinSchStrO Teil II","Wasserstraßen und Grenzen"]},{"nr":231,"teil":"binnen","thema":"recht","frage":"Was ist bei der Ausübung des Wassersports auf Gewässern außerhalb der Bundeswasserstraßen (z. B. Landeswasserstraßen, kommunale und private Gewässer) zu beachten?","inline":[],"bilder":[],"antworten":["Es ist gegebenenfalls die Genehmigung des Eigentümers einzuholen sowie die jeweilige Befahrensordnung zu beachten.","Es ist immer die Genehmigung des Eigentümers einzuholen sowie die jeweilige Befahrensordnung zu beachten.","Es ist immer die Genehmigung des Wasserstraßen- und Schifffahrtsamtes einzuholen sowie die jeweilige Befahrensordnung zu beachten.","Es ist gegebenenfalls die Genehmigung des Eigentümers einzuholen sowie die Binnenschifffahrtsstraßen-Ordnung zu beachten."],"erklaerung":"Für Landes-, kommunale oder private Gewässer braucht man gegebenenfalls die Genehmigung des Eigentümers und muss die dort geltende Befahrensordnung beachten. Die BinSchStrO gilt dort nicht automatisch.","stichworte":["Landesgewässer","ggf. Genehmigung","Befahrensordnung"]},{"nr":232,"teil":"binnen","thema":"recht","frage":"Welche Kennzeichnungsarten für Sportboote gibt es?","inline":[],"bilder":[],"antworten":["Amtliche Kennzeichen und amtlich anerkannte Kennzeichen.","Nur amtliche Kennzeichen.","Nur amtlich anerkannte Kennzeichen.","Kennzeichen gemäß Konformitätserklärung (CE-Zeichen)."],"erklaerung":"Es gibt amtliche Kennzeichen (vom Wasserstraßen- und Schifffahrtsamt) und amtlich anerkannte Kennzeichen (von DMYV, DSV, ADAC).","stichworte":["Amtliches Kennzeichen","amtlich anerkanntes Kennzeichen"]},{"nr":233,"teil":"binnen","thema":"recht","frage":"Welche Stelle ist für die Zuteilung eines amtlichen Kennzeichens für Sportboote zuständig?","inline":[],"bilder":[],"antworten":["Jedes Wasserstraßen- und Schifffahrtsamt.","Der Deutsche Motoryachtverband.","Der Deutsche Segler-Verband.","Der Allgemeine Deutsche Automobilclub."],"erklaerung":"Amtliche Kennzeichen teilt jedes Wasserstraßen- und Schifffahrtsamt zu. Die Verbände vergeben nur die amtlich anerkannten.","stichworte":["Amtliches Kennzeichen","WSA"]},{"nr":234,"teil":"binnen","thema":"recht","frage":"Woraus bestehen die amtlich anerkannten Kennzeichen?","inline":[],"bilder":[],"antworten":["Nummer des Internationalen Bootsscheins, gefolgt vom Kennbuchstaben für die ausstellende Organisation.","Nummer des Binnenschiffsregisters, gefolgt vom Kennbuchstaben für die ausstellende Organisation.","Nummer des Seeschiffsregisters, gefolgt vom Kennbuchstaben für die ausstellende Organisation.","Die europäische Schiffsnummer, gefolgt vom Kennbuchstaben für die ausstellende Organisation."],"erklaerung":"Ein amtlich anerkanntes Kennzeichen besteht aus der Nummer des Internationalen Bootsscheins (IBS) und einem Kennbuchstaben für den ausstellenden Verband.","stichworte":["Internationaler Bootsschein","Nummer + Kennbuchstabe"]},{"nr":235,"teil":"binnen","thema":"recht","frage":"Welche Stellen sind für die Zuteilung eines amtlich anerkannten Kennzeichens für Sportboote zuständig?","inline":[],"bilder":[],"antworten":["Der Deutsche Motoryachtverband, der Deutsche Segler-Verband, der Allgemeine Deutsche Automobilclub.","Die Wasserstraßen- und Schifffahrtsämter.","Die Wasserschutzpolizei.","Amtsgerichte, bei denen ein Schiffsregister geführt wird."],"erklaerung":"Amtlich anerkannte Kennzeichen vergeben DMYV, DSV und ADAC, die auch den Internationalen Bootsschein ausstellen.","stichworte":["DMYV","DSV","ADAC"]},{"nr":236,"teil":"binnen","thema":"recht","frage":"Wann muss ein Wassersportfahrzeug in das Binnenschiffsregister eingetragen werden?","inline":[],"bilder":[],"antworten":["Ab 10 cbm Wasserverdrängung.","Ab 15 cbm Wasserverdrängung.","Ab 10 m Schiffslänge.","Ab 15 m Schiffslänge."],"erklaerung":"Ein Wassersportfahrzeug muss ab 10 m³ Wasserverdrängung ins Binnenschiffsregister eingetragen werden. Es kommt also auf die Verdrängung an, nicht auf die Länge.","stichworte":["Binnenschiffsregister","ab 10 m³ Verdrängung"]},{"nr":237,"teil":"binnen","thema":"gewaesser","frage":"Wie hat sich ein Schiffsführer bei Hochwasser zu verhalten?","inline":[],"bilder":[],"antworten":["Er muss die Geschwindigkeit anpassen und soweit wie möglich in der Fahrwassermitte bleiben, gegebenenfalls besondere Geschwindigkeitsbegrenzungen und Fahrtbeschränkungen beachten.","Er muss die Geschwindigkeit anpassen und soweit wie möglich in seiner Fahrtrichtung rechts fahren, gegebenenfalls besondere Geschwindigkeitsbegrenzungen und Fahrtbeschränkungen beachten.","Er muss die Geschwindigkeit anpassen und soweit wie möglich in seiner Fahrtrichtung links fahren, gegebenenfalls besondere Geschwindigkeitsbegrenzungen und Fahrtbeschränkungen beachten.","Er muss die Geschwindigkeit anpassen und soweit wie möglich in der Fahrwassermitte bleiben, besondere Geschwindigkeitsbegrenzungen und Fahrtbeschränkungen sind nicht zu beachten."],"erklaerung":"Bei Hochwasser passt man die Geschwindigkeit an und bleibt möglichst in der Fahrwassermitte. Am Rand liegen überflutete Ufer und Treibgut, und Wellenschlag schadet dort besonders. Besondere Beschränkungen gelten zusätzlich.","stichworte":["Hochwasser","Fahrwassermitte","Geschwindigkeit anpassen"]},{"nr":238,"teil":"binnen","thema":"gewaesser","frage":"Wie hat sich ein Schiffsführer bei Erreichen der Hochwassermarke II zu verhalten?","inline":[],"bilder":[],"antworten":["Er hat die Fahrt unverzüglich einzustellen.","Er hat die Geschwindigkeit anzupassen.","Er hat das Fahrverbot für Fahrzeuge ohne Sprechfunk zu beachten.","Er hat das Verbot der Schifffahrt bei Nacht zu beachten."],"erklaerung":"Bei Hochwassermarke II muss die Fahrt sofort eingestellt werden.","stichworte":["Hochwassermarke II","Fahrt einstellen"]},{"nr":239,"teil":"binnen","thema":"zeichen","frage":"Ein Fahrzeug fährt zu Tal. Voraus liegt eine rote Tonne. Auf welcher Fahrrinnenseite befindet sich diese Tonne und an welcher Schiffsseite muss diese Tonne passiert werden?","inline":[],"bilder":[],"antworten":["Sie befindet sich auf der rechten Fahrrinnenseite und muss an der Steuerbordseite des Schiffes passiert werden.","Sie befindet sich auf der rechten Fahrrinnenseite und muss an der Backbordseite des Schiffes passiert werden.","Sie befindet sich auf der linken Fahrrinnenseite und muss an der Steuerbordseite des Schiffes passiert werden.","Sie befindet sich auf der linken Fahrrinnenseite und muss an Backbordseite des Schiffes passiert werden."],"erklaerung":"Zu Tal stimmt die Uferbezeichnung mit der Fahrtrichtung überein. Rote Tonnen markieren die rechte Seite, sie liegen also an Steuerbord. Man passiert sie an Steuerbord und bleibt links davon in der Fahrrinne.","stichworte":["Talfahrt","rote Tonne = rechts","an Steuerbord passieren"]},{"nr":240,"teil":"binnen","thema":"zeichen","frage":"Ein Fahrzeug fährt zu Berg. Voraus liegt eine rote Tonne. Auf welcher Fahrrinnenseite befindet sich diese Tonne und an welcher Schiffsseite muss diese Tonne passiert werden?","inline":[],"bilder":[],"antworten":["Sie befindet sich auf der rechten Fahrrinnenseite und muss an der Backbordseite des Schiffes passiert werden.","Sie befindet sich auf der rechten Fahrrinnenseite und muss an der Steuerbordseite des Schiffes passiert werden.","Sie befindet sich auf der linken Fahrrinnenseite und muss an der Backbordseite des Schiffes passiert werden.","Sie befindet sich auf der linken Fahrrinnenseite und muss an der Steuerbordseite des Schiffes passiert werden."],"erklaerung":"Zu Berg ist die Uferbezeichnung umgekehrt zur Fahrtrichtung. Die rote Tonne (rechte Fahrrinnenseite) liegt dann an Backbord und wird dort passiert.","stichworte":["Bergfahrt","rote Tonne = rechts","an Backbord passieren"]},{"nr":241,"teil":"binnen","thema":"zeichen","frage":"Ein Fahrzeug fährt in der Fahrrinne gegen den Strom. Voraus liegt eine grüne Tonne. Auf welcher Fahrrinnenseite befindet sich diese Tonne und an welcher Schiffsseite muss diese Tonne passiert werden?","inline":[],"bilder":[],"antworten":["Sie befindet sich auf der linken Fahrrinnenseite und muss an der Steuerbordseite des Schiffes passiert werden.","Sie befindet sich auf der rechten Fahrrinnenseite und muss an der Steuerbordseite des Schiffes passiert werden.","Sie befindet sich auf der linken Fahrrinnenseite und muss an der Backbordseite des Schiffes passiert werden.","Sie befindet sich auf der rechten Fahrrinnenseite und muss an der Backbordseite des Schiffes passiert werden."],"erklaerung":"Gegen den Strom heißt zu Berg. Die grüne Tonne markiert die linke Fahrrinnenseite und liegt bei Bergfahrt an Steuerbord.","stichworte":["Bergfahrt","grüne Tonne = links","an Steuerbord passieren"]},{"nr":242,"teil":"binnen","thema":"zeichen","frage":"Welche Funktion haben gelbe Tonnen mit einem Radarreflektor vor Brückenpfeilern?","inline":[],"bilder":[],"antworten":["Kenntlichmachung der Brückenpfeiler auf dem Radarschirm.","Kenntlichmachung der Höhe der Brückenpfeiler.","Kenntlichmachung einer gesperrten Brückendurchfahrt.","Kenntlichmachung einer Untiefe im Brückenbereich."],"erklaerung":"Gelbe Tonnen mit Radarreflektor vor Brückenpfeilern machen die Pfeiler auf dem Radarschirm sichtbar, z. B. für Radarfahrt bei Nebel.","stichworte":["Gelbe Tonne","Radarreflektor","Brückenpfeiler"]},{"nr":243,"teil":"binnen","thema":"schleuse","frage":"Welche Bedeutung haben diese Tafeln an der nachstehenden gekennzeichneten Brücke?","inline":[],"bilder":["bilder/Bild-Frage-243.gif"],"antworten":["Empfohlene Durchfahrt mit Gegenverkehr und seitlicher Begrenzung der erlaubten Brückendurchfahrt.","Empfohlene Durchfahrt ohne Gegenverkehr und seitlicher Begrenzung der erlaubten Brückendurchfahrt.","Vorgeschriebene Durchfahrt mit Gegenverkehr und seitlicher Begrenzung der erlaubten Brückendurchfahrt.","Empfohlene Durchfahrt mit Gegenverkehr ohne seitliche Begrenzung der erlaubten Brückendurchfahrt."],"erklaerung":"Der gelbe Rhombus in der Mitte zeigt die empfohlene Durchfahrt mit Gegenverkehr. Die rot-weißen Tafeln an den Seiten begrenzen den Bereich, in dem die Durchfahrt erlaubt ist.","stichworte":["Ein Rhombus = empfohlen mit Gegenverkehr","rot-weiße Tafeln = seitliche Grenze"]},{"nr":244,"teil":"binnen","thema":"schleuse","frage":"Was bedeutet dieses Tafelzeichen an einer Brückendurchfahrt?","inline":[],"bilder":["bilder/Verbotszeichen-A01-Tafeln.gif"],"antworten":["Verbot der Durchfahrt und Sperrung der Schifffahrt.","Gesperrte Durchfahrt, jedoch für Kleinfahrzeuge mit Antriebsmaschine befahrbar.","Gesperrte Durchfahrt, jedoch für Kleinfahrzeuge ohne Antriebsmaschine befahrbar.","Schutzbedürftige Anlage."],"erklaerung":"Rot-weiß-rot bedeutet auch an einer Brücke: Durchfahrt verboten, gesperrt für alle.","stichworte":["Rot-weiß-rot","Durchfahrt verboten"]},{"nr":245,"teil":"binnen","thema":"schleuse","frage":"Warum ist es bei der Schleusendurchfahrt verboten, Autoreifen als Fender zu benutzen?","inline":[],"bilder":[],"antworten":["Autoreifen sind nicht schwimmfähig und können in den Schleusen zu erheblichen Störungen führen.","Autoreifen erzeugen eine zu hohe Reibung.","Autoreifen erzeugen schwarze Farbspuren am Boot und an der Schleusenmauer.","Autoreifen sind schwimmfähig und können in der Schleuse zu erheblichen Störungen führen."],"erklaerung":"Autoreifen schwimmen nicht. Gehen sie in der Schleuse verloren, sinken sie und können Tore, Antriebe oder Pumpen blockieren.","stichworte":["Autoreifen","nicht schwimmfähig","Schleuse blockiert"]},{"nr":246,"teil":"binnen","thema":"lichter","frage":"Welche Lichter führt ein Schubverband?","inline":[],"bilder":[],"antworten":["Drei weiße Topplichter in einem Dreieck angebracht, die Seitenlichter und drei weiße Hecklichter waagerecht nebeneinander.","Drei weiße Topplichter senkrecht untereinander angebracht, die Seitenlichter und drei weiße Hecklichter waagerecht nebeneinander.","Drei weiße Topplichter in einem Dreieck angebracht, die Seitenlichter und zwei weiße Hecklichter waagerecht nebeneinander.","Drei weiße Topplichter waagerecht nebeneinander, die Seitenlichter und drei weiße Hecklichter waagerecht nebeneinander."],"erklaerung":"Ein Schubverband führt drei weiße Topplichter im Dreieck, die Seitenlichter und drei weiße Hecklichter nebeneinander.","stichworte":["Schubverband","3 Topplichter im Dreieck","3 Hecklichter"]},{"nr":247,"teil":"binnen","thema":"lichter","frage":"Welches Fahrzeug führt am Bug einen roten Wimpel?","inline":[],"bilder":[],"antworten":["Ein Fahrzeug mit Vorrang beim Schleusen.","Ein Fahrzeug mit Vorrang beim Be- und Entladen.","Ein Fahrzeug, das explosive Stoffe geladen hat.","Ein Fahrzeug, das brennbare Stoffe geladen hat."],"erklaerung":"Ein roter Wimpel am Bug zeigt ein Fahrzeug mit Vorrang beim Schleusen (vgl. Frage 132).","stichworte":["Roter Wimpel","Vorrang beim Schleusen"]},{"nr":248,"teil":"binnen","thema":"recht","frage":"Wann gilt ein Sportboot auf den Binnenschifffahrtsstraßen als Kleinfahrzeug?","inline":[],"bilder":[],"antworten":["Wenn das Fahrzeug eine Länge von weniger als 20 m hat.","Wenn das Fahrzeug eine Länge von 20 m hat.","Wenn das Fahrzeug eine Länge von 25 m hat.","Wenn das Fahrzeug eine Länge von mehr als 20 m hat."],"erklaerung":"Ein Kleinfahrzeug ist ein Fahrzeug mit weniger als 20 m Länge. Genau 20 m ist schon kein Kleinfahrzeug mehr.","stichworte":["Kleinfahrzeug","weniger als 20 m"]},{"nr":249,"teil":"binnen","thema":"lichter","frage":"Welche Bedeutung hat die Bezeichnung eines Fahrzeuges mit einer rot-weißen Flagge und was ist zu beachten?","inline":[],"bilder":[],"antworten":["Schutzbedürftiges Fahrzeug, Geschwindigkeit vermindern und Sog und Wellenschlag vermeiden.","Schutzbedürftiges Fahrzeug, Geschwindigkeit beibehalten und Sog und Wellenschlag vermeiden.","Schutzbedürftiges Fahrzeug, Geschwindigkeit vermindern.","Schutzbedürftiges Fahrzeug, Sog und Wellenschlag vermeiden."],"erklaerung":"Eine rot-weiße Flagge kennzeichnet ein schutzbedürftiges Fahrzeug. Man vermindert die Geschwindigkeit und vermeidet Sog und Wellenschlag. Richtig ist nur die Antwort, die beides nennt.","stichworte":["Rot-weiße Flagge","schutzbedürftig","langsam","Sog vermeiden"]},{"nr":250,"teil":"binnen","thema":"schall","frage":"Welches optische Zeichen kann am Tage anstelle von vier kurzen Tönen gegeben werden?","inline":[],"bilder":[],"antworten":["Eine rote Flagge im unteren Halbkreis schwenken.","Eine rote Flagge im oberen Halbkreis schwenken.","Eine rote Flagge im Kreis schwenken.","Eine rote Flagge zeigen."],"erklaerung":"Statt vier kurzer Töne (manövrierunfähig) kann man am Tag eine rote Flagge im unteren Halbkreis schwenken. Im Kreis geschwenkt wäre sie dagegen ein Notsignal.","stichworte":["Manövrierunfähig","rote Flagge","unterer Halbkreis"]},{"nr":251,"teil":"binnen","thema":"schall","frage":"Welches optische Zeichen kann in der Nacht oder bei verminderter Sicht anstelle von vier kurzen Tönen gegeben werden?","inline":[],"bilder":[],"antworten":["Ein rotes Licht im unteren Halbkreis schwenken.","Ein rotes Licht im oberen Halbkreis schwenken.","Ein rotes Licht im Kreis schwenken.","Ein rotes Licht zeigen."],"erklaerung":"Nachts oder bei verminderter Sicht schwenkt man statt der Flagge ein rotes Licht im unteren Halbkreis.","stichworte":["Manövrierunfähig","rotes Licht","unterer Halbkreis"]},{"nr":252,"teil":"binnen","thema":"recht","frage":"Welcher Befähigungsnachweis ist zur Teilnahme am Binnenschifffahrtsfunk erforderlich?","inline":[],"bilder":[],"antworten":["Das UKW-Sprechfunkzeugnis für den Binnenschifffahrtsfunk.","Das CB-Sprechfunkzeugnis für den Binnenschifffahrtsfunk.","Das Seefunkzeugnis für den Binnenschifffahrtsfunk.","Das SRC-Sprechfunkzeugnis für den Binnenschifffahrtsfunk."],"erklaerung":"Für den Binnenschifffahrtsfunk braucht man das UKW-Sprechfunkzeugnis für den Binnenschifffahrtsfunk (UBI). Das SRC gilt nur für den Seefunk.","stichworte":["UBI","UKW-Sprechfunkzeugnis Binnen"]},{"nr":253,"teil":"binnen","thema":"fahrregeln","frage":"Was bedeutet Radarfahrt?","inline":[],"bilder":[],"antworten":["Eine Fahrt bei unsichtigem Wetter mit Radar.","Eine Fahrt bei Nacht mit Radar.","Eine Fahrt mit Radar.","Eine Fahrt am Tage mit Radar."],"erklaerung":"Radarfahrt ist eine Fahrt mit Radar bei unsichtigem Wetter. Nur mit Radar zu fahren, auch nachts, ist noch keine Radarfahrt.","stichworte":["Radarfahrt","unsichtiges Wetter"]},{"nr":254,"teil":"segeln","thema":"boot","frage":"Was wird unter einem \"Kimmkieler\" verstanden?","inline":[],"bilder":[],"antworten":["Eine Yacht mit zwei Seitenkielen.","Eine Yacht mit zwei Seitenschwertern.","Eine Yacht mit einem Kielschwert.","Eine Yacht mit zwei Kielen hintereinander."],"erklaerung":"Ein Kimmkieler hat zwei Seitenkiele, links und rechts unter dem Rumpf („Kimm“ ist der Übergang vom Boden zur Bordwand).","stichworte":["Kimmkieler","zwei Seitenkiele"]},{"nr":255,"teil":"segeln","thema":"boot","frage":"Worin besteht der Vorteil eines Kimmkielers gegenüber anderen Kielbooten?","inline":[],"bilder":[],"antworten":["Er kann problemlos aufrecht trocken fallen.","Sein Tiefgang ist größer.","Die Abdrift ist geringer als bei anderen Kielbooten.","Der Kiel lässt sich aufholen."],"erklaerung":"Auf seinen zwei Kielen kann ein Kimmkieler aufrecht trockenfallen, z. B. bei Ebbe oder auf dem Trailer.","stichworte":["Kimmkieler","aufrecht trockenfallen"]},{"nr":256,"teil":"segeln","thema":"boot","frage":"Was wird unter einer \"Kielschwertyacht\" verstanden?","inline":[],"bilder":[],"antworten":["Eine Yacht mit flach gehendem Ballastkiel und zusätzlichem aufholbarem Schwert.","Eine Yacht mit einem Ballastkiel und einem zusätzlichen Schwert.","Eine Yacht mit einem aufholbaren Ballastkiel.","Eine Yacht mit zwei Seitenkielen."],"erklaerung":"Eine Kielschwertyacht hat einen flachen Ballastkiel für die Stabilität und zusätzlich ein Schwert, das man aufholen kann. So kombiniert sie wenig Tiefgang mit guten Amwind-Eigenschaften.","stichworte":["Kielschwerter","flacher Ballastkiel","aufholbares Schwert"]},{"nr":257,"teil":"segeln","thema":"boot","frage":"Wodurch wirken die Bodenlenzventile einer Jolle, die unterhalb der Wasserlinie liegen?","inline":[],"bilder":[],"antworten":["Durch den Sog, der bei Fahrt durchs Wasser entsteht.","Durch die Schwerkraft fließt das Wasser außenbords.","Durch die Massenträgheit, die das Boot besitzt.","Durch das Druckgefälle zwischen Luft- und Wasserdruck."],"erklaerung":"Bodenlenzventile wirken durch den Sog, der unter dem Boot bei Fahrt entsteht. Dieser saugt das Wasser aus dem Boot. Ohne Fahrt funktionieren sie nicht.","stichworte":["Lenzventil","Sog bei Fahrt"]},{"nr":258,"teil":"segeln","thema":"boot","frage":"Was wird unter \"Formstabilität\" verstanden?","inline":[],"bilder":[],"antworten":["Die Fähigkeit eines Schiffes, durch seine Rumpfform der Krängung entgegenzuwirken.","Die Fähigkeit eines Schiffes, sich nach einer Kenterung wieder von selbst aufzurichten.","Die Fähigkeit eines Schiffes beim Loslassen der Pinne den Kurs beizubehalten.","Die Fähigkeit eines Schiffes über Jahre die Rumpfform auch bei starker Beanspruchung beizubehalten."],"erklaerung":"Ein formstabiles Boot widersteht der Krängung durch seine breite, flache Rumpfform. Wenn es sich neigt, wandert der Auftrieb zur tieferen Seite und richtet es auf.","stichworte":["Formstabilität","Rumpfform","breit und flach"]},{"nr":259,"teil":"segeln","thema":"boot","frage":"Was wird unter \"Gewichtsstabilität\" verstanden?","inline":[],"bilder":[],"antworten":["Die Fähigkeit eines Schiffes, durch seinen tief liegenden Ballast der Krängung entgegenzuwirken.","Die Möglichkeit durch zusätzlichen Innenballast die Krängung zu verringern.","Die Möglichkeit durch ein hohes Crewgewicht der Krängung entgegenzuwirken.","Die Fähigkeit eines Schiffes, durch seine Rumpfform der Krängung entgegenzuwirken."],"erklaerung":"Ein gewichtsstabiles Boot widersteht der Krängung durch tief liegendes Gewicht (Ballastkiel). Wie ein Stehaufmännchen zieht das Gewicht das Boot wieder aufrecht.","stichworte":["Gewichtsstabilität","Ballastkiel","tiefer Schwerpunkt"]},{"nr":260,"teil":"segeln","thema":"boot","frage":"Welche Boote sind vorwiegend \"gewichtsstabil\"?","inline":[],"bilder":[],"antworten":["Kielyachten sind vorwiegend \"gewichtsstabil\".","Jollen sind vorwiegend \"gewichtsstabil\".","Katamarane sind vorwiegend \"gewichtsstabil\".","Trimarane sind vorwiegend \"gewichtsstabil\"."],"erklaerung":"Kielyachten sind vorwiegend gewichtsstabil, weil ihr schwerer Ballastkiel sie aufrichtet.","stichworte":["Kielyacht","gewichtsstabil"]},{"nr":261,"teil":"segeln","thema":"boot","frage":"Welche Boote sind vorwiegend \"formstabil\"?","inline":[],"bilder":[],"antworten":["Jollen sind vorwiegend \"formstabil\".","Kielyachten sind vorwiegend \"formstabil\".","Kimmkieler sind vorwiegend \"formstabil\".","Kielschwertyachten sind vorwiegend \"formstabil\"."],"erklaerung":"Jollen haben keinen Ballastkiel und sind vor allem durch ihre breite Form stabil, also formstabil. Dazu kommt das Gewicht der Crew.","stichworte":["Jolle","formstabil"]},{"nr":262,"teil":"segeln","thema":"boot","frage":"Wodurch kann bei formstabilen Booten bei viel Wind die Stabilität erhöht werden?","inline":[],"bilder":[],"antworten":["Durch Ausreiten bzw. durch Benutzung der Trapezeinrichtung.","Durch Verlagerung von Innenballast.","Durch Umpumpen von Wasserballast.","Durch Ausfahren von sogenannten Trimmklappen oder eines Zusatzschwertes."],"erklaerung":"Bei formstabilen Booten wie Jollen hängt sich die Crew bei viel Wind nach außen (Ausreiten bzw. Trapez). Das Gewicht wirkt dann an einem langen Hebel gegen die Krängung.","stichworte":["Ausreiten","Trapez","Crewgewicht nach Luv"]},{"nr":263,"teil":"segeln","thema":"boot","frage":"Wie verändert sich das aufrichtende Kraftmoment einer Jolle bei Krängung?","inline":[],"bilder":[],"antworten":["Es nimmt anfangs zu bis zu einem Maximum, von da wieder ab, bis Auftriebs- und Gewischtsschwerpunkt übereinander liegen, anschließend kentert die Jolle.","Es nimmt anfangs ab bis zu einem Minimum, von da wieder zu, bis Auftriebs- und Gewichtsschwerpunkt übereinander liegen, anschließend kentert die Jolle.","Es nimmt anfangs ab und erreicht ein Maximum, wenn Auftriebs- und Gewichtsschwerpunkt übereinander liegen, anschließend kentert die Jolle.","Es nimmt anfangs ab und erreicht sein Minimum, bis Auftriebs- und Gewichtsschwerpunkt übereinander liegen, anschließend kentert die Jolle."],"erklaerung":"Bei einer Jolle wächst das aufrichtende Moment zuerst mit der Krängung bis zu einem Maximum und nimmt dann wieder ab. Liegen Auftriebs- und Gewichtsschwerpunkt übereinander, ist das Moment null, und die Jolle kentert.","stichworte":["Jolle","erst zu, dann ab","Kenterpunkt"]},{"nr":264,"teil":"segeln","thema":"boot","frage":"Wie verändert sich das aufrichtende Kraftmoment einer Kielyacht bei stetig zunehmender Krängung?","inline":[],"bilder":[],"antworten":["Es nimmt zu und erreicht nach Überschreitung des Maximums seinen kritischen Winkel erst bei über 90°.","Es nimmt bis zum Erreichen des kritischen Winkels zu, der bei etwa 70° liegt.","Es nimmt bis zum Erreichen des kritischen Winkels von 90° ab.","Es nimmt bis 90° Krängung ab und dann stetig zu."],"erklaerung":"Bei der Kielyacht wächst das aufrichtende Moment mit der Krängung. Auch nach dem Maximum bleibt es noch lange positiv: Der kritische Winkel liegt erst jenseits von 90°. Deshalb richtet sich eine Kielyacht fast immer wieder auf.","stichworte":["Kielyacht","kritischer Winkel über 90°","richtet sich auf"]},{"nr":265,"teil":"segeln","thema":"boot","frage":"Welche Maßnahme ist bei Ruderbruch auf einer Jolle zu treffen?","inline":[],"bilder":[],"antworten":["Notruder oder Paddel als Ersatz nehmen, Fahrwasser verlassen, sich als manövrierunfähig zu erkennen geben.","Sofort ankern und einen Notruf absetzen, Signalkörper (blauer Kegel) setzen.","Rote Flagge kreisförmig schwenken, Schleppleine bereithalten.","Segel bergen, Motor starten und in Rückwärtsfahrt das Ufer ansteuern."],"erklaerung":"Bei Ruderbruch: mit Notruder oder Paddel steuern, das Fahrwasser verlassen und sich als manövrierunfähig zu erkennen geben (vier kurze Töne bzw. rote Flagge im unteren Halbkreis).","stichworte":["Ruderbruch","Notruder/Paddel","Fahrwasser verlassen","manövrierunfähig anzeigen"]},{"nr":266,"teil":"segeln","thema":"boot","frage":"Wodurch kann eine Pinnensteuerung auch bei Krängung des Bootes sicher erreicht und bedient werden?","inline":[],"bilder":[],"antworten":["Durch einen Pinnenausleger.","Durch Verstellen des Travellers.","Durch das Ausreiten mit Hilfe des Trapezes.","Durch Ersetzen der Pinne durch ein Rad."],"erklaerung":"Ein Pinnenausleger ist eine Verlängerung der Pinne. Mit ihm kann der Steuermann auch weit außen sitzen oder ausreiten und trotzdem sicher steuern.","stichworte":["Pinnenausleger","Steuern beim Ausreiten"]},{"nr":267,"teil":"segeln","thema":"segel","frage":"Warum sollte Tauwerk an Bord stets ordentlich aufgeschossen werden?","inline":[],"bilder":[],"antworten":["Damit es im Gebrauchsfall klar liegt.","Damit es trocknen kann und nicht verrottet.","Damit die Reißfestigkeit erhalten bleibt.","Damit es nicht durch UV-Strahlung beschädigt wird."],"erklaerung":"Ordentlich aufgeschossenes Tauwerk liegt „klar“: Im Ernstfall lässt es sich sofort und ohne Knoten oder Kinken verwenden.","stichworte":["Aufschießen","klar zum Gebrauch"]},{"nr":268,"teil":"segeln","thema":"segel","frage":"Warum sollten Fallen stets ordentlich aufgeschossen werden?","inline":[],"bilder":[],"antworten":["Damit sie im Gebrauchsfall schnell und sicher gefiert werden können.","Damit sie trocknen können und nicht verrotten.","Damit sie nicht durch UV-Strahlung beschädigt werden.","Damit sie nicht mit den Schoten verwechselt werden können."],"erklaerung":"Ordentlich aufgeschossene Fallen kann man schnell und sicher fieren, z. B. um bei einer Bö das Segel zu bergen, ohne dass sich etwas verheddert.","stichworte":["Fallen","aufschießen","schnell fieren"]},{"nr":269,"teil":"segeln","thema":"segel","frage":"Wie heißen die Ecken eines Segels?","inline":[],"bilder":[],"antworten":["Kopf, Hals, Schothorn.","Kopf, Hals, Nock.","Vorliek, Unterliek, Achterliek.","Vorstag, Unterwant, Achterstag."],"erklaerung":"Die drei Ecken eines Segels heißen Kopf (oben), Hals (vorne unten) und Schothorn (hinten unten, dort sitzt die Schot). Die „-lieken“ sind die Kanten.","stichworte":["Kopf","Hals","Schothorn","Ecken"]},{"nr":270,"teil":"segeln","thema":"segel","frage":"Wie heißen die Kanten eines Segels?","inline":[],"bilder":[],"antworten":["Vorliek, Unterliek, Achterliek.","Kopf, Hals, Nock.","Vorstag, Unterwant, Achterstag.","Kopf, Hals, Schothorn."],"erklaerung":"Die Kanten eines Segels heißen Vorliek (vorn), Unterliek (unten) und Achterliek (hinten).","stichworte":["Vorliek","Unterliek","Achterliek","Kanten"]},{"nr":271,"teil":"segeln","thema":"segel","frage":"Wozu dienen Segellatten?","inline":[],"bilder":[],"antworten":["Der Formgebung und Aussteifung des Segels.","Der Erleichterung des Reffens.","Der Verhinderung des Killens von Segeln.","Der Möglichkeit das Segel auch bei Starkwind nutzen zu können."],"erklaerung":"Segellatten stecken in Taschen im Achterliek und steifen das Segel aus. Sie geben ihm seine Form, besonders hinten am Achterliek.","stichworte":["Segellatten","Form","Aussteifung"]},{"nr":272,"teil":"segeln","thema":"segel","frage":"Weshalb dürfen Segel nicht über einen längeren Zeitraum killen?","inline":[],"bilder":[],"antworten":["Killen schädigt das Tuch und lässt Nähte aufgehen.","Killen lässt das Boot bei stärkerem Wind kentern.","Killen führt zu Verletzungen der Besatzung.","Killen führt zu Beschädigungen an nebeneinander liegenden Schiffen."],"erklaerung":"Killen, also Flattern, lässt das Tuch hin und her schlagen. Das scheuert das Gewebe auf und lässt Nähte reißen.","stichworte":["Killen","Tuch beschädigt","Nähte"]},{"nr":273,"teil":"segeln","thema":"segel","frage":"Warum müssen auch kleine Schäden an den Segeln sofort repariert werden?","inline":[],"bilder":[],"antworten":["Weil unter Winddruck daraus schnell große Schäden werden.","Weil dadurch der Vortrieb des Segels leidet.","Weil es nur noch bei Flaute eingesetzt werden kann.","Weil Feuchtigkeit in das Segel eindringen kann."],"erklaerung":"Unter dem Winddruck reißen kleine Löcher oder offene Nähte schnell weiter. Aus einem kleinen Schaden wird so rasch ein großer.","stichworte":["Kleiner Schaden","reißt weiter","sofort reparieren"]},{"nr":274,"teil":"segeln","thema":"segel","frage":"Woran kann wärend der Fahrt die Richtung des wahren Windes erkannt werden?","inline":[],"bilder":[],"antworten":["An Flaggen oder anderen Anzeichen an Land.","An der Zugrichtung von Wolken.","An der Nationalflagge am Heck.","An den Trimmfäden im Großsegel."],"erklaerung":"Den wahren Wind erkennt man an Dingen, die sich nicht mitbewegen, z. B. Flaggen an Land oder Rauch. An Bord misst man wegen der eigenen Fahrt immer den scheinbaren Wind.","stichworte":["Wahrer Wind","Flaggen an Land"]},{"nr":275,"teil":"segeln","thema":"segel","frage":"Welcher Wind wird in Fahrt von Standern bzw. Verklickern angezeigt?","inline":[],"bilder":[],"antworten":["Der scheinbare Wind.","Der Fahrtwind.","Der wahre Wind.","Die Windrichtung."],"erklaerung":"Stander und Verklicker am Boot zeigen in Fahrt den scheinbaren Wind, also den wahren Wind zusammen mit dem Fahrtwind.","stichworte":["Verklicker","Stander","scheinbarer Wind"]},{"nr":276,"teil":"segeln","thema":"segel","frage":"Wann kommen wahrer Wind und scheinbarer Wind auf einem segelnden Boot aus der gleichen Richtung?","inline":[],"bilder":[],"antworten":["Auf Vorwindkurs.","Auf Halbwindkurs.","Auf Amwindkurs.","Auf Raumschotkurs."],"erklaerung":"Auf Vorwindkurs kommen wahrer Wind und Fahrtwind aus genau entgegengesetzten Richtungen. Der scheinbare Wind hat dann die gleiche Richtung wie der wahre, ist aber schwächer.","stichworte":["Vorwindkurs","gleiche Richtung"]},{"nr":277,"teil":"segeln","thema":"segel","frage":"Warum ist der scheinbare Wind auf einem Vorwindkurs schwächer als der wahre Wind?","inline":[],"bilder":[],"antworten":["Der wahre Wind vermindert sich um den entgegenstehenden Fahrtwind.","Der wahre Wind wird durch den Fahrtwind abgebremst.","Der scheinbare Wind wird durch den Unterdruck am Segel entlang abgebremst.","Der scheinbare Wind ist unabhängig von der Windrichtung immer schwächer als der wahre Wind."],"erklaerung":"Auf Vorwindkurs weht der Fahrtwind von vorne, der wahre Wind von hinten. Der Fahrtwind wird also vom wahren Wind abgezogen, der scheinbare Wind ist schwächer.","stichworte":["Vorwind","Fahrtwind abgezogen","schwächer"]},{"nr":278,"teil":"segeln","thema":"segel","frage":"Warum ist der scheinbare Wind auf einem Kurs hoch am Wind stärker als der wahre Wind?","inline":[],"bilder":[],"antworten":["Da sich auf diesem Kurs der wahre Wind und der Fahrtwind in Richtung und Stärke addieren.","Da sich auf diesem Kurs eine Düse zwischen Fock- und Großsegel bildet, die den Wind verstärkt.","Da der wahre Wind beim Amwindkurs stärker ist als bei raumen Kursen.","Da der scheinbare Wind unabhängig von der Windrichtung immer stärker als der wahre Wind ist."],"erklaerung":"Hoch am Wind kommen wahrer Wind und Fahrtwind beide eher von vorn und addieren sich. Deshalb ist der scheinbare Wind stärker als der wahre.","stichworte":["Am Wind","Fahrtwind addiert sich","stärker"]},{"nr":279,"teil":"segeln","thema":"segel","frage":"Auf einem Amwindkurs wurde gerefft. Ein entgegenkommendes Boot gleichen Typs segelt ungerefft. Wie lässt sich das erklären?","inline":[],"bilder":[],"antworten":["Der scheinbare Wind ist auf Amwindkursen stärker, auf Raumschot- und Vorwindkursen schwächer als der wahre Wind.","Boote sind stabiler, wenn der Wind achterlicher einfällt.","Der wahre Wind staut sich am Segel bei Raumschotkurs und ist deshalb schwächer.","Bei Amwindkurs streicht der Wind am tragflächenartig gewölbten Segel entlang und wird dadurch beschleunigt."],"erklaerung":"Am Wind ist der scheinbare Wind stärker als der wahre, auf raumen Kursen schwächer. Das Boot am Wind spürt mehr Wind und refft deshalb früher als das entgegenkommende Boot auf raumem Kurs.","stichworte":["Am Wind mehr Wind","raum weniger Wind","Reffen"]},{"nr":280,"teil":"segeln","thema":"segel","frage":"Warum raumt beim Einfallen einer Bö auf Amwindkurs der scheinbare Wind?","inline":[],"bilder":[],"antworten":["Da der Fahrtwind zunächst gleich bleibt, der wahre Wind jedoch zunimmt, kommt der daraus resultierende scheinbare Wind raumer.","Da durch die Koreoliskraft der Wind auch seine Richtung ändert, wenn er stärker wird.","Da durch den Trimm des Bootes sich der Kurs automatisch ändert, wenn der Wind zunimmt.","Da die Windrichtung durch die Segelstellung beeinflusst wird, verändert sich auch der scheinbare Wind."],"erklaerung":"In einer Bö nimmt der wahre Wind sofort zu, das Boot beschleunigt aber erst verzögert, der Fahrtwind bleibt also zunächst gleich. Der stärkere wahre Wind dreht den scheinbaren Wind weiter nach achtern: Er „raumt“.","stichworte":["Bö","wahrer Wind stärker","Fahrtwind gleich","scheinbarer Wind raumt"]},{"nr":281,"teil":"segeln","thema":"segel","frage":"Beim Einfallen einer Bö auf Amwindkurs raumt der scheinbare Wind. Welchen Nutzen kann auf der Kreuz daraus gezogen werden?","inline":[],"bilder":[],"antworten":["Mitluven, um weitere Höhe zu gewinnen.","Abfallen, um maximale Höhe zu segeln.","Segel etwas fieren, um die Bö in Krängung umzusetzen.","Ein Spinnacker kann gesetzt werden."],"erklaerung":"Raumt der Wind in der Bö, kann man mitluven, also höher an den Wind gehen, und so Höhe gewinnen.","stichworte":["Bö","Mitluven","Höhe gewinnen"]},{"nr":282,"teil":"segeln","thema":"trimm","frage":"Wie sollte das Schwert einer Jolle auf Vorwindkurs gefahren werden und warum?","inline":[],"bilder":[],"antworten":["Es sollte aufgeholt werden. Dadurch vermindert sich der Reibungswiderstand, aber auch die Gefahr der Kenterung bei einer unfreiwilligen Halse.","Es sollte gefiert werden. Dadurch wird das Boot stabiler und die Gefahr der Kenterung bei einer unfreiwilligen Halse reduziert.","Es sollte nie ganz aufgeholt werden, da es sonst bei einer Kenterung zum Aufrichten der Jolle nicht mehr greifbar ist.","Es sollte bei stärkerem Wind ganz aufgeholt werden, um die Steuerfähigkeit der Jolle zu verbessern."],"erklaerung":"Vorwind braucht man kaum seitlichen Widerstand. Ist das Schwert aufgeholt, gibt es weniger Reibung. Außerdem „stolpert“ die Jolle bei einer ungewollten Halse nicht über das Schwert und kentert weniger leicht.","stichworte":["Vorwind","Schwert hoch","weniger Reibung","weniger Kentergefahr"]},{"nr":283,"teil":"segeln","thema":"trimm","frage":"Wie verändern sich Abdrift und Krängung, wenn das Schwert einer Jolle auf einem Amwindkurs etwas aufgeholt wird?","inline":[],"bilder":[],"antworten":["Die Abdrift wird größer, die Krängung nimmt ab.","Die Abdrift wird größer, die Krängung nimmt zu.","Die Abdrift nimmt ab, das Boot wird aufgrund des geringeren Wasserwiderstandes schneller.","Die Abdrift wird kleiner, die Krängung nimmt ab."],"erklaerung":"Ist das Schwert teilweise aufgeholt, hat die Jolle weniger Lateralplan und treibt stärker ab. Gleichzeitig hat der Wind weniger Widerstand, um das Boot umzudrücken, sodass die Krängung abnimmt.","stichworte":["Schwert hoch","mehr Abdrift","weniger Krängung"]},{"nr":284,"teil":"segeln","thema":"trimm","frage":"Mit welcher Krängung sollte eine Jolle üblicherweise gesegelt werden und weshalb?","inline":[],"bilder":[],"antworten":["Möglichst aufrecht, da sonst Abdrift und Luvgierigkeit zunehmen.","Möglichst aufrecht, weil sonst Abdrift und Leegierigkeit zunehmen.","Leicht nach Lee geneigt, da sonst die Segel leicht nach Luv überkommen können.","Möglichst nach Luv geneigt, weil dadurch die Abdrift und die Luvgierigkeit abnehmen."],"erklaerung":"Eine Jolle segelt man möglichst aufrecht. Krängt sie, wird sie luvgierig, drängt also in den Wind, und treibt stärker ab, weil das Schwert schräg steht.","stichworte":["Jolle aufrecht","sonst Luvgierigkeit und Abdrift"]},{"nr":285,"teil":"segeln","thema":"trimm","frage":"Wie wirkt sich auf einem Halbwindkurs ein zu dicht geholtes Großsegel auf die Geschwindigkeit des Bootes aus?","inline":[],"bilder":[],"antworten":["Die Krängung nimmt zu, die Geschwindigkeit nimmt ab.","Die Krängung und die Geschwindigkeit nehmen bis zum kritischen Punkt zu, darüber hinaus schnell ab.","Die Geschwindigkeit nimmt zu, da dadurch die Windkräfte optimaler genutzt werden.","Das Boot bleibt stehen, da die Strömung abreißt."],"erklaerung":"Auf Halbwind muss das Segel weiter geöffnet sein. Ist es zu dicht geholt, reißt die Strömung ab und das Segel drückt nur noch seitlich: mehr Krängung, weniger Fahrt.","stichworte":["Halbwind","zu dicht","mehr Krängung","langsamer"]},{"nr":286,"teil":"segeln","thema":"trimm","frage":"Wie wirkt sich ein Holepunkt, der zu weit vorne liegt, auf Stand und Beanspruchung des Vorsegels aus?","inline":[],"bilder":[],"antworten":["Das Unterliek killt, das Achterliek wird übermäßig gereckt.","Das Achterliek killt, das Vorliek wird übermäßig gereckt.","Das Vorliek killt, das Unterliek wird übermäßig gereckt.","Das Vorliek killt, das Achterliek wird übermäßig gereckt."],"erklaerung":"Liegt der Holepunkt zu weit vorn, zieht die Schot vor allem nach unten. Das Achterliek wird stramm gereckt, das Unterliek bleibt lose und killt.","stichworte":["Holepunkt vorn","Achterliek gereckt","Unterliek killt"]},{"nr":287,"teil":"segeln","thema":"trimm","frage":"Wie wirkt sich ein Holepunkt, der zu weit achtern liegt, auf Stand und Beanspruchung des Vorsegels aus?","inline":[],"bilder":[],"antworten":["Das Achterliek killt, das Unterliek wird übermäßig gereckt.","Das Vorliek killt, das Unterliek wird übermäßig gereckt.","Das Unterliek killt, das Achterliek wird übermäßig gereckt.","Das Achterliek killt, das Vorliek wird übermäßig gereckt."],"erklaerung":"Liegt der Holepunkt zu weit achtern, zieht die Schot vor allem nach hinten. Das Unterliek wird übermäßig gereckt, das Achterliek bleibt lose und killt.","stichworte":["Holepunkt achtern","Unterliek gereckt","Achterliek killt"]},{"nr":288,"teil":"segeln","thema":"trimm","frage":"Wie muss ein Segel bei leichtem Wind getrimmt werden?","inline":[],"bilder":[],"antworten":["Das Segel soll bauchig stehen.","Das Segel soll flach getrimmt werden.","Die Schoten müssen gefiert werden.","Die Schoten müssen dicht geholt werden."],"erklaerung":"Bei leichtem Wind trimmt man das Segel bauchig. Ein tiefes Profil holt aus wenig Wind mehr Vortrieb.","stichworte":["Leichter Wind","bauchig"]},{"nr":289,"teil":"segeln","thema":"trimm","frage":"Wie muss ein Segel bei starkem Wind getrimmt werden?","inline":[],"bilder":[],"antworten":["Das Segel soll flach getrimmt werden.","Es soll bauchig getrimmt werden.","Die Schoten müssen dicht geholt werden.","Die Schoten müssen gefiert werden."],"erklaerung":"Bei starkem Wind trimmt man das Segel flach. Ein flaches Profil erzeugt weniger Druck und Krängung.","stichworte":["Starker Wind","flach"]},{"nr":290,"teil":"segeln","thema":"trimm","frage":"Wie beeinflusst ein Unterliekstrecker den Trimm des Segels?","inline":[],"bilder":[],"antworten":["Je nach Zugkraft wird der untere Teil des Großsegels bauchiger oder flacher.","Je nach Zugkraft wird der untere Teil des Vorsegels bauchiger oder flacher.","Je nach Zugkraft wird der achtere Teil des Vorsegels bauchiger oder flacher.","Je nach Zugkraft wird der achtere Teil des Großsegels bauchiger oder flacher."],"erklaerung":"Der Unterliekstrecker spannt das Unterliek des Großsegels. Viel Zug macht den unteren Teil des Großsegels flacher, wenig Zug bauchiger.","stichworte":["Unterliekstrecker","Großsegel unten","flach/bauchig"]},{"nr":291,"teil":"segeln","thema":"trimm","frage":"Um auf Amwindkursen eine Jolle auf Kurs zu halten, muss die Pinne stets stark von der Seite der Segel weggezogen werden. Wie kann der Trimmfehler behoben werden?","inline":[],"bilder":[],"antworten":["Großsegel flacher trimmen; Gewichtsverlagerung nach achtern.","Großsegel flacher trimmen; Gewichtsverlagerung nach vorne.","Vorsegel flacher trimmen; Gewichtsverlagerung nach achtern.","Vorsegel flacher trimmen; Gewichtsverlagerung nach vorne."],"erklaerung":"Muss man die Pinne ständig von den Segeln weg (nach Luv) ziehen, ist das Boot zu luvgierig. Abhilfe: Großsegel flacher trimmen (weniger Druck achtern) und das Gewicht nach achtern verlagern.","stichworte":["Zu luvgierig","Groß flacher","Gewicht nach achtern"]},{"nr":292,"teil":"segeln","thema":"trimm","frage":"Um auf Amwindkursen eine Jolle auf Kurs zu halten, muss die Pinne stets stark zur Seite der Segel hingedrückt werden. Wie kann der Trimmfehler behoben werden?","inline":[],"bilder":[],"antworten":["Großsegel bauchiger trimmen, Gewichtsverlagerung nach vorn.","Großsegel flacher trimmen, Gewichtsverlagerung nach vorn.","Großsegel bauchiger trimmen, Gewichtsverlagerung nach hinten.","Großsegel flacher trimmen, Gewichtsverlagerung nach hinten."],"erklaerung":"Muss man die Pinne ständig zu den Segeln hin (nach Lee) drücken, ist das Boot leegierig. Abhilfe: Großsegel bauchiger trimmen und das Gewicht nach vorn verlagern. Das ist das Gegenteil von Frage 291.","stichworte":["Leegierig","Groß bauchiger","Gewicht nach vorn"]},{"nr":293,"teil":"segeln","thema":"trimm","frage":"Warum soll ein gut getrimmtes Segelboot leicht luvgierig sein?","inline":[],"bilder":[],"antworten":["Weil es im Notfall von selbst in den Wind schießt.","Weil es sich so anspruchsvoller steuern lässt.","Weil es so weniger Höhe läuft.","Weil es auf Raumschotkurs mehr Geschwindigkeit läuft."],"erklaerung":"Ein leicht luvgieriges Boot dreht von selbst in den Wind, wenn man die Pinne loslässt. Es bleibt dann stehen, statt unkontrolliert weiterzusegeln, z. B. wenn jemand über Bord geht.","stichworte":["Leicht luvgierig","schießt in den Wind","Sicherheit"]},{"nr":294,"teil":"segeln","thema":"trimm","frage":"Welchen Einfluss hat zunehmende Krängung auf den Trimm des Bootes?","inline":[],"bilder":[],"antworten":["Die Luvgierigkeit nimmt zu.","Die Leegierigkeit nimmt zu.","Keinen.","Bis 45° Krängung nimmt die Luvgierigkeit zu, dann wieder ab."],"erklaerung":"Je stärker das Boot krängt, desto luvgieriger wird es. Der Segeldruck wirkt dann seitlich versetzt und dreht das Boot in den Wind.","stichworte":["Mehr Krängung","mehr Luvgierigkeit"]},{"nr":295,"teil":"segeln","thema":"segelmanoever","frage":"Welche Manöver hat das Boot auf dem eingezeichneten Kurs an den Punkten 1, 2 und 3 gefahren?","inline":[],"bilder":["bilder/Bild-Frage-295.gif"],"antworten":["1 Wende, 2 Halse, 3 Q-Wende.","1 Q-Wende, 2 Halse, 3 Wende.","1 Halse, 2 Wende, 3 Q-Wende.","1 Wende, 2 Q-Wende, 3 Halse."],"erklaerung":"Bei Punkt 1 geht der Bug durch den Wind: Wende. Bei Punkt 2 geht das Heck durch den Wind: Halse. Bei Punkt 3 fährt das Boot statt einer Halse einen Kreis über die Wende, die Q-Wende (Kuhwende).","stichworte":["1 Wende","2 Halse","3 Q-Wende"]},{"nr":296,"teil":"segeln","thema":"segelmanoever","frage":"Was ist mit Schwert und Ruder einer Jolle zu tun, wenn das Boot an einer Boje liegen gelassen wird?","inline":[],"bilder":[],"antworten":["Schwert und Ruderblatt aufholen, damit das Boot frei schwojen kann.","Schwert absenken, Ruder aufholen, damit das Boot frei schwojen kann.","Schwert aufholen, Ruder absenken, damit das Boot frei schwojen kann.","Schwert und Ruder absenken, damit das Boot frei schwojen kann."],"erklaerung":"Liegt die Jolle an der Boje, holt man Schwert und Ruderblatt auf. Dann kann sie frei um die Boje schwojen, ohne dass Schwert oder Ruder hängen bleiben oder beschädigt werden.","stichworte":["Boje","Schwert und Ruder hoch","frei schwojen"]},{"nr":297,"teil":"segeln","thema":"segelmanoever","frage":"Warum ist eine Patenthalse gefährlich?","inline":[],"bilder":[],"antworten":["Es kann zu Verletzungen der Crew, zu Riggschäden und zur Kenterung führen.","Es kann zur plötzlichen Änderung der Ausweichpflicht kommen.","Es kann zum Verlust der Steuerfähigkeit des Fahrzeuges führen.","Es kann erneut eine Patenthalse folgen, wenn nicht sofort abgefallen wird."],"erklaerung":"Bei einer Patenthalse (ungewollte Halse) schlägt der Baum mit voller Wucht auf die andere Seite. Das kann die Crew verletzen, das Rigg beschädigen oder das Boot kentern lassen.","stichworte":["Patenthalse","Baum schlägt über","Verletzung","Kenterung"]},{"nr":298,"teil":"segeln","thema":"segelmanoever","frage":"Ein Segelboot segelt am Wind, plötzlich bricht das Luvwant. Welches Manöver ist sinnvoll?","inline":[],"bilder":[],"antworten":["Wende.","Halse.","Q-Wende.","Aufschießer."],"erklaerung":"Das Luvwant trägt die ganze Last des Mastes. Bricht es, wendet man sofort: Die beschädigte Seite wird zur Leeseite und entlastet, das intakte Want übernimmt.","stichworte":["Luvwant bricht","Wende","Last auf andere Seite"]},{"nr":299,"teil":"segeln","thema":"segelmanoever","frage":"Ein Segelboot segelt bei starkem Wind nur unter Großsegel auf Amwindkurs. Plötzlich bricht das Vorstag. Was ist sofort zu unternehmen?","inline":[],"bilder":[],"antworten":["Abfallen auf Vorwindkurs.","Dichtholen und Anluven.","Einen Aufschießer fahren.","Eine Halse fahren."],"erklaerung":"Das Vorstag hält den Mast nach vorn. Fällt man auf Vorwindkurs ab, drückt der Wind von hinten den Mast nach vorn gegen das Achterstag, und das gebrochene Vorstag wird entlastet.","stichworte":["Vorstag bricht","abfallen auf Vorwind","Achterstag trägt"]},{"nr":300,"teil":"segeln","thema":"segelmanoever","frage":"Ein Segelboot segelt bei starkem Wind nur unter Großsegel auf Amwindkurs. Plötzlich bricht das Vorstag. Womit kann das gebrochene Vorstag schnell provisorisch ersetzt werden?","inline":[],"bilder":[],"antworten":["Durch die Fock oder ein Fall.","Durch die Fockschot oder das Großfall.","Durch die Vor- oder die Achterleine.","Durch die Fockschot oder eine Reffleine."],"erklaerung":"Ein Fall (z. B. das Fockfall) oder die Fock selbst, deren Vorliek mit dem Fall gespannt wird, kann den Mast provisorisch nach vorn halten. Eine Schot ist dafür nicht geeignet.","stichworte":["Vorstag-Ersatz","Fall","Fock"]}]};
